insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('3d74f292-698d-5b70-8b4a-61d1b81dc3a1', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '97aae7d0-af93-5132-ad15-c840e2825cb2', $kuggfri$adhesiv-forslitning$kuggfri$, $kuggfri$Adhesiv förslitning$kuggfri$, $kuggfri$Vid nötningen binds materialen samman med atomära bindningar, och material rycks bort när ytorna glider mot varandra. De två materialen svetsas punktvis samman, och slits isär.$kuggfri$, null, 15, true, $kuggfri$c8933af27$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('c5d3fc0c-c96d-53ef-812b-440f3f7dc952', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '97aae7d0-af93-5132-ad15-c840e2825cb2', $kuggfri$abrasiv-forslitning$kuggfri$, $kuggfri$Abrasiv förslitning$kuggfri$, $kuggfri$Förslitning som fås när ett hårt material/medium avverkar ytan.$kuggfri$, null, 16, true, $kuggfri$c6454d205$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('f00f3ae6-5a05-5a37-b015-ec75bf24f180', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '97aae7d0-af93-5132-ad15-c840e2825cb2', $kuggfri$quiz-vad-ar-sant-for-atombindningar-tva$kuggfri$, $kuggfri$Vilka påståenden om atombindningar är sanna?$kuggfri$, $kuggfri$Keramer har kovalent- eller jonbindning. I metallbindningen lossnar valenselektronerna och bildar ett elektronmoln, vilket ger elektrisk och termisk ledning. Vätebindningar hör tillsammans med van der Waals-bindningar till de svaga bindningarna (t.ex. mellan polymerkedjor), medan jon-, kovalent- och metallbindning är starka. Av bindningstyperna i föreläsningen är det den kovalenta som beskrivs som riktningsberoende.$kuggfri$, null, 17, false, $kuggfri$cb7998a0f$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Keramiska material kan ha jonbindningar.","correct":true},{"text":"Bindningstypen hos metaller ger elektrisk ledningsförmåga.","correct":true},{"text":"De starkaste bindningarna är vätebindningar.","correct":false},{"text":"Jonbindningar och metallbindningar är riktningsberoende.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 1, fråga 1; Canvas, Fo 1 Materialegenskaper och materialgrupper HT25, s. 14, 17; Canvas, Kapitel_04 Elastisk deformation, s. 34$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('ca5c1c46-9751-5cc9-ad3b-eb1921daf262', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '97aae7d0-af93-5132-ad15-c840e2825cb2', $kuggfri$quiz-vad-ar-sant-for-keramiska-material-tva$kuggfri$, $kuggfri$Vilka påståenden om keramiska material är sanna?$kuggfri$, $kuggfri$Keramer är oftast kristallina, med glas som amorft undantag, och de har kovalent- eller jonbindning. Starka bindningar (djup bindningsenergikurva) ger hög smälttemperatur. Keramer är oorganiska föreningar mellan metall och icke-metall, inte föreningar med organiska material, och trots att de är spröda har de bra slitstyrka. Quizens alternativ "Alla keramer är kristallina förutom glas" är omformulerat till "oftast", som det står i föreläsningen.$kuggfri$, null, 18, false, $kuggfri$c5a7a296b$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Keramer är oftast kristallina; glas är ett undantag och är amorft.","correct":true},{"text":"Den starka atombindningen hos keramer ger hög smälttemperatur.","correct":true},{"text":"Keramer är föreningar mellan oorganiska och organiska material.","correct":false},{"text":"Spröda keramer har dålig slitstyrka.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 1, fråga 2; Canvas, Fo 1 Materialegenskaper och materialgrupper HT25, s. 16, 17; Canvas, Fo 7 Styvhet, s. 4$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('e9e8deb4-e530-5098-ac44-4d30bb4ae975', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '97aae7d0-af93-5132-ad15-c840e2825cb2', $kuggfri$quiz-mer-keramer-vad-ar-sant-tva-ratta-svar$kuggfri$, $kuggfri$Keramer: vilka påståenden är sanna?$kuggfri$, $kuggfri$Keramer är elektriskt och termiskt isolerande. De är spröda och tål dragbelastning dåligt men tryckbelastning bättre. Keramiska produkter gjuts inte vanligtvis utan formas av lera eller pulver och sintras vid ca 2/3 av smälttemperaturen. Glas är amorft och mjuknar och kan formas först mellan 800 och 1200 °C, vilket inte är en låg temperatur.$kuggfri$, null, 19, false, $kuggfri$c0cb2f0c6$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Keramer är vanligtvis isolatorer.","correct":true},{"text":"När man konstruerar med keramer bör man eftersträva tryckbelastning.","correct":true},{"text":"Keramer gjuts vanligtvis.","correct":false},{"text":"Glas är en keram med låg smälttemperatur.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 1, fråga 3; Canvas, Fo 1 Materialegenskaper och materialgrupper HT25, s. 17, 18$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('a4015a21-dade-54dc-be85-69c8934db437', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '97aae7d0-af93-5132-ad15-c840e2825cb2', $kuggfri$quiz-vad-ar-sant-for-metaller-tva-ratta-svar$kuggfri$, $kuggfri$Vilka påståenden om metaller är sanna?$kuggfri$, $kuggfri$Spröda material har låg brottseghet, och keramer är spröda medan metaller inte är det. Att metaller kan gjutas står bland metallernas egenskaper i föreläsningen. Stål är järn och kol (Fe + C), och även andra metaller korroderar, t.ex. magnesium, som bildar ett poröst oxidskikt och därför har sämre korrosionsskydd. Quizens alternativ är förenklade: "högre brottseghet än plaster och keramer" är begränsat till keramer och "Alla metaller kan gjutas" till "Metaller kan gjutas", eftersom föreläsningstexten bara belägger det.$kuggfri$, null, 20, false, $kuggfri$c968e66af$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Metaller har generellt sett högre brottseghet än keramer.","correct":true},{"text":"Metaller kan gjutas.","correct":true},{"text":"Stål är en legering av järn och fosfor.","correct":false},{"text":"Den enda metall som korroderar är stål.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 1, fråga 9; Canvas, Fo 1 Materialegenskaper och materialgrupper HT25, s. 17, 19, 20; Canvas, Kapitel_02 Material och tillverkning databaser, s. 26; Canvas, Fo 13 Aluminium och andra metaller, s. 11$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('6d5e9686-51c1-5107-924a-4208e44ec6e3', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '97aae7d0-af93-5132-ad15-c840e2825cb2', $kuggfri$quiz-vad-ar-sant-for-kompositer-tva-ratta$kuggfri$, $kuggfri$Vilka påståenden om kompositer är sanna?$kuggfri$, $kuggfri$En komposit är en kombination av två eller flera material, t.ex. plast och kolfiber, och förstärkningen kan vara långa fiber, korta fiber eller partiklar. Kompositens densitet beror på volymandelarna och densiteterna hos de ingående materialen: enligt blandningsregeln, $\rho = f\rho_A + (1-f)\rho_B$, viktas densiteterna med volymandelarna, så kompositens densitet hamnar mellan de ingående materialens och inte under båda. Återvinning av kompositer beskrivs i föreläsningen som en utmaning.$kuggfri$, null, 21, false, $kuggfri$c98d9a887$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"En komposit består vanligen av två olika material.","correct":true},{"text":"Förstärkningen i en komposit kan bestå av långa fiber, korta fiber eller partiklar.","correct":true},{"text":"En komposit har alltid lägre densitet än vart och ett av de ingående materialen.","correct":false},{"text":"Kompositer är oftast lätta att återvinna.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 1, fråga 10; Canvas, Fo 1 Materialegenskaper och materialgrupper HT25, s. 11, 23; Canvas, Fo 7 Styvhet, s. 3; Canvas, Kapitel_04 Elastisk deformation, s. 27; Canvas, Short_dictionary_ v2026, s. 12$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('6102de48-4de8-5da3-8337-f9a86dd30efa', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '97aae7d0-af93-5132-ad15-c840e2825cb2', $kuggfri$designbegransande-egenskap$kuggfri$, $kuggfri$Designbegränsande egenskap$kuggfri$, $kuggfri$En egenskap som avgör om ett material är lämpligt utifrån designkraven. Exempel: för ett flygplan är hållfasthet, styvhet och seghet designbegränsande; är någon av dem för låg kan flygplanet inte flyga.$kuggfri$, null, 22, false, $kuggfri$c0da361b2$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_01 Intro till Material, s. 26$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('0643ae74-6de7-559d-95f2-940d3fbf10b4', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '97aae7d0-af93-5132-ad15-c840e2825cb2', $kuggfri$sex-materialfamiljer$kuggfri$, $kuggfri$Vilka av följande är egna familjer i kursens indelning i sex materialfamiljer?$kuggfri$, $kuggfri$De sex familjerna är metaller (med legeringar), keramer, glas, polymerer, elastomerer och hybrider (t.ex. kompositer). I den grövre indelningen i fyra grupper räknas glas till keramerna och elastomerer till polymererna. Legeringar hör till metallfamiljen och termoplaster är en undergrupp till polymererna, så ingen av dem är en egen familj.$kuggfri$, null, 23, false, $kuggfri$c7519eeac$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Glas","correct":true},{"text":"Elastomerer","correct":true},{"text":"Legeringar","correct":false},{"text":"Termoplaster","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_02 Material och tillverkning databaser, s. 3, 5; Canvas, Fo 1 Materialegenskaper och materialgrupper HT25, s. 15$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('2be1d410-d260-5f60-b5a3-198d0c0cf76a', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$vilka-ar-de-olika-stegen-i$kuggfri$, $kuggfri$Vilka är de olika stegen i materialvalsprocessen?$kuggfri$, $kuggfri$1. Översätta
2. Sålla
3. Rangordna
4. Sök dokumentation

Utöver de fyra stegen itererar man: materialvalet behöver ofta förfinas i flera steg innan man hittar en bra lösning.$kuggfri$, null, 24, false, $kuggfri$c211c3c09$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: iteration stod som ett femte steg, men strategin har fyra steg och iterationen är ett tillägg; Canvas, Kapitel_03 Materialval, s. 26, 42; Canvas, Ashby et al Materials 3 utgavan PRELIMINAR Lasanvisning och detaljerade larmal Kap 1-12, s. 2$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('a3576869-1462-5637-89ae-52b6fa1768a4', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$beskriv-vad-man-gor-i$kuggfri$, $kuggfri$Beskriv vad man gör i materialvalssteget: "Översätta".$kuggfri$, $kuggfri$Översätta krav på komponenten till krav på materialet:

* Funktion: talar om materialets huvudsakliga funktion i
komponenten.
Ex. leda värme, elektrisk isolering,
balk i böjning som inte plasticerar.
* Krav: egenskaper som måste vara uppfyllda för att komponenten skall fungera.
Ex. användningstemperatur, tåla
vatten, viss brottseghet
* Mål: egenskaper hos komponenten som vi vill optimera.
Ex. vikt, pris, miljöbelastning
* Fria variabler: variabler hos komponenten som vi kan ändra.
Ex. tvärsnitt, material$kuggfri$, null, 25, true, $kuggfri$c24260826$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('a7bb3469-b345-53df-8186-e4c1cb157b04', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$beskriv-vad-man-gor-i-2$kuggfri$, $kuggfri$Beskriv vad man gör i materialvalssteget: "Sålla".$kuggfri$, $kuggfri$Ta bort alla material som inte fyller kraven. (Använder vi dessa material så kommer komponenten inte att fungera som vi vill.) Materialegenskaper som vi använder i målfunktionen bör vi inte heller använda vid sållningen. (Ex. inget krav på densitet om målet är låg vikt.)$kuggfri$, null, 26, true, $kuggfri$cdb622b81$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('3376edce-7584-52be-92d7-dcb736609e56', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$beskriv-vad-man-gor-i-3$kuggfri$, $kuggfri$Beskriv vad man gör i materialvalssteget: "Rangordna".$kuggfri$, $kuggfri$* Använd funktion, mål och fria variabler för att bestämma
materialindex.
* Materialindex = numeriskt värde som beskriver hur bra ett material uppfyller målen!
* Ta hjälp av materialindexet för att rangordna materialen.
Ex: E-modul/pris, E-modul^(1/2)/densitet$kuggfri$, null, 27, true, $kuggfri$c563a2f62$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('6a60025f-71d7-542e-98c2-4fba34214cb2', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$beskriv-vad-man-gor-i-4$kuggfri$, $kuggfri$Beskriv vad man gör i materialvalssteget: "Sök dokumentation".$kuggfri$, $kuggfri$Leta i dokumentation (handböcker, artiklar, standarder m.m.) för att se om det finns erfarenheter av materialet i liknande tillämpningar.$kuggfri$, null, 28, true, $kuggfri$c866b5ae0$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('352114ee-0597-5fa4-b1f4-d4c6f6844374', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$beskriv-vad-man-gor-i-5$kuggfri$, $kuggfri$Vad innebär det att iterera materialvalet, och varför är det viktigt?$kuggfri$, $kuggfri$Materialvalet måste ofta förfinas och förbättras i flera steg innan man hittar en bra lösning. Det är bra att först börja med materialgrupperna och sedan begränsa sig. I CES (Granta EduPack) börjar man med nivå 1 för att hitta materialgrupper och går sedan vidare till nivå 2 och 3.$kuggfri$, null, 29, false, $kuggfri$c77bc8c03$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: kortet sa att man utökar mängden material efter första iterationen, men kursen säger att man börjar brett med materialgrupperna och sedan begränsar sig; Canvas, Kapitel_03 Materialval, s. 26, 42; Canvas, Fo 2 Materialval, s. 9$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('7c7811c1-f9b4-53d9-b8cf-7f11fbb36aaa', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$vad-har-lastfall-for-inverkan-pa$kuggfri$, $kuggfri$Vad har lastfall för inverkan på materialindexet?$kuggfri$, $kuggfri$Lastfallet bestämmer vilket materialindex som är bäst lämpat för situationen. Materialindexet beskriver i sin tur hur bra ett material presterar i det aktuella lastfallet och kan därför med fördel användas för att rangordna en mängd material.$kuggfri$, null, 30, false, $kuggfri$cc40f89c4$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('a446e3f7-5f57-5f56-987d-dbde37915688', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$vad-ar-ett-lastfall-och-varfor-ar-det$kuggfri$, $kuggfri$Vad är ett lastfall och varför är det viktigt i materialvalsprocessen?$kuggfri$, $kuggfri$* Ett lastfall är en isolerad belastningssituation som materialet kan utsättas för.
* Ex: En stång i tryck/drag/vridspänning, en balk i böjning/knäckning eller utsatt för utbredd last, ett tryckkärl utsatt för tryckskillnader.
* Lastfallet (tillsammans med vad som ska optimeras) bestämmer vilket materialindex som är lämpligt. Alla fall av böjning av en balk har t.ex. samma inverkan av materialet, så för materialvalet behöver man bara bestämma typen av lastfall.
* Exempel vid minsta vikt: dragstång $\rho/E$ (styvhet) eller $\rho/\sigma_y$ (hållfasthet), balk i böjning $\rho/E^{1/2}$ eller $\rho/\sigma_y^{2/3}$; välj material med lägsta värde.$kuggfri$, null, 31, false, $kuggfri$cddf9c0d0$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: påståendet att man ska använda det lastfall som förekommer oftast saknar stöd i kursmaterialet och är struket; dubbletten vad-har-lastfall-for-inverkan-pa är inaktiverad; Canvas, Fo 7 Styvhet, s. 15, 17; Canvas, Kapitel_03 Materialval, s. 33, 35$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('c67240d8-2f57-5d95-902d-05aae6a70542', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$beskriv-ingaende-vad-ett-materialindex$kuggfri$, $kuggfri$Beskriv ingående vad ett materialindex är och hur det används.$kuggfri$, $kuggfri$* Ett numeriskt värde M som talar om hur effektivt ett material är i
ett visst lastfall och en viss form
* För att bestämma materialindex behöver vi veta vilken egenskap som skall optimeras (ex: styvhet, pris, vikt) och lastfall
* Detta bestäms av funktion, mål och fria variabler från
översättningen
* Materialindex används för att rangordna material i materialvalet$kuggfri$, null, 32, true, $kuggfri$cfccc05c5$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('55f44335-263b-5f37-aa6f-9617704990b5', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$nar-ska-man-anvanda-materialindex-for$kuggfri$, $kuggfri$När ska man använda materialindex för styvhet, kontra sträckgräns?$kuggfri$, $kuggfri$* Använd materialindex för styvhet
om deformationen är
dimensionerande. (Krav på max
deformation)
* Använd materialindex för
sträckgräns om last utan plasticering
är dimensionerande. (Krav på max
spänning)$kuggfri$, null, 33, true, $kuggfri$ca46196e2$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('f9ca0bd4-1ef1-503d-9cec-63f4769c74c7', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$quiz-materialval-vad-ar-sant-ett-ratt-svar$kuggfri$, $kuggfri$Materialval: vilket påstående är sant?$kuggfri$, $kuggfri$Material, form och process samverkar: en specificerad process begränsar valet av material och form. Minimal miljöpåverkan kan vara ett mål i materialvalet och uppskattas med en snabb eco audit, utan fullständig livscykelanalys. Sållningen tar bara bort material som inte klarar kraven och rangordningen avgör vilket av de kvarvarande som är bäst, så ett stort antal kvar är inget mål i sig. Fria variabler kan vara t.ex. tvärsnitt och material; i kursens kylflänsexempel är valet av material den enda fria variabeln.$kuggfri$, null, 34, false, $kuggfri$cc7706a33$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Materialvalet påverkas av möjliga tillverkningsmetoder.","correct":true},{"text":"Miljöbelastningen kan inte tas med i materialvalet utan kräver en livscykelanalys.","correct":false},{"text":"Ju fler material man har kvar efter sållningen, desto bättre.","correct":false},{"text":"Om tvärsnittet inte är en fri variabel kan man inte göra ett materialval.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 1, fråga 4; Canvas, Kapitel_03 Materialval, s. 8, 9, 25, 28, 43; Canvas, Fo 2 Materialval, s. 5, 6, 7$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('a43cf025-5dd7-5279-947c-9d33da39d142', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$quiz-materialval-vad-ar-sant-tva-ratta-svar$kuggfri$, $kuggfri$Materialval: vilka påståenden är sanna?$kuggfri$, $kuggfri$Sållningen tar bort alla material som inte fyller kraven, eftersom komponenten annars inte fungerar. De material som finns kvar uppfyller kraven och kan användas; rangordningen med materialindex avgör sedan vilket som är bäst. Översättning innebär att krav på komponenten översätts till funktion, krav, mål och fria variabler, och fria variabler är variabler hos komponenten som vi kan ändra, t.ex. tvärsnitt och material. Quizens alternativ "Alla material som är kvar efter att vi sållat kan användas för att göra produkten" är omformulerat så att det tydligt gäller kraven.$kuggfri$, null, 35, false, $kuggfri$c41043ef0$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Material som inte klarar kraven kan inte användas i komponenten.","correct":true},{"text":"Material som finns kvar efter sållningen uppfyller kraven och kan därför användas i komponenten.","correct":true},{"text":"Med översättning menas att översätta materialkraven till danska.","correct":false},{"text":"Fria variabler är sådant som inte är nödvändigt.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 1, fråga 5; Canvas, Fo 2 Materialval, s. 5, 6, 7$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('6b069be9-1fbe-56fa-99b1-7f1c4f73daab', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$quiz-for-att-bestamma-materialindex-behover$kuggfri$, $kuggfri$Vad behöver man veta för att bestämma ett materialindex?$kuggfri$, $kuggfri$Vilket materialindex som gäller bestäms av vilken egenskap som ska optimeras (målet, t.ex. låg vikt) och av lastfallet, dvs. av funktion, mål och fria variabler från översättningen. Materialdata som densitet, pris, sträckgräns och E-modul behövs först när indexet räknas ut för de olika materialen, inte för att bestämma vilket index som ska användas.$kuggfri$, null, 36, false, $kuggfri$c42592bb6$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Lastfall","correct":true},{"text":"Mål","correct":true},{"text":"Densitet och pris","correct":false},{"text":"Sträckgräns och E-modul","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 3, fråga 8; Canvas, Fo 7 Styvhet, s. 17; Canvas, Kapitel_03 Materialval, s. 26$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('496300cc-3655-5fe5-be03-5041ae662dd7', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$quiz-materialindex-vad-ar-ratt-2-ratta-svar$kuggfri$, $kuggfri$Materialindex: vilka påståenden är rätt?$kuggfri$, $kuggfri$Materialindex rangordnar material efter hur väl de uppfyller målet; kraven används i sållningen, inte i rangordningen. Ett index kan vara en enda egenskap (t.ex. bara E om prestandan mäts som en balks styvhet) eller en kombination som $E/\rho$ eller $\sigma_y/\rho$, så det behöver inte innehålla densiteten. Finns det flera mål, t.ex. låg vikt och lågt pris, kan man behöva flera index och jämföra alternativen i ett paretodiagram.$kuggfri$, null, 37, false, $kuggfri$c21e338a7$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Materialindex är ett numeriskt värde som används för att rangordna material efter hur bra de uppfyller kraven.","correct":false},{"text":"Ett materialindex kan innehålla en eller flera materialegenskaper.","correct":true},{"text":"Man kan behöva använda flera materialindex för att komma fram till ett bra materialval.","correct":true},{"text":"Alla materialindex måste innehålla materialets densitet.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 3, fråga 9; Canvas, Fo 2 Materialval, s. 6, 7; Canvas, Kapitel_03 Materialval, s. 35; Canvas, Kapitel_03 Materialval Repetition och Inlamningsuppgift, s. 24, 25; Canvas, performance-indices-booklet-bokpeien22, s. 2$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('51c51044-1ab1-5620-9eb5-44dae79022db', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$materialval-krav-eller-mal$kuggfri$, $kuggfri$Vilka av följande är krav (och inte mål) i en översättning?$kuggfri$, $kuggfri$Krav är egenskaper som måste vara uppfyllda för att komponenten ska fungera, t.ex. användningstemperatur, att tåla vatten eller en viss brottseghet. Mål är egenskaper hos komponenten som vi vill optimera (minimera eller maximera), t.ex. vikt, pris och miljöbelastning. Kraven används i sållningen och målen i rangordningen.$kuggfri$, null, 38, false, $kuggfri$cd0241b72$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Tåla vatten","correct":true},{"text":"Viss brottseghet","correct":true},{"text":"Låg vikt","correct":false},{"text":"Lågt pris","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Fo 2 Materialval, s. 5; Canvas, Kapitel_03 Materialval, s. 24, 25$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('1ea82806-66b6-5ec9-b9fd-723706b2cc07', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$sallning-inget-krav-pa-malegenskap$kuggfri$, $kuggfri$Om målet är låg vikt bör man inte ställa något krav på densiteten vid sållningen.$kuggfri$, $kuggfri$Materialegenskaper som ingår i målfunktionen ska inte användas vid sållningen. Densiteten hanteras i stället i rangordningen, via materialindexet (t.ex. $\rho/\sigma_y$ för en lätt och stark dragstång).$kuggfri$, null, 39, false, $kuggfri$cc2fb3d30$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Fo 2 Materialval, s. 6$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('33a3ee5d-2ee3-59e8-8b86-7df602bdcdfd', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$materialindex-latt-stark-dragstang$kuggfri$, $kuggfri$Lätt och stark dragstång (får inte plasticera): vilket materialindex ska minimeras?$kuggfri$, $kuggfri$För en dragstång med minsta massa gäller $\rho/\sigma_y$ när hållfastheten (ingen plasticering) är dimensionerande och $\rho/E$ när styvheten är det. $\rho/E^{1/2}$ och $\rho/\sigma_y^{2/3}$ är indexen för en lätt balk i böjning (styvhet respektive hållfasthet). Man väljer material med lägsta värde på indexet, vilket är samma sak som högsta $\sigma_y/\rho$.$kuggfri$, null, 40, false, $kuggfri$c0074bd46$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"$\\rho/\\sigma_y$","correct":true},{"text":"$\\rho/E$","correct":false},{"text":"$\\rho/E^{1/2}$","correct":false},{"text":"$\\rho/\\sigma_y^{2/3}$","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_03 Materialval, s. 35, 37$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('23fbd209-9bc2-5c01-841f-42299750f3c9', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$materialindex-latt-styv-balk$kuggfri$, $kuggfri$Lätt och styv balk i böjning (tvärsnittsarean fri): vilket materialindex ska minimeras?$kuggfri$, $kuggfri$För en lätt och styv balk i böjning är indexet $\rho/E^{1/2}$ (minimeras), dvs. välj material med högsta $E^{1/2}/\rho$. $\rho/E$ gäller en styv dragstång, $\rho/E^{1/3}$ en styv panel i böjning och $\rho/\sigma_y^{2/3}$ en balk där hållfastheten är dimensionerande.$kuggfri$, null, 41, false, $kuggfri$ce14f5b3c$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"$\\rho/E^{1/2}$","correct":true},{"text":"$\\rho/E$","correct":false},{"text":"$\\rho/E^{1/3}$","correct":false},{"text":"$\\rho/\\sigma_y^{2/3}$","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_03 Materialval, s. 35, 36; Canvas, Fo 7 Styvhet, s. 20$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('40e424cb-f98e-59c1-b52d-a23618a555f2', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$harled-materialindex-dragstang$kuggfri$, $kuggfri$Härled materialindex för en lätt och stark dragstång med given längd L och last F.$kuggfri$, $kuggfri$Översättning: funktion dragstång; mål minsta massa; krav längden L given och stången får inte gå sönder (plasticera) under lasten F; fria variabler materialet och tvärsnittsarean A.

1. Massan: $m = A L \rho$
2. Kravet: $F/A \le \sigma_y$, dvs. minsta area $A = F/\sigma_y$
3. Eliminera A: $m = F L \,(\rho/\sigma_y)$

F och L är givna, så massan blir minst för det material som har lägst $\rho/\sigma_y$. Det är materialindexet.$kuggfri$, null, 42, false, $kuggfri$c869b1719$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_03 Materialval, s. 37; Canvas, Ashby et al Materials 3 utgavan PRELIMINAR Lasanvisning och detaljerade larmal Kap 1-12, s. 4$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('bf4ddb26-ea98-529a-a250-f0104833d6fa', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$materialindex-lutning-bubbeldiagram$kuggfri$, $kuggfri$I ett diagram med $\log E$ mot $\log \rho$ ligger material med samma värde på $E^{1/2}/\rho$ på en linje. Vilken lutning har linjen?$kuggfri$, $kuggfri$Om $E^{1/2}/\rho = C$ blir $E = C^2\rho^2$, och med logaritmer $\log E = 2\log\rho + 2\log C$: en rät linje med lutningen 2. Alla material på linjen har samma indexvärde och är lika bra; material längre upp till vänster är bättre.$kuggfri$, null, 43, false, $kuggfri$c0d453e45$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"2","correct":true},{"text":"1","correct":false},{"text":"1/2","correct":false},{"text":"3","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_03 Materialval, s. 36; Canvas, Fo 7 Styvhet, s. 23$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('76ebd325-9294-56c4-9449-b0140ae81683', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$konceptdesign-materialdata$kuggfri$, $kuggfri$I konceptfasen av designen behövs detaljerade data för ett enda specifikt material.$kuggfri$, $kuggfri$I konceptdesign står alla material till förfogande och man använder data med låg precision, enkla egenskaper som är typiska för varje materialgrupp. I primärdesign jämförs ett fåtal material med mer detaljerade data, och först i detaljdesignen behövs välspecificerade data för ett material och en process.$kuggfri$, null, 44, false, $kuggfri$cbb988019$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_03 Materialval, s. 3, 8$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('cad2d06f-432d-5d94-b874-d03e48bca6b2', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'e2f719bb-f9eb-549f-acbb-a21921adb0bc', $kuggfri$paretoyta-materialval$kuggfri$, $kuggfri$Vad är en Paretoyta (paretodiagram) i materialval och när används den?$kuggfri$, $kuggfri$Den används när det finns en konflikt mellan önskemål (mål), t.ex. låg vikt och lågt pris, och det är oklart vilken parameter som är viktigast. Ett paretodiagram visar vilka alternativ som är de bästa kompromisserna mellan målen.$kuggfri$, null, 45, false, $kuggfri$c2e400b70$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_03 Materialval Repetition och Inlamningsuppgift, s. 24, 25$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('71baf9d6-ddeb-5b91-b705-dfb55d49290b', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'd63240aa-9a49-52d8-8170-a0180269bc83', $kuggfri$vad-ar-skillnaden-mellan-kristallin-och$kuggfri$, $kuggfri$Vad är skillnaden mellan kristallin- och amorf mikrostruktur?$kuggfri$, $kuggfri$* Kristallin = ordnad struktur
  - Metaller, keramer, vissa polymerer
* Amorf = oordnad struktur
  - Polymerer, glas$kuggfri$, null, 46, true, $kuggfri$ca25bd769$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('71bc6e75-1c5f-580e-ab9e-43cdbb002348', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'd63240aa-9a49-52d8-8170-a0180269bc83', $kuggfri$vad-ar-en-enhetscell-namn-minst-tva$kuggfri$, $kuggfri$Vad är en enhetscell? Nämn minst två olika typer av enhetsceller.$kuggfri$, $kuggfri$* En liten volym som kan beskriva hela kristallen
* I varje punkt sitter det en atom eller molekyl
* Sex parametrar: 3 längder, 3 vinklar

Ex: FCC (Face Centered Cubic), BCC (Body Centered Cubic), Triclinic, Simple Cubic, Close-Packed Hexagonal.$kuggfri$, null, 47, true, $kuggfri$c5e06cd5c$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('488e66a6-cc96-548e-b7d8-bf2bf19fe9fe', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'd63240aa-9a49-52d8-8170-a0180269bc83', $kuggfri$vad-kannetecknar-enhetscellen-fcc$kuggfri$, $kuggfri$Vad kännetecknar enhetscellen: "FCC"?$kuggfri$, $kuggfri$* Face centered cubic
* Ytcentrerad kubisk
* Ex: Al, Cu, Ni, Au, Ag, austenitiskt rostfritt stål (austenit = FCC-järn)
* Kantlängd a, vinkel 90 grader
* Tätpackad ytdiagonal
* Tätpackad struktur: packningsgrad 0,74, staplingsföljd ABCABC$kuggfri$, null, 48, false, $kuggfri$c47afdbfc$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: "rostfritt stål" som exempel gäller bara austenitiskt rostfritt stål, eftersom det även finns ferritiska och martensitiska rostfria stål; packningsgrad tillagd; Canvas, GLU 01 Kristallstrukturer, s. 11, 15; Canvas, Fo 12 Stal, s. 28; Canvas, Short_dictionary_ v2026, s. 2$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('e0c74db4-eaf6-56f1-940d-2d603cf7e3fd', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'd63240aa-9a49-52d8-8170-a0180269bc83', $kuggfri$vad-kannetecknar-enhetscellen-bcc$kuggfri$, $kuggfri$Vad kännetecknar enhetscellen: "BCC"?$kuggfri$, $kuggfri$* Body centered cubic
* Rymdcentrerad kubisk
* Ex: Fe (ferrit, $\alpha$-järn) från rumstemperatur upp till ca 913 °C; däröver är järnet FCC (austenit). Nära smältpunkten (1394–1538 °C) är järnet åter BCC, $\delta$-ferrit.
* Kantlängd a, vinkel 90 grader
* Tätpackad rymddiagonal
* Inte tätpackad struktur: packningsgrad 0,68$kuggfri$, null, 49, false, $kuggfri$c7f553ac6$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: "Ex: Fe" angavs utan temperatur, men järn är BCC (ferrit) bara upp till ca 913 °C och därefter FCC (austenit); packningsgrad tillagd; Canvas, GLU 01 Kristallstrukturer, s. 2, 12, 16; Canvas, Short_dictionary_ v2026, s. 6; Canvas, Lab_PM_M2_v2026, s. 4$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('affc638b-908b-5e1c-ba33-b645f4bb8fa3', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'd63240aa-9a49-52d8-8170-a0180269bc83', $kuggfri$det-finns-olika-typer-av-hal-i$kuggfri$, $kuggfri$Det finns olika typer av hål i kristallstrukturer, vad innebär detta?$kuggfri$, $kuggfri$* Mellan atomerna finns
hålrum med olika form
och storlek
* Avgör om små atomer
kan lösas in i
materialet (ex. C i Fe)$kuggfri$, null, 50, true, $kuggfri$c0ae0eb91$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('05549803-b3c4-5c64-9b20-5bb35005788b', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'd63240aa-9a49-52d8-8170-a0180269bc83', $kuggfri$millerindex-beskriv-kortfattat-vad-det$kuggfri$, $kuggfri$Millerindex: Beskriv kortfattat vad det är och hur det tas fram.$kuggfri$, $kuggfri$Millerindex beskriver ett atomplans orientering i kristallen (jämför med planets normal). Enhetscellen definierar koordinatsystemet. Så tas planets index fram:
1. Bestäm planets skärningar med koordinataxlarna
2. Invertera
3. Gör heltalig → Millerindex (hkl)

(hkl) = specifikt plan
{hkl} = familj av plan

Riktningar beskrivs med riktningsvektorer i samma koordinatsystem, omvandlade till heltal (bara riktningen spelar roll, inte längden). I GLU 1 kallas de "Millerindex för riktningar", även kallat riktningsindex:
[hkl] = specifik riktning
\<hkl> = familj av riktningar$kuggfri$, null, 51, false, $kuggfri$cfd9c8ce9$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: kortet påstod att riktningsindex inte kallas Millerindex, men GLU 1 2026 kallar dem "Millerindex för riktningar"; kortet beskrev också planets position i stället för orientering; Canvas, GLU 01 Kristallstrukturer, s. 19, 20$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('eaa580ff-ee2d-5af3-b2b2-7bc74bd0971f', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'd63240aa-9a49-52d8-8170-a0180269bc83', $kuggfri$kristallin$kuggfri$, $kuggfri$Kristallin$kuggfri$, $kuggfri$Atomer eller molekyler som sitter i en ordnad struktur.$kuggfri$, null, 52, true, $kuggfri$c508d9b78$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('11b32f49-60f5-5226-9df2-54ce6a5fed20', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'd63240aa-9a49-52d8-8170-a0180269bc83', $kuggfri$quiz-kristaller-nar-man-beskriver-plan-och$kuggfri$, $kuggfri$Vilka beteckningar anger ett specifikt atomplan eller en specifik riktning i en kristall?$kuggfri$, $kuggfri$(hkl) betecknar ett specifikt plan och [hkl] en specifik riktning. {hkl} betecknar en familj av plan, och \<hkl> en familj av riktningar.$kuggfri$, null, 53, false, $kuggfri$c97dedb48$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"(hkl)","correct":true},{"text":"[hkl]","correct":true},{"text":"{hkl}","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 2, fråga 1; Canvas, GLU 01 Kristallstrukturer, s. 19, 20$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('206fab61-c555-516f-b815-16e0bc52d222', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'd63240aa-9a49-52d8-8170-a0180269bc83', $kuggfri$quiz-kristallina-eller-amorfa-material-tva$kuggfri$, $kuggfri$Kristallina och amorfa material: vilka påståenden är sanna?$kuggfri$, $kuggfri$De flesta metaller är kristallina, med ett regelbundet upprepat mönster av atomer. Glas är amorft (amorf kiseldioxid är basen i de flesta glas), medan keramer i övrigt oftast är kristallina. Polymerer finns både som amorfa och som kristallina (vissa polymerer). Quizens alternativ "Metaller är alltid kristallina" är ändrat till "i regel", eftersom GLU 1 skriver "de flesta metaller".$kuggfri$, null, 54, false, $kuggfri$cc47b5c77$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Metaller är i regel kristallina.","correct":true},{"text":"Kristallglas är den enda typen av glas som är kristallin.","correct":false},{"text":"Polymerer kan vara både amorfa och kristallina.","correct":true},{"text":"Alla keramer förutom glas är amorfa.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 2, fråga 2; Canvas, GLU 01 Kristallstrukturer, s. 11; Canvas, Fo 3 Kristallstruktur, s. 13; Canvas, Fo 1 Materialegenskaper och materialgrupper HT25, s. 17; Canvas, Kapitel_04 Elastisk deformation, s. 40$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('098b516f-8838-56e5-ad6a-4133a392b2a0', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'd63240aa-9a49-52d8-8170-a0180269bc83', $kuggfri$quiz-kristaller-och-enhetsceller-tva-ratt$kuggfri$, $kuggfri$Kristaller och enhetsceller: vilka påståenden är sanna?$kuggfri$, $kuggfri$Tätpackade plan är viktiga för att glidplanen, där dislokationer rör sig vid plastisk deformation, är de mest tätpackade planen. En enhetscell är en modell: den minsta volym som, upprepad i rummet, beskriver hela kristallen. Amorfa material saknar ordnad struktur (ingen fjärrordning) och beskrivs därför inte med enhetsceller. FCC har packningsgraden 0,74 och är tätpackad, BCC har 0,68. Quizens alternativ "Enhetsceller ... finns inte i verkligheten" är omformulerat efter föreläsningens definition, som inte säger så.$kuggfri$, null, 55, false, $kuggfri$c9153b542$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Tätpackade atomplan är viktiga eftersom det är där materialet spricker.","correct":false},{"text":"Enhetscellen är ett sätt att beskriva en kristall: den minsta volym som kan beskriva hela kristallen.","correct":true},{"text":"För att beskriva ett amorft material behövs speciella enhetsceller med fler atomer.","correct":false},{"text":"FCC-strukturen är tätpackad men inte BCC-strukturen.","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 2, fråga 3; Canvas, GLU 01 Kristallstrukturer, s. 10, 11, 12; Canvas, Kapitel_06 Plasticitet och Duktilitet, s. 28; Canvas, Short_dictionary_ v2026, s. 1$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('c472c5d1-62bf-5fa9-a2bf-8c27395c4616', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'd63240aa-9a49-52d8-8170-a0180269bc83', $kuggfri$tatpackade-strukturer-fcc-hcp$kuggfri$, $kuggfri$Vilka strukturer är tätpackade (packningsgrad 0,74)?$kuggfri$, $kuggfri$FCC och HCP är båda tätpackade med packningsgraden 0,74; de skiljer sig i staplingsföljden av de tätpackade skikten (ABCABC för FCC, ABAB för HCP). BCC har packningsgraden 0,68 och en amorf struktur högst 0,64.$kuggfri$, null, 56, false, $kuggfri$c36151ac7$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"FCC","correct":true},{"text":"HCP","correct":true},{"text":"BCC","correct":false},{"text":"Amorf struktur","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, GLU 01 Kristallstrukturer, s. 11, 12; Canvas, Kapitel_04 Elastisk deformation, s. 37$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('f427d509-8766-5146-9af2-585dc946747b', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'd63240aa-9a49-52d8-8170-a0180269bc83', $kuggfri$staplingsfoljd-abcabc$kuggfri$, $kuggfri$Tätpackade atomskikt staplas i följden ABCABC. Vilken struktur ger det?$kuggfri$, $kuggfri$Staplingsföljden ABCABC ger FCC och ABAB ger HCP; båda är tätpackade med packningsgraden 0,74. BCC har en ABAB-följd av skikt som inte är fullt tätpackade (packningsgrad 0,68), och en amorf struktur saknar regelbunden stapling.$kuggfri$, null, 57, false, $kuggfri$cecf44d94$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"FCC","correct":true},{"text":"HCP","correct":false},{"text":"BCC","correct":false},{"text":"Amorf struktur","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, GLU 01 Kristallstrukturer, s. 11, 12$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('1115db9a-30f5-5ce7-bb8a-aebc23c81397', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'd63240aa-9a49-52d8-8170-a0180269bc83', $kuggfri$mikroskopi-lom-sem-tem$kuggfri$, $kuggfri$Vilka påståenden om mikroskopi av metaller stämmer?$kuggfri$, $kuggfri$Optiskt mikroskop används för att studera mikrostrukturen på kapade, slipade, polerade och etsade prover. SEM ger större skärpedjup och mycket högre förstoring och används t.ex. för brottytor. I TEM undersöker man bara en liten tunn skiva, och där syns dislokationer.$kuggfri$, null, 58, false, $kuggfri$cecc3a1f1$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"I transmissionselektronmikroskop (TEM) blir dislokationer synliga eftersom gittret är lokalt deformerat.","correct":true},{"text":"I optiskt mikroskop studeras plana, polerade och etsade prover, där t.ex. korngränser och porer syns.","correct":true},{"text":"I TEM undersöker man hela komponenter utan provberedning.","correct":false},{"text":"Svepelektronmikroskop (SEM) har mindre skärpedjup och lägre förstoring än optiskt mikroskop.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, GLU 01 Kristallstrukturer, s. 7, 8, 9$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('d5ed15a7-54b9-5dbb-a152-1d26fbb48d08', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'd63240aa-9a49-52d8-8170-a0180269bc83', $kuggfri$e-modul-enkristall-riktningsberoende$kuggfri$, $kuggfri$En enkristall har samma E-modul i alla kristallriktningar.$kuggfri$, $kuggfri$E-modulen är riktningsberoende: en enkristall har olika styvhet i olika kristallografiska riktningar. I en polykristall med slumpmässigt orienterade korn jämnas det ut, så att styvheten blir i medeltal isotrop.$kuggfri$, null, 59, false, $kuggfri$c7f2393c8$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, GLU 01 Kristallstrukturer, s. 21; Canvas, Kapitel_04 Elastisk deformation, s. 12$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('9d97bfc8-3792-568e-87aa-24834ac6ac79', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'd63240aa-9a49-52d8-8170-a0180269bc83', $kuggfri$millerindex-berakna-plan$kuggfri$, $kuggfri$Ett plan skär x-axeln i 1/2, y-axeln i 1 och är parallellt med z-axeln. Vilket Millerindex har planet?$kuggfri$, $kuggfri$Skärningarna är 1/2, 1 och ∞ (parallellt med z). Inverterade blir de 2, 1 och 0, som redan är heltal, så planet är (210). (120) är i stället planet som skär x-axeln i 1 och y-axeln i 1/2, dvs. x och y omkastade.$kuggfri$, null, 60, false, $kuggfri$cbc0cd5e4$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"(210)","correct":true},{"text":"(120)","correct":false},{"text":"(100)","correct":false},{"text":"(021)","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, GLU 01 Kristallstrukturer, s. 19$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('3c0c8fcc-f235-5abb-9942-81114bd817e0', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'd63240aa-9a49-52d8-8170-a0180269bc83', $kuggfri$riktningsindex-berakna$kuggfri$, $kuggfri$En riktning går från origo till punkten (1/2, 1, 0) i enhetscellen. Vilket riktningsindex har den?$kuggfri$, $kuggfri$Riktningsvektorn är (1/2, 1, 0). Riktningar omvandlas alltid till heltal, eftersom bara riktningen spelar roll och inte längden: multiplicera med 2 och riktningen blir [120]. Till skillnad från Millerindex för plan inverteras komponenterna inte.$kuggfri$, null, 61, false, $kuggfri$c8fed0414$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"[120]","correct":true},{"text":"[210]","correct":false},{"text":"[110]","correct":false},{"text":"[021]","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, GLU 01 Kristallstrukturer, s. 20$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('37e85615-60cb-5f0b-aad8-3c081af15a0f', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$vad-ar-ett-fasdiagram-och-vad-anvands$kuggfri$, $kuggfri$Vad är ett fasdiagram och vad används det till?$kuggfri$, $kuggfri$Ett fasdiagram visar vilka faser som är stabila vid vilka specifika temperaturer och sammansättningar av de ingående metallerna i en legering (även tryck m.m.). Gäller vid långsamma förlopp så att utjämning av koncentrationsskillnader kan ske m.h.a. diffusion = jämvikt uppnås.$kuggfri$, null, 62, true, $kuggfri$ce27f51b8$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('b7f718c4-fd46-589a-b120-4292ac949dfc', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$vad-ar-ferrit-och-nar-uppstar-det$kuggfri$, $kuggfri$Vad är Ferrit och när uppstår det?$kuggfri$, $kuggfri$Ferrit ($lpha$-järn) är järn med BCC-struktur. I rent järn är det den stabila fasen upp till ca 913 °C. Ferrit har låg löslighet av kol.

Över ca 1394 °C blir rent järn BCC igen, då kallat $\delta$-ferrit.$kuggfri$, null, 63, false, $kuggfri$c09414104$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: temperaturen följer nu 2026 års material och δ-ferriten nämns, så att "upp till 910 °C" inte läses som enda BCC-området; Canvas, GLU 02 Fasdiagram, s. 4; Canvas, Lab_PM_Optisk_Mikroskopi_v2026, s. 4; Canvas, Fo 4 Fasdiagram, s. 14$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('b75e3374-5e46-5d9c-8da7-6108d70dec27', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$vad-ar-austenit-och-nar-uppstar-det$kuggfri$, $kuggfri$Vad är Austenit och när uppstår det?$kuggfri$, $kuggfri$Austenit ($\gamma$-järn) är järn med FCC-struktur. I rent järn är det den stabila fasen mellan ca 913 °C och ca 1394 °C. Austenit kan lösa upp till ca 2,1 % kol.$kuggfri$, null, 64, false, $kuggfri$c3b8225cb$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: "upp över 910 °C" gällde inte över ca 1394 °C, där rent järn blir delta-ferrit (BCC); Canvas, GLU 02 Fasdiagram, s. 4; Canvas, Lab_PM_Optisk_Mikroskopi_v2026, s. 4; Canvas, Fo 4 Fasdiagram, s. 14$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('98158a2f-4921-5d45-87ce-a327352ae79f', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$vad-ar-cementit-och-nar-uppstar-det$kuggfri$, $kuggfri$Vad är cementit och när uppstår det?$kuggfri$, $kuggfri$Cementit, Fe₃C, intermediär fas, 6,67 % C, mycket hård$kuggfri$, null, 65, true, $kuggfri$cab75e673$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('3b439075-5235-5d41-804f-c8306d0daaf4', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$metastabil$kuggfri$, $kuggfri$Metastabil$kuggfri$, $kuggfri$Ett tillstånd i ett lokalt energiminimum. För att uppnå tillståndet med lägst energi (stabilt) måste en energibarriär övervinnas genom tillförsel av termisk energi. Fasen har högre Gibbs fria energi men antar spontant inte den mer stabila fasen.$kuggfri$, null, 66, true, $kuggfri$c9be8fcfa$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('7c74f111-e32c-5294-a214-27bd32c6695f', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$intermetall$kuggfri$, $kuggfri$Intermetall$kuggfri$, $kuggfri$En mellanliggande fas i fasdiagrammet som bara består av metaller (minst två). Den har exakt eller nära stökiometrisk sammansättning, t.ex. CuAl₂ i Al-Cu, och syns som ett smalt enfasområde. Mellanliggande faser med ett bredare sammansättningsintervall kallas intermediära faser.$kuggfri$, null, 67, false, $kuggfri$c22170986$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: definitionen var otydlig och saknade att fasen har (nära) stökiometrisk sammansättning; Canvas, GLU 02 Fasdiagram, s. 18, 21; Canvas, Fo 4 Fasdiagram, s. 13$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('33f94e1a-b83d-5559-8184-a4a14ee15928', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$eutektikum$kuggfri$, $kuggfri$Eutektikum$kuggfri$, $kuggfri$En strukturbeståndsdel som består av två faser. Eutektikum bildas vid konstant temperatur
och koncentration genom en trefasreaktion där en smält fas L bildar två fasta faser: L → alpha + beta$kuggfri$, null, 68, true, $kuggfri$c41514b8f$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('487cb6ba-20b9-586c-a857-b0e2025341c0', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$ja-nej-perlit-bildas-vid-en-eutektisk$kuggfri$, $kuggfri$Perlit bildas vid en eutektisk reaktion ur smälta.$kuggfri$, $kuggfri$Perlit bildas vid den eutektoida reaktionen, som sker i fast fas: austenit omvandlas till ferrit och cementit vid ca 0,8 % C och ca 723 °C. En eutektisk reaktion utgår från smälta ($L \to \alpha + \beta$); i Fe-C sker den vid 4,3 % C och 1147 °C och är relevant för gjutjärn.$kuggfri$, null, 69, false, $kuggfri$c5fde0021$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, GLU 02 Fasdiagram, s. 19, 20; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 17; Canvas, Tentamen Materialteknik med svar 2020-10-24, s. 2$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('6675b4ec-52ec-55b3-b2a8-2df1ebeb4a6f', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$loslighetsgrans$kuggfri$, $kuggfri$Löslighetsgräns$kuggfri$, $kuggfri$Den högsta koncentration av ett ämne som kan lösas i en fas.$kuggfri$, null, 70, true, $kuggfri$c979b9927$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('825a6b52-8e29-547f-886a-75b54524f3d6', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$strukturbestandsdel$kuggfri$, $kuggfri$Strukturbeståndsdel$kuggfri$, $kuggfri$En urskiljbar del av materialet som består av en eller flera faser och kan ses som en enhet på
något sätt. Kan vara en fas, eutektikum eller eutektoid.$kuggfri$, null, 71, true, $kuggfri$ceb2ca583$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('2966162f-6239-561d-997b-f65d8642ef18', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$fas$kuggfri$, $kuggfri$Fas$kuggfri$, $kuggfri$En del av materialet med homogena fysikaliska och kemiska egenskaper$kuggfri$, null, 72, true, $kuggfri$cf3070b69$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('bdf18512-3559-571c-b0cf-298f6985b446', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$quiz-vad-galler-for-gibbs-fria-energi-tva$kuggfri$, $kuggfri$Vilka påståenden om Gibbs fria energi är sanna?$kuggfri$, $kuggfri$Gibbs fria energi är entalpi minus temperatur gånger entropi, $G = H - TS$. Entalpin är energi lagrad i materialet, t.ex. elastisk töjning av atombindningarna, och entropin är kopplad till oordning, så ökad oordning sänker G. Begreppet gäller alla faser, även flytande och gas (is, vatten och vattenånga är olika faser), och ett material strävar mot den fas som har lägst G vid den aktuella temperaturen.$kuggfri$, null, 73, false, $kuggfri$cb112e71b$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Gibbs fria energi är summan av atomernas kinetiska energi.","correct":false},{"text":"Atombindningarnas potentiella energi ger ett bidrag till Gibbs fria energi.","correct":true},{"text":"Gibbs fria energi minskar med ökande oordning i materialet.","correct":true},{"text":"Gibbs fria energi gäller bara för fasta material.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 2, fråga 4; Canvas, GLU 02 Fasdiagram, s. 4, 5$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('6fe80817-abbd-5524-b336-6dcff30a39db', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$quiz-jamvikt-och-stabilitet-tva-ratt$kuggfri$, $kuggfri$Jämvikt och stabilitet: vilka påståenden är sanna?$kuggfri$, $kuggfri$Den stabila fasen är den med lägst Gibbs fria energi. En metastabil fas har inte lägst G men kräver aktiveringsenergi (oftast värme) för att omvandlas till den stabila fasen, och kan därför finnas kvar, t.ex. martensit i härdat stål eller den övermättade $\alpha$-fasen i snabbkyld aluminium. Även en instabil fas har en fri energi; den omvandlas förr eller senare till den stabila fasen, med en hastighet som kan begränsas av diffusion.$kuggfri$, null, 74, false, $kuggfri$ceef651ba$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Man kan använda Gibbs fria energi för att avgöra om materialet är i ett stabilt tillstånd.","correct":true},{"text":"Man kan använda Gibbs fria energi för att avgöra om materialet är i ett metastabilt tillstånd.","correct":true},{"text":"Gibbs fria energi är odefinierad när materialet är i ett instabilt tillstånd.","correct":false},{"text":"Ett material kan bara befinna sig i ett metastabilt tillstånd en kort tid (några sekunder till några dagar beroende på temperatur).","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 2, fråga 5; Canvas, GLU 02 Fasdiagram, s. 5, 6; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 23, 26; Canvas, Fo 5 Fasdiagram och mikrostruktur 2, s. 20$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('ebe9a8eb-beb9-5ed8-86bc-6365ae8f9f9a', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$quiz-fasdiagram-tva-ratt$kuggfri$, $kuggfri$Fasdiagram: vilka påståenden är sanna?$kuggfri$, $kuggfri$I ett binärt fasdiagram skiljs enfasområdena åt av tvåfasområden, även mellan de smala strecken för stökiometriska faser. Fasdiagrammet visar vilka faser som är stabila (har lägst Gibbs fria energi) vid en viss temperatur och sammansättning; tiden finns inte med, och diagrammet gäller vid så långsamma förlopp att jämvikt uppnås. En metastabil fas som martensit finns därför inte i fasdiagrammet. Quizens alternativ ("Två enfasområden har alltid ett tvåfasområde mellan sig", "Ett fasdiagram visar bara stabila faser") är omformulerade utan "alltid" och "bara", som föreläsningarna inte använder; det första är dessutom preciserat till binära fasdiagram, eftersom enfasområdena i ett unärt fasdiagram (ett enda ämne, t.ex. järn) bara skiljs åt av omvandlingstemperaturer.$kuggfri$, null, 75, false, $kuggfri$c128c6e7a$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"I ett binärt fasdiagram ligger det tvåfasområden mellan enfasområdena.","correct":true},{"text":"Ett fasdiagram visar hur stabila faser ändras med tiden.","correct":false},{"text":"Ett fasdiagram visar vilka faser som är stabila vid en viss temperatur och sammansättning.","correct":true},{"text":"Metastabila faser markeras vanligen med röd färg i fasdiagrammet.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 2, fråga 6; Canvas, GLU 02 Fasdiagram, s. 8, 14, 22; Canvas, Lab_PM_M2_v2026, s. 4, 6$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('1b3270bd-b25f-500f-be16-8b7593ec6f4e', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$quiz-stals-fasdiagram-vad-ar-sant-tva-ratt$kuggfri$, $kuggfri$Ståls fasdiagram: vilka påståenden är sanna?$kuggfri$, $kuggfri$Faserna i Fe-C-diagrammet är ferrit, austenit och cementit; martensit är en metastabil fas som bildas vid snabbkylning och finns inte i fasdiagrammet. Cementit (Fe₃C) innehåller 6,67 % C, mer än austenit (upp till 2,1 %) och ferrit (låg löslighet). Perlit är en strukturbeståndsdel av ferrit och cementit som bildas vid den eutektoida punkten (ca 0,8 % C), och dess andel kan räknas fram med hävstångsregeln. Austenit är en egen fas med annan kristallstruktur (FCC-järn) än ferrit (BCC-järn). Quizens alternativ "Om man löser in kol i ferrit så bildas austenit" är omformulerat, eftersom det inte är entydigt fel: vid t.ex. 850 °C är rent järn ferrit men ett stål med 0,3 % C austenit.$kuggfri$, null, 76, false, $kuggfri$cff3c5d68$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Cementit, ferrit och martensit är alla faser i fasdiagrammet.","correct":false},{"text":"Cementit är den fas i stål som innehåller mest kol.","correct":true},{"text":"Perlit är inte en fas, men man kan ändå bestämma perlitens kolhalt och andel ur fasdiagrammet.","correct":true},{"text":"Austenit är ferrit med inlöst kol.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 2, fråga 7; Canvas, GLU 02 Fasdiagram, s. 4, 16, 19, 20; Canvas, Fo 4 Fasdiagram, s. 14; Canvas, Fo 5 Fasdiagram och mikrostruktur 2, s. 20; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 15; Canvas, Short_dictionary_ v2026, s. 2, 6$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('ad53e5c4-a1a4-5562-a435-0de58aef0d72', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$quiz-eutektiska-och-eutektoida-reaktioner$kuggfri$, $kuggfri$Eutektiska och eutektoida reaktioner: vilka påståenden är sanna?$kuggfri$, $kuggfri$Trefasreaktioner sker vid konstant temperatur och koncentration: den eutektiska $L \to \alpha + \beta$ ur smälta och den eutektoida $\gamma \to \alpha + \beta$ i fast fas. Perlit bildas eutektoidt ur austenit, inte ur smälta. Vid en fasomvandling under svalning bildas värme, så ingen värme behöver tillföras, men reaktionen kräver diffusion av kol; vid snabbkylning hinner kolet inte diffundera och då bildas martensit i stället för perlit.$kuggfri$, null, 77, false, $kuggfri$c6e39146d$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Vid både eutektiska och eutektoida reaktioner är temperaturen konstant.","correct":true},{"text":"Perlit bildas vid en eutektisk reaktion ur smälta.","correct":false},{"text":"Eutektoida reaktioner kräver att värme tillförs, annars händer inget.","correct":false},{"text":"Eutektoida reaktioner kräver diffusion; utan diffusion sker ingen eutektoid reaktion.","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 2, fråga 8; Canvas, GLU 02 Fasdiagram, s. 19, 20; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 2, 17; Canvas, Fo 5 Fasdiagram och mikrostruktur 2, s. 20$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('49123138-a782-526c-b495-0465127568b6', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$quiz-fasdiagram-vad-ar-sant-tva-ratta-svar$kuggfri$, $kuggfri$Fasdiagram: vilka påståenden om löslighet och hävstångsregeln är sanna?$kuggfri$, $kuggfri$Vid obegränsad löslighet, t.ex. Cu-Ni, finns en enda fast fas vid alla sammansättningar under soliduslinjen. Löslighetsgränsen är den maximala koncentrationen av ett ämne som kan lösas in i ett annat, och den beror på temperaturen (i Pb-Sn är lösligheten av Sn i Pb störst, 18,3 %, vid 183 °C). Hävstångsregeln gäller i alla tvåfasområden, även där smälta och fast fas samexisterar.$kuggfri$, null, 78, false, $kuggfri$c914486e4$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Ett fasdiagram med obegränsad löslighet har bara en fast fas.","correct":true},{"text":"Löslighetsgränsen förändras vanligen med temperaturen.","correct":true},{"text":"Hävstångsregeln gäller bara för faser i fast tillstånd.","correct":false},{"text":"Löslighetsgränsen talar om hur svårt det är att legera en metall.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 2, fråga 10; Canvas, GLU 02 Fasdiagram, s. 10, 13, 14, 16; Canvas, Fo 4 Fasdiagram, s. 8, 9; Canvas, Lab_PM_M2_v2026, s. 6$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('dc423845-c891-5190-a8fe-cf7fa70faaa2', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$havstang-pbsn-40-strukturbestandsdelar$kuggfri$, $kuggfri$Pb-40 % Sn svalnar långsamt från smälta. Hur stor andel är primär $\alpha$ respektive eutektikum strax under 183 °C?$kuggfri$, $kuggfri$Strax ovanför 183 °C består legeringen av Pb-rik fas $\alpha$ (18,3 % Sn) och smälta med eutektisk sammansättning (61,9 % Sn). Hävstångsregeln ger andelen primär $\alpha$ $= \frac{61{,}9-40}{61{,}9-18{,}3} = \frac{21{,}9}{43{,}6} \approx 0{,}50$. Resten, ca 50 %, är smälta som vid 183 °C stelnar till eutektikum. 73 % är andelen av fasen $\alpha$ totalt (primär $\alpha$ plus $\alpha$ i eutektikumet), inte av strukturbeståndsdelen primär $\alpha$.$kuggfri$, null, 79, false, $kuggfri$c773d7f33$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Ca 50 % primär $\\alpha$ och 50 % eutektikum","correct":true},{"text":"Ca 40 % primär $\\alpha$ och 60 % eutektikum","correct":false},{"text":"Ca 73 % primär $\\alpha$ och 27 % eutektikum","correct":false},{"text":"100 % eutektikum","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, GLU 02 Fasdiagram, s. 14, 15, 17; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 10, 11$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('592a47c1-3597-58c2-a5bd-bb1f5edc9895', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$havstang-pbsn-40-faser$kuggfri$, $kuggfri$Pb-40 % Sn strax under 183 °C: hur stora är andelarna av faserna $\alpha$ och $\beta$?$kuggfri$, $kuggfri$Strax under 183 °C finns två faser: $\alpha$ med 18,3 % Sn och $\beta$ med 97,8 % Sn (lösligheten av Pb i Sn är bara 2,2 %). Hävstångsregeln ger andelen $\alpha$ $= \frac{97{,}8-40}{97{,}8-18{,}3} = \frac{57{,}8}{79{,}5} \approx 0{,}73$ och andelen $\beta \approx 0{,}27$. Fasandelarna skiljer sig från andelarna av strukturbeståndsdelarna (primär $\alpha$ och eutektikum, ca 50 % var).$kuggfri$, null, 80, false, $kuggfri$cd37e17ff$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Ca 73 % $\\alpha$ och 27 % $\\beta$","correct":true},{"text":"Ca 50 % $\\alpha$ och 50 % $\\beta$","correct":false},{"text":"Ca 60 % $\\alpha$ och 40 % $\\beta$","correct":false},{"text":"Ca 27 % $\\alpha$ och 73 % $\\beta$","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, GLU 02 Fasdiagram, s. 14, 17$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('65e63bdc-ec33-5eb3-9f1b-9bebc53bb999', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$havstangsregeln-metod$kuggfri$, $kuggfri$Hur använder man hävstångsregeln i ett tvåfasområde?$kuggfri$, $kuggfri$1. Dra en horisontell linje (förbindelselinje) vid aktuell temperatur genom legeringens sammansättning $C$ ut till tvåfasområdets gränser.
2. Läs av fasernas koncentrationer $C_\alpha$ och $C_\beta$ vid gränserna.
3. Andelen av en fas är den bortre hävstångsarmen delat med hela hävstången:

$f_\alpha = \dfrac{C_\beta - C}{C_\beta - C_\alpha}, \qquad f_\beta = \dfrac{C - C_\alpha}{C_\beta - C_\alpha}$

Det är linjär interpolation: vid $C = C_\alpha$ är andelen $\beta$ 0 % och vid $C = C_\beta$ 100 %.$kuggfri$, null, 81, false, $kuggfri$cbbc29af4$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Fo 4 Fasdiagram, s. 8, 9; Canvas, GLU 02 Fasdiagram, s. 16, 17; Canvas, Short_dictionary_ v2026, s. 14$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('4a59ac92-316f-593a-ba27-dd15e86670c9', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$segring$kuggfri$, $kuggfri$Segring$kuggfri$, $kuggfri$Koncentrationsskillnader i kornen som uppstår vid stelningen, eftersom diffusionen är för begränsad för att jämna ut sammansättningen. Förekommer nästan alltid vid gjutning i praktiken.$kuggfri$, null, 82, false, $kuggfri$ccc2416ea$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 13; Canvas, Lab_PM_M2_v2026, s. 6$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('913220b3-efa1-5d61-a133-e43a2dcfcc24', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$karnbildning$kuggfri$, $kuggfri$Kärnbildning$kuggfri$, $kuggfri$Att nya kristaller bildas i smältan och sedan tillväxer. Kärnbildningen sker lättare på fasta partiklar och ytor, och vid gjutning tillsätts därför små partiklar för att få en finkornigare kornstruktur. Kornen växer tills de möts och bildar materialets kornstruktur och korngränser.$kuggfri$, null, 83, false, $kuggfri$c01c43f44$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 5$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('d3dee631-b091-5489-a78f-50e3c7b9014b', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$ren-metall-stelningstemperatur$kuggfri$, $kuggfri$En ren metall stelnar inom ett temperaturintervall.$kuggfri$, $kuggfri$En ren metall har en distinkt smälttemperatur. När den stelnar bildas värme, och avsvalningskurvan får en platå tills allt har stelnat. En legering stelnar däremot i regel inom ett temperaturintervall, där smälta och fasta kristaller finns i jämvikt i ett tvåfasområde.$kuggfri$, null, 84, false, $kuggfri$ce87a9758$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, GLU 02 Fasdiagram, s. 9; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 2, 4; Canvas, Lab_PM_M2_v2026, s. 5$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('e8cf2321-3976-56b8-8287-1b97b1b41ab9', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$eutektoidiskt-stal-faser-strukturbestandsdel$kuggfri$, $kuggfri$Ett eutektoidiskt stål (ca 0,8 % C) som svalnat långsamt består av två faser men bara en strukturbeståndsdel.$kuggfri$, $kuggfri$Under den eutektoida temperaturen består stålet av faserna ferrit och cementit, men de förekommer tillsammans som den enda strukturbeståndsdelen perlit (lameller av ferrit och cementit). Över den eutektoida temperaturen är stålet en enda fas, austenit, som också är den enda strukturbeståndsdelen.$kuggfri$, null, 85, false, $kuggfri$c4526cdf9$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Lab_PM_M2_v2026, s. 11, 12; Canvas, GLU 02 Fasdiagram, s. 19, 20$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('eece5eea-efd7-5bb1-b1dc-c66702e31eb6', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$undereutektoidiskt-stal-strukturbestandsdelar$kuggfri$, $kuggfri$Vilka strukturbeståndsdelar har ett undereutektoidiskt stål (under ca 0,8 % C) efter långsam svalning?$kuggfri$, $kuggfri$Vid långsam svalning bildas först primär (proeutektoid) ferrit, och vid den eutektoida temperaturen omvandlas resten av austeniten till perlit. Bara perlit fås vid ca 0,8 % C, och perlit med cementit i gränserna mellan perlitområdena i övereutektoida stål. Martensit bildas bara vid snabbkylning från austenitområdet.$kuggfri$, null, 86, false, $kuggfri$ccbe07cf4$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Primär ferrit och perlit","correct":true},{"text":"Perlit och cementit","correct":false},{"text":"Bara perlit","correct":false},{"text":"Martensit","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 15, 18, 23; Canvas, Lab_PM_M2_v2026, s. 12$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('b5bf398f-324b-5d5f-9724-ff6c25bc67dc', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$tvafasomrade-fasernas-sammansattning$kuggfri$, $kuggfri$I ett tvåfasområde har båda faserna samma sammansättning som legeringen.$kuggfri$, $kuggfri$I ett tvåfasområde läser man av fasernas koncentrationer vid områdets gränser, längs en horisontell linje vid aktuell temperatur, och de skiljer sig från legeringens sammansättning. Det är bara i ett enfasområde som fasen har samma koncentration som legeringen.$kuggfri$, null, 87, false, $kuggfri$c993d5712$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Fo 4 Fasdiagram, s. 8, 9; Canvas, GLU 02 Fasdiagram, s. 17$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('270c7024-1219-5d1d-80cf-211f849c0aee', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '9d686bd9-37fb-54a7-aa3c-feaa3668034c', $kuggfri$stelning-pbsn-40$kuggfri$, $kuggfri$Beskriv hur en Pb-40 % Sn-legering stelnar och svalnar långsamt från smälta till rumstemperatur.$kuggfri$, $kuggfri$* Ca 240 till 184 °C: Pb-rik fas ($\alpha$) bildas gradvis i jämvikt med smältan, upp till ca 50 %.
* 183 °C: den kvarvarande smältan, som då har eutektisk sammansättning (61,9 % Sn), stelnar till eutektikum, en finfördelad blandning av $\alpha$ och $\beta$.
* Under 183 °C: lösligheten av Sn i Pb minskar, så Sn-rik fas ($\beta$) skiljs ut som utskiljningar i den Pb-rika fasen.

Resultatet är primär $\alpha$ (med $\beta$-utskiljningar) och eutektikum, ungefär hälften av varje.$kuggfri$, null, 88, false, $kuggfri$c89c1caa2$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 10, 11; Canvas, Fo 5 Fasdiagram och mikrostruktur 2, s. 8; Canvas, GLU 02 Fasdiagram, s. 14$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('1f10e3ac-c277-5ae0-99d3-e1f78cbfaffe', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '7b4bdbf7-ac7f-5d46-8266-31205b083f96', $kuggfri$vad-beror-ett-materials-densitet-pa-for$kuggfri$, $kuggfri$Vad beror ett materials densitet på för faktorer?$kuggfri$, $kuggfri$* Atomvikten hos atomerna i materialet
* Antalet atomer/volym
* Densiteten hos kompositer beror på volymandel och densitet på de ingående materialen
* Densiteten i polymerskum, trä m.m blir låg p.g.a. hålrummen.$kuggfri$, null, 89, true, $kuggfri$cea5cf0cf$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('a5d5e6cf-4695-5d9d-919c-45aca7d7469a', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '7b4bdbf7-ac7f-5d46-8266-31205b083f96', $kuggfri$atombindningar-kan-jamforas-med-linjara$kuggfri$, $kuggfri$Atombindningar kan jämföras med linjära fjädrar. Hur kommer detta sig och varför gör man det?$kuggfri$, $kuggfri$Man brukar likna atombindningar med linjära fjädrar för att de har liknande egenskaper.
Om:
S = styvheten hos atombindningen
n = antalet bindningar/area
Får vi:
E-modulen = S x n

* Elastiskt beteende = materialet beter sig
som en fjäder, fjädrar tillbaka vid
avlastning
* Djup bindningsenergikurva ger:
  - Stor E-modul
  - Hög smälttemperatur$kuggfri$, null, 90, true, $kuggfri$c73defe7d$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('b6fbe14c-8a65-5414-8cd1-c8a662b058b5', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '7b4bdbf7-ac7f-5d46-8266-31205b083f96', $kuggfri$vad-har-ett-materials-atombindningar$kuggfri$, $kuggfri$Vad har ett materials atombindningar för inverkan på dess egenskaper?$kuggfri$, $kuggfri$* Påverkar styvhet, termisk utvidgning,
smälttemperatur, elektrisk ledningsförmåga m.m.
* Kan ej förändras med processer$kuggfri$, null, 91, true, $kuggfri$c7dae83a1$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('2eaf03ac-75d0-5f23-96b7-17e66a9784d8', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '7b4bdbf7-ac7f-5d46-8266-31205b083f96', $kuggfri$hur-ser-ett-typiskt-dragprov-ut-for-ett$kuggfri$, $kuggfri$Hur ser ett typiskt dragprov ut för ett sprött material?$kuggfri$, $kuggfri$* Elastiskt beteende upp till
brottgränsen
* Brottgränsen =den spänning
där brott sker
* Keramer, glas$kuggfri$, null, 92, true, $kuggfri$cf8e91586$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('b9598645-8b12-5add-b41c-ea6dda4985cf', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '7b4bdbf7-ac7f-5d46-8266-31205b083f96', $kuggfri$hur-ser-ett-typiskt-dragprov-ut-for-ett-2$kuggfri$, $kuggfri$Hur ser ett typiskt dragprov ut för ett segt material?$kuggfri$, $kuggfri$* Elastiskt beteende upp till
sträckgränsen
* Sträckgränsen = den spänning där
materialet börjar plasticera
* Brottgränsen = högsta spänningen
* Elastisk avlastning även i plastiska
området
* Metaller, polymerer$kuggfri$, null, 93, true, $kuggfri$cc774aeb9$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('33289dc7-b673-55d4-a065-92d76b09c55a', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '7b4bdbf7-ac7f-5d46-8266-31205b083f96', $kuggfri$vilka-egenskaper-kan-observeras$kuggfri$, $kuggfri$Vilka egenskaper kan observeras/kartläggas med hjälp av dragprov?$kuggfri$, $kuggfri$* E-modul (styvhet) GPa
* Sträckgräns (börjar plasticera) MPa
* Brottgräns (största spänningen innan brott) MPa
* Brottförlängning (plastisk töjning efter brott) %
* Arean under kurvan: brottarbetet, dvs. energin per volymenhet fram till brott. (Seghet i betydelsen motstånd mot spricktillväxt, brottseghet, kan däremot inte mätas med dragprov, eftersom provet saknar spricka.)$kuggfri$, null, 94, false, $kuggfri$c5c36d755$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: "seghet = arean under dragprovkurvan" (2025) krockar med 2026 års definition av seghet som motstånd mot spricktillväxt, som inte kan fås ur dragprov; arean beskrivs nu som brottarbete; Canvas, Kapitel_08 Seghet och Brott, s. 2, 7; Canvas, Fo 9 Brott och brottseghet, s. 11; Canvas, Kapitel_04 Elastisk deformation, s. 20; Canvas, Fo 7 Styvhet, s. 9$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('b00edef7-d562-5966-b3b2-4ef281fd25df', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '7b4bdbf7-ac7f-5d46-8266-31205b083f96', $kuggfri$styvheten-hos-kompositer-beror-pa-fler$kuggfri$, $kuggfri$Styvheten hos kompositer beror på fler faktorer än homogena material gör, nämn minst två av dessa.$kuggfri$, $kuggfri$Styvheten beror på:

* De ingående komponenternas
egenskaper
* Volymfraktion
* Orientering
* Form

Ex: Fiberriktning$kuggfri$, null, 95, true, $kuggfri$c0859f190$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('60ee4565-6c5e-5669-b67f-8858de7bd4ca', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '7b4bdbf7-ac7f-5d46-8266-31205b083f96', $kuggfri$vad-ar-tojning$kuggfri$, $kuggfri$Vad är töjning?$kuggfri$, $kuggfri$Töjning är en geometrisk storhet: den relativa längdändringen, $\varepsilon = (L - L_0)/L_0$. Den är dimensionslös och anges ofta i procent (0,05 = 5 %). Dragspänning ger positiv töjning och tryckspänning negativ.

* Töjning kan orsakas av:

Mekaniska laster:
$\sigma = E\,\varepsilon$
Temperatur:
$\varepsilon = \alpha\,\Delta T$
$\alpha$ = längdutvidgningskoefficienten
Elektriska och magnetiska fält
Fukt m.m.$kuggfri$, null, 96, false, $kuggfri$cbbd9ee36$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: töjning beskrevs som den procentuella förlängningen, men är den relativa längdändringen, dimensionslös och negativ vid tryck; Canvas, Kapitel_04 Elastisk deformation, s. 6, 7, 22; Canvas, Kapitel_06 Plasticitet och Duktilitet, s. 2; Canvas, Fo 7 Styvhet, s. 12$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('fc3d7020-a55c-5b64-8d7c-0ab7141a10cd', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '7b4bdbf7-ac7f-5d46-8266-31205b083f96', $kuggfri$vad-kannetecknar-ett-isotropt-material$kuggfri$, $kuggfri$Vad kännetecknar ett isotropt material?$kuggfri$, $kuggfri$Ett isotropt material har samma egenskaper oavsett i vilken riktning de mäts. Dess elastiska beteende beskrivs av två elastiska konstanter:

* E-modul
* Poissons tal, tvärkontraktion

Övriga moduler följer av dem, t.ex. skjuvmodulen $G = E/(2(1+\nu))$. Fler elastiska konstanter behövs i t.ex. kompositer och trä → anisotropt material.$kuggfri$, null, 97, false, $kuggfri$c84f800fe$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: isotropi definierades som att materialet kan beskrivas med minst två elastiska konstanter, men definitionen är att egenskaperna är lika i alla riktningar; Canvas, Kapitel_04 Elastisk deformation, s. 15, 21, 23; Canvas, Short_dictionary_ v2026, s. 8; Canvas, Fo 7 Styvhet, s. 13$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('fa1984b2-f558-570c-a331-a604f2b4d29c', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '7b4bdbf7-ac7f-5d46-8266-31205b083f96', $kuggfri$anisotropt$kuggfri$, $kuggfri$Anisotropt$kuggfri$, $kuggfri$Olika egenskaper i olika riktningar$kuggfri$, null, 98, true, $kuggfri$cb59ba541$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('c3c66c32-5ded-5101-8c9e-271dc8f5b15b', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '7b4bdbf7-ac7f-5d46-8266-31205b083f96', $kuggfri$styvhet$kuggfri$, $kuggfri$Styvhet$kuggfri$, $kuggfri$Ett mått på hur mycket ett material deformeras elastiskt när det utsätts för en last.$kuggfri$, null, 99, true, $kuggfri$c6b630f01$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('957800a7-7c8a-5c24-9f39-dbdf80fe5599', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '7b4bdbf7-ac7f-5d46-8266-31205b083f96', $kuggfri$ja-nej-basta-sattet-att-oka-e-modulen$kuggfri$, $kuggfri$Det bästa sättet att öka en metalls E-modul är att värmebehandla (härda) den.$kuggfri$, $kuggfri$E-modulen bestäms av atombindningarnas styvhet och antalet bindningar per area, och i metaller påverkar värmebehandling och bearbetning inte E-modulen. Härdning höjer i stället sträckgräns och hårdhet. Vill man ändra E-modulen är det mest effektivt att kombinera material i makroskala, t.ex. styva fibrer i en mindre styv matris i en komposit.$kuggfri$, null, 100, false, $kuggfri$c63a6dc9f$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_04 Elastisk deformation, s. 12, 24, 26; Canvas, Fo 7 Styvhet, s. 4, 5; Canvas, Tentamen Materialteknik med svar 2020-10-24, s. 2$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('b4c5783f-d35b-52cf-a5df-727f449202b2', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '7b4bdbf7-ac7f-5d46-8266-31205b083f96', $kuggfri$ja-nej-dislokationer-ar-lika-viktiga$kuggfri$, $kuggfri$Dislokationer är lika viktiga för ett materials E-modul som för dess sträckgräns.$kuggfri$, $kuggfri$Dislokationsrörelse ger plastisk deformation, och genom att försvåra den höjs sträckgränsen. E-modulen beskriver elastisk deformation och bestäms av atombindningarnas styvhet; den påverkas inte av värmebehandling och bearbetning, som ändrar dislokationsstrukturen.$kuggfri$, null, 101, false, $kuggfri$ce3ccc466$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_06 Plasticitet och Duktilitet, s. 18, 30; Canvas, Kapitel_04 Elastisk deformation, s. 12; Canvas, Fo 7 Styvhet, s. 4; Canvas, Tentamen Materialteknik med svar 2020-10-24, s. 2$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('34aea368-5a8b-51c0-9712-df9ef011bca4', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '7b4bdbf7-ac7f-5d46-8266-31205b083f96', $kuggfri$quiz-styvhet-vad-ar-sant-tva-ratta-svar$kuggfri$, $kuggfri$Styvhet: vilka påståenden är sanna?$kuggfri$, $kuggfri$Styvhet är motståndet mot elastisk formförändring, och E-modulen är lutningen i den elastiska delen av spännings-töjningskurvan ($\sigma = E\varepsilon$). Låg E-modul ger alltså stor elastisk töjning vid en given spänning, ett vekt material, medan hög E-modul ger liten deformation. Sprödhet hänger ihop med låg brottseghet, inte med låg E-modul. Quizens "lätta att deformera" är preciserat till elastisk deformation.$kuggfri$, null, 102, false, $kuggfri$c62e590c8$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Material med låg E-modul är lätta att deformera elastiskt.","correct":true},{"text":"Material med låg E-modul är veka.","correct":true},{"text":"Material med hög E-modul kan deformeras mycket.","correct":false},{"text":"Material med låg E-modul är spröda.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 1, fråga 8; Canvas, Kapitel_04 Elastisk deformation, s. 2, 9, 12; Canvas, Kapitel_01 Intro till Material, s. 16$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('eb16f80b-2faa-5900-bcb4-2feb958d4fcc', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '7b4bdbf7-ac7f-5d46-8266-31205b083f96', $kuggfri$quiz-vad-ar-ratt-for-styvhet-2-ratta-svar$kuggfri$, $kuggfri$Styvhet: vilka påståenden om E-modul och elastisk deformation är rätt?$kuggfri$, $kuggfri$Metaller som stål har en linjärt elastisk del av spännings-töjningskurvan (E ≈ 210 GPa för stål). Poissons tal är bara definierat i det elastiska området och beskriver, liksom E-modulen, elastisk deformation. E-modulen är en materialegenskap och kan bestämmas med både drag- och böjprov. Hög E-modul hänger ihop med starka atombindningar, och empiriskt har material med hög E-modul låg expansionskoefficient.$kuggfri$, null, 103, false, $kuggfri$ce8cb3177$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Stål kan inte deformeras elastiskt.","correct":false},{"text":"E-modul och Poissons tal beskriver båda elastisk deformation.","correct":true},{"text":"E-modulen är olika vid dragbelastning och böjbelastning.","correct":false},{"text":"Material med hög E-modul har oftast låg termisk utvidgningskoefficient.","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 3, fråga 1; Canvas, Kapitel_04 Elastisk deformation, s. 12, 14; Canvas, 2026-09-25 Kapitel_12 Material och varme, s. 15$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('790cfd4a-27ed-546a-b726-1a74a9afcd44', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '7b4bdbf7-ac7f-5d46-8266-31205b083f96', $kuggfri$quiz-styvhet-vad-ar-ratt-2-ratta-svar$kuggfri$, $kuggfri$Styvhet: vilka påståenden om att ändra E-modulen är rätt?$kuggfri$, $kuggfri$I metaller påverkar värmebehandling och bearbetning inte E-modulen, och att ändra modulen genom legering (mikroskala) är mindre effektivt än att kombinera material i makroskala, t.ex. i en komposit. En komposit med orienterade fibrer är anisotrop och har olika E-modul i olika riktningar. I polymerer är kedjorna kovalent bundna, men bindningarna mellan kedjorna (van der Waals- och vätebindningar) är svaga. Quizens "de svaga atombindningarna" är preciserat till bindningarna mellan kedjorna.$kuggfri$, null, 104, false, $kuggfri$c435ae8b0$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Man kan öka en metalls E-modul genom härdning.","correct":false},{"text":"Ett vanligt sätt att öka en metalls E-modul är att legera med en tyngre metall.","correct":false},{"text":"E-modulen hos en komposit kan vara olika i olika riktningar.","correct":true},{"text":"Polymerers relativt låga E-modul förklaras av de svaga bindningarna mellan polymerkedjorna.","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 3, fråga 2; Canvas, Kapitel_04 Elastisk deformation, s. 12, 23, 24, 26, 42; Canvas, Fo 1 Materialegenskaper och materialgrupper HT25, s. 14$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('18449a8e-ff18-58cc-a15a-3106400df92e', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '7b4bdbf7-ac7f-5d46-8266-31205b083f96', $kuggfri$poissons-tal-elastiska-omradet$kuggfri$, $kuggfri$Poissons tal är bara definierat i det elastiska området.$kuggfri$, $kuggfri$Poissons tal $\nu$ är den negativa kvoten mellan tvärtöjning och längstöjning vid dragbelastning, och det är definierat bara i det elastiska området. Typiska värden: metaller ca 0,3, keramer 0,2 till 0,3, polymerer ca 0,4 och gummi nära 0,5.$kuggfri$, null, 105, false, $kuggfri$cc31d4ec5$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_04 Elastisk deformation, s. 14$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('3707d01a-6c18-5113-a38a-1a3428bfd92f', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '7b4bdbf7-ac7f-5d46-8266-31205b083f96', $kuggfri$skjuvmodul-stal-berakning$kuggfri$, $kuggfri$Stål har E = 210 GPa och $\nu = 0{,}3$. Vilken skjuvmodul G ger det?$kuggfri$, $kuggfri$För ett isotropt material gäller $G = \dfrac{E}{2(1+\nu)} = \dfrac{210}{2 \cdot 1{,}3} \approx 81$ GPa. 105 GPa fås om man glömmer faktorn $(1+\nu)$, 162 GPa om man glömmer faktorn 2, och 273 GPa är $E(1+\nu)$, dvs. man har multiplicerat med $(1+\nu)$ och glömt faktorn 2.$kuggfri$, null, 106, false, $kuggfri$cd6306bbd$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Ca 81 GPa","correct":true},{"text":"Ca 105 GPa","correct":false},{"text":"Ca 162 GPa","correct":false},{"text":"Ca 273 GPa","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_04 Elastisk deformation, s. 12, 14, 21$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('3aba3671-9359-57ac-8cad-a0b47897cc09', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '7b4bdbf7-ac7f-5d46-8266-31205b083f96', $kuggfri$blandningsregeln$kuggfri$, $kuggfri$Blandningsregeln$kuggfri$, $kuggfri$En egenskap hos en komposit eller hybrid uppskattas genom att de ingående materialens egenskaper viktas med volymandelarna. För densiteten gäller $\rho = f\rho_A + (1-f)\rho_B$, där f är volymandelen av material A. För E-modulen ger blandningsregeln i stället en övre och en nedre gräns. I kursens exempel räknas modulen för långa parallella fibrer (längs fibrerna) och för små partiklar, som motsvarar den nedre gränsen.$kuggfri$, null, 107, false, $kuggfri$c34c73cda$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Short_dictionary_ v2026, s. 12; Canvas, Kapitel_04 Elastisk deformation, s. 26, 27, 28$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('868c4718-d4ed-5563-adc5-688f003a52db', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$hur-mats-ett-materials-hardhet$kuggfri$, $kuggfri$Hur mäts ett materials hårdhet?$kuggfri$, $kuggfri$* Mäts med intryck
* Olika metoder med
olika form på
indenter och olika
last
* Kopplar till
sträckgräns$kuggfri$, null, 108, true, $kuggfri$cb2a80d92$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('9572836a-8873-57b7-acba-30ec59fa647d', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$vad-kan-det-finnas-for-defekter-i$kuggfri$, $kuggfri$Vad kan det finnas för defekter i kristaller?$kuggfri$, $kuggfri$* Vakanser = atomer saknas
* Inlösta atomer = atom av
annan sort
* Dislokationer = extra
atomplan
* Korngränser$kuggfri$, null, 109, true, $kuggfri$c0ab71ac0$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('d7a8223b-69cb-5f19-8d0a-6c9a30699b40', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$beskriv-ingaende-vad-dislokationer-och$kuggfri$, $kuggfri$Beskriv ingående vad dislokationer och dislokationsrörelser är och vad det innebär för materialet.$kuggfri$, $kuggfri$Dislokationer är en typ av strukturmässig avvikelse i kristallen i form av "extra atomplan". De bryter alltså det annars uniforma mönstret hos kristallen.

* När kristallen belastas över sträckgränsen kan dislokationer röra sig
* Dislokationerna rör sig på glidsystem = glidplan + glidriktning
* Glidningen ger upphov till en förskjutning som har storlek och riktning som glidvektorn, Burgers vektor

Dislokationen kan sättas i rörelse av skjuvspänningar och rör sig sedan i små steg. Detta ger upphov till små förskjutningar eller annars kallat; plastiska deformationer i kristallstrukturen.

* Dislokationerna rör sig lättast i
riktningar nära 45 grader mot
belastningsriktningen
* Plasticering sker under
konstant volym
* Ger upphov till skjuvband =
band av plasticerat material$kuggfri$, null, 110, true, $kuggfri$c3fddec37$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('bdde4b07-0a8c-5e79-930a-1ec43cabd094', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$vad-ar-en-hardningsmekanism-namn-minst$kuggfri$, $kuggfri$Vad är en härdningsmekanism? Nämn minst två olika typer av härdningsmekanismer.$kuggfri$, $kuggfri$En förändring av mikrostrukturen för att göra dislokationsrörelser svårare. Det resulterar i högre sträckgräns, hårdhet och ofta lägre brottförlängning. De olika typerna av härdningsmekanismer är:

1. Lösningshärdning
2. Utskiljningshärdning
3. Deformationshärdning
4. Korngränshärdning$kuggfri$, null, 111, true, $kuggfri$cb564e8df$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('19c6729c-f900-5e59-a867-310a3bddcac4', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$vad-ar-losningshardning-och-hur-gar-det$kuggfri$, $kuggfri$Vad är lösningshärdning och hur går det till?$kuggfri$, $kuggfri$* Atomer av annan sort löses in i
kristallen
* Spänningsfältet kring atomerna
hindrar dislokationsrörelse
* Större effekt med större
koncentration och större skillnad i
atomstorlek
* Sker med legering i smälta$kuggfri$, null, 112, true, $kuggfri$c560695e6$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('695a24b3-4bad-5386-8dcf-34119a088d8c', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$vad-ar-utskiljningshardning-och-hur-gar$kuggfri$, $kuggfri$Vad är utskiljningshärdning och hur går det till?$kuggfri$, $kuggfri$* Partiklar av annan fas
bildas i materialet
* Partiklarna hindrar
dislokationsrörelse
* Sker med legering i smälta
och värmebehandling i
fast form$kuggfri$, null, 113, true, $kuggfri$c9c6febd6$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('27d1e234-cb5f-5cc9-8017-ecd793b9a6be', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$vad-ar-deformationshardning-och-hur-gar$kuggfri$, $kuggfri$Vad är deformationshärdning och hur går det till?$kuggfri$, $kuggfri$* Dislokationer hindrar andra
dislokationer att röra sig (låser
varandra)
* Mängden dislokationer ökar
kraftigt vid plastisk
deformation → plastiskt
hårdnande
* Sker vid kallbearbetning
(pressning, valsning, smide ...)$kuggfri$, null, 114, true, $kuggfri$cda37f5df$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('6fbfcc5e-7066-58f1-8030-8b3841e89331', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$vad-ar-korngarnshardning-och-hur-gar$kuggfri$, $kuggfri$Vad är korngränshärdning och hur går det till?$kuggfri$, $kuggfri$* Minska storleken på kornen som utgör materialet så att antalet korngränser ökar
* Korngränser hindrar
dislokationer
* Små korn ger hårdare material
* Viktigt hos BCC-metaller (vissa
stål)$kuggfri$, null, 115, true, $kuggfri$c8f444b4e$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('4a90b17b-5925-5e27-9d4a-1c775d3725af', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$brottforlangning$kuggfri$, $kuggfri$Brottförlängning$kuggfri$, $kuggfri$Den plastiska förlängningen som kvarstår efter ett material har belastats till brott.$kuggfri$, null, 116, true, $kuggfri$c5a09cd20$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('1a8920c7-444e-55dd-a0d3-e2b9fc75f32f', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$ja-nej-malet-med-utskiljningshardning$kuggfri$, $kuggfri$Målet med utskiljningshärdning är att få bort dislokationerna.$kuggfri$, $kuggfri$Utskiljningshärdning skapar små, jämnt fördelade partiklar av en annan fas som hindrar dislokationernas rörelse. När dislokationerna får svårare att röra sig ökar sträckgränsen och hårdheten. Dislokationerna finns kvar; det är deras rörelse som bromsas.$kuggfri$, null, 117, false, $kuggfri$c701ce9dc$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_06 Plasticitet och Duktilitet, s. 30, 33, 35; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 26; Canvas, Tentamen Materialteknik med svar 2020-10-24, s. 2$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('287429c1-2dbd-5de2-b528-b53465e1cd6d', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$quiz-strackgrans-vad-ar-sant-tva-ratta-svar$kuggfri$, $kuggfri$Sträckgräns: vilka påståenden är sanna?$kuggfri$, $kuggfri$Under sträckgränsen är deformationen elastisk och materialet återgår till sin ursprungliga form; över sträckgränsen uppstår permanent (plastisk) deformation. Hårdheten kopplar till sträckgränsen och korrelerar med brottgränsen för duktila material, så hårda material har i regel hög sträckgräns. Sträckgränsen är en spänning (MPa), inte en förlängning; den plastiska töjningen efter brott kallas brottförlängning.$kuggfri$, null, 118, false, $kuggfri$c9b42a996$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Vid belastning under sträckgränsen beter sig ett material elastiskt.","correct":true},{"text":"Hårda material har vanligen låg sträckgräns.","correct":false},{"text":"Vid belastning över sträckgränsen fås permanent formförändring.","correct":true},{"text":"Sträckgränsen är den maximala förlängningen vid en sträckning av materialet.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 1, fråga 7; Canvas, Kapitel_06 Plasticitet och Duktilitet, s. 3, 6; Canvas, Fo 8 Plasticitet, s. 3; Canvas, Fo 7 Styvhet, s. 9$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('2d437028-ade3-5787-be6f-40cb1b5cd05c', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$quiz-strackgrans-vad-ar-ratt-tva-ratta-svar$kuggfri$, $kuggfri$Sträckgräns: vilka påståenden är rätt?$kuggfri$, $kuggfri$Under sträckgränsen är deformationen elastisk, oavsett hur hårt materialet är. Sträckgränsen bestäms med en standardiserad offsetmetod, $R_{p0{,}2}$, dvs. den spänning som ger 0,2 % kvarstående töjning. Vid plastisk deformation ökar dislokationstätheten och metallen deformationshärdas, så sträckgränsen stiger. Lösningshärdning beror på att de inlösta atomerna har en annan storlek än värdatomerna och stör dislokationsrörelsen, inte på att legeringsämnet är hårdare.$kuggfri$, null, 119, false, $kuggfri$c6491bdd0$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Ett hårt material som belastas under sträckgränsen beter sig elastiskt.","correct":true},{"text":"Det vanligaste sättet att öka en metalls sträckgräns är att legera med en hårdare metall.","correct":false},{"text":"När man plasticerar en metall sjunker sträckgränsen.","correct":false},{"text":"Vid mätning definieras sträckgränsen som den spänning som ger 0,2 % plastisk töjning.","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 3, fråga 3; Canvas, Kapitel_06 Plasticitet och Duktilitet, s. 3, 31, 36; Canvas, Kapitel_03 Materialval, s. 15; Canvas, Fo 8 Plasticitet, s. 11, 15$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('07aee70e-3f91-555b-bece-8d2f3c9e4f75', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$quiz-dislokationer-vad-ar-ratt-tva-ratta-svar$kuggfri$, $kuggfri$Dislokationer: vilka påståenden är rätt?$kuggfri$, $kuggfri$Dislokationer ger plastisk, inte elastisk, deformation, och genom att försvåra deras rörelse höjs sträckgränsen. Dislokationer är kristalldefekter i metaller och keramer och förklarar inte polymerers låga sträckgräns. Dislokationer rör sig lättast nära 45 grader mot belastningsriktningen, där skjuvspänningen på glidsystemet, $\tau = \sigma \cos\lambda \cos\varphi$, blir störst; ett korn börjar deformeras när skjuvspänningen på dess glidsystem blir tillräckligt hög. Quizens alternativ "För att en dislokation ska kunna ge plastisk töjning måste den röra sig på ett atomplan nära 45 grader" är omformulerat, eftersom föreläsningen säger "lättast" och inte "måste".$kuggfri$, null, 120, false, $kuggfri$c0975645e$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Dislokationer har stor betydelse för elastisk deformation.","correct":false},{"text":"Ett bra sätt att öka sträckgränsen är att försvåra dislokationsrörelse.","correct":true},{"text":"Polymerer har låg sträckgräns på grund av att de alltid innehåller många dislokationer.","correct":false},{"text":"Dislokationer rör sig lättast i riktningar nära 45 grader mot belastningsriktningen.","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 3, fråga 4; Canvas, Kapitel_06 Plasticitet och Duktilitet, s. 16, 20, 30; Canvas, Kapitel_04 Elastisk deformation, s. 12; Canvas, Fo 8 Plasticitet, s. 9$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('0ab353c8-7ef0-539d-930c-05cf36a94977', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$quiz-hardningsmekanismer-vad-ar-ratt-2-ratta$kuggfri$, $kuggfri$Härdningsmekanismer: vilka påståenden är rätt?$kuggfri$, $kuggfri$Deformationshärdning kräver bara plastisk deformation (dislokationerna blir fler och låser varandra) och fungerar på både legerade och olegerade metaller. Utskiljningshärdning kräver ett legeringsämne som kan skiljas ut som partiklar. Värms en kallbearbetad metall bildas nya små korn med få dislokationer (rekristallisation), och sträckgränsen sjunker medan brottförlängningen ökar. Korngränser hindrar dislokationer, så det är små korn som ger hårdare material (korngränshärdning). Quizens två felaktiga alternativ ("När man värmebehandlar metaller så låser sig dislokationerna och sträckgränsen ökar" och "Om man minskar mängden kristalldefekter så ökar hållfastheten") är utbytta, eftersom de inte är entydigt fel: utskiljningshärdning är en värmebehandling där partiklar låser dislokationerna, och enligt kursen är det dislokationerna som gör att metaller inte når den ideala hållfastheten.$kuggfri$, null, 121, false, $kuggfri$c66c415c9$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Rena metaller kan deformationshärdas.","correct":true},{"text":"När en kallbearbetad metall värms så att den rekristalliserar ökar sträckgränsen.","correct":false},{"text":"Utskiljningshärdning kan bara göras på legeringar, inte på rena metaller.","correct":true},{"text":"Större korn (färre korngränser) ger högre hållfasthet.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 3, fråga 5; Canvas, Kapitel_06 Plasticitet och Duktilitet, s. 14, 15, 33, 35, 36; Canvas, Fo 8 Plasticitet, s. 13, 15, 17; Canvas, Fo 12 Stal, s. 5; Canvas, Svarsforslag Tentamen MTT085 25-01, s. 7$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('ac5c6f0f-b9d0-5c3e-8276-17046989f5d2', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$quiz-kristalstorningar-kristalldefekter-vad$kuggfri$, $kuggfri$Kristallstörningar (kristalldefekter): vilka påståenden är rätt?$kuggfri$, $kuggfri$Kristalldefekter är avvikelser från den perfekta kristallen: vakanser, lösta atomer, dislokationer och korngränser. Porer och sprickor är defekter i materialet men inte kristalldefekter. Vakanser spelar roll vid diffusion, krypning och sintring men påverkar inte hållfastheten. Inlösta atomer ger lösningshärdning och höjer sträckgränsen, medan E-modulen i stort sett inte ändras av legering i mikroskala.$kuggfri$, null, 122, false, $kuggfri$ca2ff1686$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Porer och sprickor är exempel på kristalldefekter.","correct":false},{"text":"Vakanser och inlösta atomer är exempel på kristalldefekter.","correct":true},{"text":"Vakanser är en typ av kristalldefekt som försvagar materialet.","correct":false},{"text":"Inlösta atomer kan användas för att höja sträckgränsen, men påverkar E-modulen i liten omfattning.","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 3, fråga 6; Canvas, Kapitel_06 Plasticitet och Duktilitet, s. 16, 17; Canvas, Fo 8 Plasticitet, s. 5, 11; Canvas, Kapitel_04 Elastisk deformation, s. 12, 26$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('f7368ca0-99f8-5fdf-83c9-17b4007a657b', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$duktilitet$kuggfri$, $kuggfri$Duktilitet$kuggfri$, $kuggfri$Ett mått på formbarhet, dvs. hur formbart materialet är. I dragprov mäts den som brottförlängning (t.ex. 20 %) eller areakontraktion. Rörliga dislokationer är viktiga för metallers formbarhet och duktilitet, och starkare legeringar tenderar att ha lägre duktilitet.$kuggfri$, null, 123, false, $kuggfri$c2c68383d$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_06 Plasticitet och Duktilitet, s. 3, 24; Canvas, Kapitel_08 Seghet och Brott, s. 2; Canvas, Short_dictionary_ v2026, s. 4$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('f28c6496-832f-5741-9b0f-7a45cf4f00f3', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$glidsystem$kuggfri$, $kuggfri$Glidsystem$kuggfri$, $kuggfri$Kombinationen av ett glidplan och en glidriktning, där dislokationer rör sig. Glidplanen och glidriktningarna korrelerar med de mest tätpackade planen och de tätpackade riktningarna i dem. Ett korn börjar deformeras plastiskt när skjuvspänningen på ett glidsystem, $\tau = \sigma\cos\lambda\cos\varphi$, blir tillräckligt hög.$kuggfri$, null, 124, false, $kuggfri$cc210bee0$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_06 Plasticitet och Duktilitet, s. 20, 28$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('217772a9-04b7-5f05-909b-1a6ed287a226', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$skruvdislokation-burgers-vektor$kuggfri$, $kuggfri$I en skruvdislokation är Burgers vektor parallell med dislokationslinjen.$kuggfri$, $kuggfri$I en skruvdislokation förskjuts kristallens övre del parallellt med snittkanten, och Burgers vektor är parallell med dislokationslinjen. En kantdislokation kan ses som kanten av ett extra halvplan av atomer, och där är förskjutningen vinkelrät mot dislokationslinjen. Verkliga dislokationer växlar mellan de två typerna längs linjen.$kuggfri$, null, 125, false, $kuggfri$c5b82219f$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_06 Plasticitet och Duktilitet, s. 18, 19, 22, 23, 24$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('8bb74730-d8dc-52be-8b4b-8fba46a18178', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$hardning-okad-dislokationstathet$kuggfri$, $kuggfri$Vilken härdningsmekanism bygger på att dislokationstätheten ökar vid plastisk deformation?$kuggfri$, $kuggfri$Vid plastisk deformation (t.ex. kallvalsning eller smide) skapas fler dislokationer som hindrar varandra, och ju mer deformation, desto mer hårdnande. Lösningshärdning bygger på inlösta främmande atomer, utskiljningshärdning på små partiklar och korngränshärdning på att korngränserna hindrar dislokationer från att glida vidare till nästa korn.$kuggfri$, null, 126, false, $kuggfri$c2515b4f7$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Deformationshärdning","correct":true},{"text":"Lösningshärdning","correct":false},{"text":"Utskiljningshärdning","correct":false},{"text":"Korngränshärdning","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_06 Plasticitet och Duktilitet, s. 31, 33, 36, 37, 40$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('7b45a40a-203f-5396-bde8-baf2b78b9fe8', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'b1e2c1c7-3222-5068-b863-314ad83c0320', $kuggfri$ideal-hallfasthet-dislokationer$kuggfri$, $kuggfri$Varför når metaller inte den ideala hållfastheten, dvs. den spänning som krävs för att bryta alla bindningar i ett plan samtidigt?$kuggfri$, $kuggfri$Därför att metaller innehåller dislokationer. För att en dislokation ska röra sig behöver bara bindningarna längs dislokationslinjen brytas, vilket är betydligt lättare än att bryta alla bindningar i glidplanet på en gång. Glidförskjutningen per dislokation är mycket liten, men när enormt många dislokationer passerar genom kristallen på flera glidplan deformeras materialet makroskopiskt redan vid en spänning långt under den ideala hållfastheten. (I keramer är förklaringen i stället att de inte kan skapa rörliga dislokationer och därför inte deformeras plastiskt; spänningarna kan inte fördelas till en större volym, och spänningskoncentrationer ger höga lokala spänningar.)$kuggfri$, null, 127, false, $kuggfri$c22df3b30$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_06 Plasticitet och Duktilitet, s. 13, 14, 15, 27$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('d181901e-43d2-5b1c-b4b2-b828384d3ce2', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$varfor-ar-sproda-material-extra$kuggfri$, $kuggfri$Varför är spröda material extra känsliga för defekter?$kuggfri$, $kuggfri$Största förekommande defekten i en komponent ger störst spänning vilket innebär att brottet börjar där. Brottstyrkan blir då beroende av sannolikheten för att det finns en defekt i det belastade området och ju större komponenten är desto högre blir sannolikheten att det förekommer defekter. Eftersom sprickor uppträder lättare i spröda material blir de mer defektkänsliga.$kuggfri$, null, 128, true, $kuggfri$c0fb684f5$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('1cbdc93f-ab00-5877-9864-891fd35453e0', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$vad-har-temperatur-for-inverkan-pa-ett$kuggfri$, $kuggfri$Vad har temperatur för inverkan på ett materials brottseghet?$kuggfri$, $kuggfri$Vid låga temperaturer blir vissa metaller och alla polymerer spröda. När temperaturen sjunker ökar sträckgränsen för de flesta material, vilket minskar den plastiska zonen vid sprickspetsen och därmed segheten. Endast metaller med FCC-struktur förblir duktila vid de lägsta temperaturerna.

Övergången mellan segt och sprött beteende (omslagstemperaturen) bestäms med slagprovning.$kuggfri$, null, 129, false, $kuggfri$cdde3dc53$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: kortet sa att alla material blir sprödare när temperaturen sjunker, men metaller med FCC-struktur förblir duktila; Canvas, Kapitel_08 Seghet och Brott, s. 31; Canvas, Kapitel_08 Seghet och Brott, s. 37; Canvas, Fö 9 Brott och brottseghet, s. 3$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('14881e99-7c46-5d30-a7b6-0f202f4270f1', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$vad-ar-skillnaden-mellan-ett-segt$kuggfri$, $kuggfri$Vad är skillnaden mellan ett segt- respektive sprött brott?$kuggfri$, $kuggfri$* **Segt brott** föregås av tydlig plastisk deformation och stora formändringar. Hålrum bildas vid inneslutningar, växer och går samman till brott. Brottytan är matt och ojämn (skål- och konformad). Typiskt för de flesta metaller vid rumstemperatur.
* **Sprött brott** sker utan nämnvärd plastisk deformation, ofta plötsligt. Brottytan är relativt jämn och glänsande med kornig struktur. Uppträder främst vid låga temperaturer, höga belastningshastigheter och i spröda material som keramer och härdat stål.$kuggfri$, null, 130, false, $kuggfri$c3defbed9$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: "deformeras plastiskt under en längre tid" var missvisande, det är mängden plastisk deformation och inte tiden som skiljer brotten åt; Canvas, Svarsförslag uppgift 4-6, IMS085 251030, s. 1; Canvas, Kapitel_08 Seghet och Brott, s. 27; Canvas, Kapitel_08 Seghet och Brott, s. 28$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('2c88472e-7c27-5189-9afe-e136a56bbef9', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$vad-anvander-man-for-typ-av-test-for$kuggfri$, $kuggfri$Vad använder man för typ av test för att undersöka ett materials brottseghet?$kuggfri$, $kuggfri$Brottsegheten $K_{1c}$ bestäms med prov som har en skarp spricka, t.ex. CT-prov (compact tension) eller SENB-prov (single edge notched beam). Båda provstavstyperna har en utmattningsspricka. Provet måste vara så brett att plant töjningstillstånd råder längs sprickfronten; först då blir $K_{1c}$ en ren materialegenskap.

Slagprovning (Charpy) med en anvisad provstav mäter i stället slagseghet, energin för att slå av staven. Den gör det möjligt att jämföra materials seghet och bestämma omslagstemperaturen, men ger inget sätt att uttrycka seghet som en materialegenskap.$kuggfri$, null, 131, false, $kuggfri$c5902ee0b$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: kortet sa att brottseghet bestäms med slagprovning, men slagprovning mäter slagseghet; Canvas, Kapitel_08 Seghet och Brott, s. 8; Canvas, Kapitel_08 Seghet och Brott, s. 16; Canvas, Kapitel_08 Seghet och Brott, s. 21$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('99cb64e2-2ad5-5bf6-a9cf-01fdd9571678', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$brottseghet$kuggfri$, $kuggfri$Brottseghet$kuggfri$, $kuggfri$Ett mått på materialets seghet, hur mycket energi som behövs för att driva en
spricka. Brott fås när spänningsintensiteten vid sprickspetsen är högre än brottsegheten.$kuggfri$, null, 132, false, $kuggfri$c08d5d658$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('95ce58de-0758-5300-b2da-cfeda7f1e9dd', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$hogcykelutmattning$kuggfri$, $kuggfri$Högcykelutmattning$kuggfri$, $kuggfri$Utmattning är brott som uppkommer vid cyklisk belastning. Vid högcykelutmattning är belastningen under sträckgränsen, och materialet plasticerar bara lokalt
vid sprickspetsen, vilket ger ett stort antal cykler till brott.$kuggfri$, null, 133, true, $kuggfri$cf45f3841$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('aec8731f-4b78-5bd7-82c7-91d8f13fa20b', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$slagseghet$kuggfri$, $kuggfri$Slagseghet$kuggfri$, $kuggfri$Den energi som går åt för att slå av en anvisad provstav. Ett mått på hur segt eller sprött materialet är.$kuggfri$, null, 134, true, $kuggfri$c01d6c662$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('ba88eb7f-d3db-5349-ab49-7b8c7aeffce9', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$ja-nej-omslagstemperatur-finns-hos$kuggfri$, $kuggfri$Omslagstemperatur finns hos vanligt (ferritiskt) stål men inte hos aluminium och austenitiskt rostfritt stål.$kuggfri$, $kuggfri$Sant. Vid låga temperaturer blir vissa metaller spröda, men metaller med FCC-struktur förblir duktila även vid de lägsta temperaturerna. Aluminium och austenit (FCC-järn) har FCC-struktur, så aluminium och austenitiska rostfria stål har ingen omslagstemperatur. Vanligt stål består av ferrit (BCC-järn) och perlit och går från segt till sprött beteende under omslagstemperaturen.

Tentan 2020 hade påståendet med bara "rostfritt stål" och facit ja; det gäller de austenitiska rostfria stålen, därför är påståendet preciserat.$kuggfri$, null, 135, false, $kuggfri$c32ea67ee$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Tentamen Materialteknik med svar 2020-10-24, s. 2; Canvas, Kapitel_08 Seghet och Brott, s. 31; Canvas, Fö 12 Stål, s. 17; Canvas, Fö 12 Stål, s. 18; Canvas, Fö 13 Aluminium och andra metaller, s. 3; Canvas, Short_dictionary_ v2026, s. 2$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('fa0f6670-4e74-5d91-aec7-552d8f350dd5', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$ja-nej-utmattningsgransen-ar-antalet$kuggfri$, $kuggfri$Utmattningsgränsen är antalet cykler till brott vid en viss spänning.$kuggfri$, $kuggfri$Falskt. Utmattningsgränsen är en spänningsamplitud, inte ett antal cykler: under den inträffar brott inte alls eller först efter ett mycket stort antal cykler (t.ex. fler än $10^7$). Antalet cykler till brott vid en viss spänningsamplitud är utmattningslivslängden $N_f$, som kan läsas av i S-N-kurvan.$kuggfri$, null, 136, false, $kuggfri$c94c67dc3$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Tentamen Materialteknik med svar 2020-10-24, s. 2; Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 5; Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 6$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('44fded3b-b47b-5b74-9495-07fbb279c6d9', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$ja-nej-sproda-brott-foljer-alltid$kuggfri$, $kuggfri$Spröda brott följer alltid korngränserna.$kuggfri$, $kuggfri$Falskt. En spröd brottyta kan vara både interkristallin (längs korngränserna) och transkristallin (genom kornen). Ett sprött klyvbrott följer atomplanen. Brott längs korngränserna uppstår när korngränserna har försvagats, t.ex. av föroreningar som samlats där eller av kemiskt angrepp.$kuggfri$, null, 137, false, $kuggfri$c40e2fd9a$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Tentamen Materialteknik med svar 2020-10-24, s. 2; Canvas, Fö 9 Brott och brottseghet, s. 16; Canvas, Svar Materialteknik 2019-10-26, s. 2; Canvas, Kapitel_08 Seghet och Brott, s. 32$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('7ff14f04-381a-5fd9-901a-f51881b05291', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$utmattningsgrans$kuggfri$, $kuggfri$Utmattningsgräns$kuggfri$, $kuggfri$Den spänning under vilken inte utmattning sker.$kuggfri$, null, 138, true, $kuggfri$c737c3b0e$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('41b15a13-a92a-5380-bc10-a0719221fd31', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$segt-brott$kuggfri$, $kuggfri$Segt brott$kuggfri$, $kuggfri$Ett brott som föregås av mycket plasticering. Lång töjning innan brott sker med andra ord.$kuggfri$, null, 139, true, $kuggfri$ce8a483c6$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('b954d8c5-9a30-5d8e-84d1-a6382f200125', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$quiz-brott-hos-metaller-2-rattta-svar$kuggfri$, $kuggfri$Brott hos metaller: vilka påståenden är sanna?$kuggfri$, $kuggfri$För att en spricka ska växa måste tillräckligt yttre arbete utföras, och brottsegheten beror på energin som krävs för att driva sprickan. Sprickor växer när spänningsintensitetsfaktorn överskrider det kritiska värdet $K_{1c}$. Hög E-modul ger inte hög brottseghet: keramer har hög styvhet men sprött beteende. Högre sträckgräns minskar den plastiska zonen vid sprickspetsen och ger lägre seghet.

I quizen stod "Segt brott fås när spänningsintensitetsfaktorn är större än brottsegheten". Villkoret gäller sprickväxt i allmänhet, inte specifikt segt brott, så alternativet är omformulerat.$kuggfri$, null, 140, false, $kuggfri$cc5884135$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Brottegenskaper är tätt kopplade till energi.","correct":true},{"text":"Material med hög E-modul har alltid hög brottseghet.","correct":false},{"text":"Material med hög sträckgräns har alltid hög brottseghet.","correct":false},{"text":"En spricka växer när spänningsintensitetsfaktorn överskrider brottsegheten.","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 3, fråga 7; Canvas, Kapitel_08 Seghet och Brott, s. 14; Canvas, Kapitel_08 Seghet och Brott, s. 18; Canvas, Kapitel_08 Seghet och Brott, s. 37; Canvas, Fö 9 Brott och brottseghet, s. 7; Canvas, Tentamen med svarsförslag MTT085 251030, uppgift 1f$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('944b531f-0c68-5450-8e5a-4cc0e02c129d', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$quiz-brott-2-ratta-svar$kuggfri$, $kuggfri$Brott i metaller och spröda material: vilka påståenden är sanna?$kuggfri$, $kuggfri$Kursen delar in brott i spröda och sega brott, inte elastiska och plastiska. Ett segt brott i en metall uppstår genom att hålrum bildas vid inneslutningar och växer samman, och ett sprött klyvbrott separerar atomerna; brott längs korngränserna kräver att korngränserna har försvagats, t.ex. av föroreningar eller kemiskt angrepp. I spröda material ger den största defekten störst spänning och brottet börjar där, eftersom $K_1 = Y\sigma\sqrt{\pi c}$ ökar med spricklängden.$kuggfri$, null, 141, false, $kuggfri$c8130e47f$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Brott delas in i elastiska brott och plastiska brott.","correct":false},{"text":"När en metall går sönder går brottet oftast längs korngränserna.","correct":false},{"text":"I metaller går brottet bara undantagsvis längs korngränserna, t.ex. när föroreningar har försvagat dem.","correct":true},{"text":"Hos spröda material är storleken på defekter som sprickor och porer avgörande för brottspänningen.","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 3, fråga 10; Canvas, Kapitel_08 Seghet och Brott, s. 15; Canvas, Kapitel_08 Seghet och Brott, s. 27; Canvas, Kapitel_08 Seghet och Brott, s. 28; Canvas, Kapitel_08 Seghet och Brott, s. 32; Canvas, Fö 9 Brott och brottseghet, s. 15$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('4c9565c1-ef54-51dc-b4f8-34f07396ab37', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$brott-seghet-definition$kuggfri$, $kuggfri$Vad menas med seghet (toughness) i kursen?$kuggfri$, $kuggfri$Seghet är motståndet mot spricktillväxt. Motståndet mot plastisk deformation är hållfasthet, den elastiska deformationen beskrivs av styvheten och förlängningen till brott är duktilitet (brottförlängning). Seghet kan inte mätas med ett vanligt dragprov, eftersom provstaven inte har någon spricka att börja från.$kuggfri$, null, 142, false, $kuggfri$c99860ae9$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Ett materials motstånd mot plastisk deformation","correct":false},{"text":"Ett materials motstånd mot spricktillväxt","correct":true},{"text":"Hur mycket ett material deformeras elastiskt när det belastas","correct":false},{"text":"Hur mycket ett material kan förlängas innan brott i ett dragprov","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_08 Seghet och Brott, s. 7; Canvas, Kapitel_08 Seghet och Brott, s. 2$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('d1d0c8a9-6995-5bed-9a14-8f631921a3e7', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$brott-spanningsintensitetsfaktor$kuggfri$, $kuggfri$Hur beräknas spänningsintensitetsfaktorn $K_1$ för en spricka med längden $c$ i en plåt under dragspänningen $\sigma$?$kuggfri$, $kuggfri$Den lokala spänningen framför sprickspetsen skalar med $\sigma\sqrt{\pi c}$, så $K_1 = Y\sigma\sqrt{\pi c}$, där $Y$ är en geometrisk konstant (för en spricka i en bred plåt, $c \ll w$, är $Y$ ungefär 1). Enheten blir $\text{MPa}\sqrt{\text{m}}$, samma som för brottseghet, och sprickan växer när $K_1$ överskrider $K_{1c}$. Det är spänningen och inte E-modulen som driver sprickan, och $K_1$ ökar med roten ur spricklängden, inte linjärt.$kuggfri$, null, 143, false, $kuggfri$c53e4cf2c$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"$K_1 = Y\\sigma\\sqrt{\\pi c}$","correct":true},{"text":"$K_1 = Y\\sigma\\,\\pi c$","correct":false},{"text":"$K_1 = Y\\sigma/\\sqrt{\\pi c}$","correct":false},{"text":"$K_1 = YE\\sqrt{\\pi c}$","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_08 Seghet och Brott, s. 13; Canvas, Kapitel_08 Seghet och Brott, s. 14; Canvas, Fö 9 Brott och brottseghet, s. 9$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('ca575193-3da1-5fc2-9afc-c3c7c1b054ea', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$brott-omslagstemperatur$kuggfri$, $kuggfri$Omslagstemperatur$kuggfri$, $kuggfri$Den temperatur där ett material går från segt (duktilt) till sprött brottbeteende, duktilt/sprött omslag (ductile-to-brittle transition). Under omslagstemperaturen blir materialet sprött. Den bestäms med slagprovning. Vissa metaller, t.ex. vanligt (ferritiskt) stål, och alla polymerer har en omslagstemperatur, medan metaller med FCC-struktur förblir duktila även vid de lägsta temperaturerna.$kuggfri$, null, 144, false, $kuggfri$c30e4a263$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Short_dictionary_ v2026, s. 4; Canvas, Svar Materialteknik 2019-10-26, s. 2; Canvas, Kapitel_08 Seghet och Brott, s. 10; Canvas, Kapitel_08 Seghet och Brott, s. 31$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('3006171a-c2da-59f5-ab1e-8e40a33da707', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$utm-lagcykelutmattning$kuggfri$, $kuggfri$Lågcykelutmattning$kuggfri$, $kuggfri$Utmattning där spänningsnivåerna varierar över sträckgränsen men under draghållfastheten, så att materialet deformeras både elastiskt och plastiskt i varje cykel (hysteresloop). Livslängden är kort räknat i antal cykler, den vänstra delen av livslängdsdiagrammet. Lågcykelutmattning provas oftast töjningsstyrt, och livslängden beskrivs av Coffins lag.$kuggfri$, null, 145, false, $kuggfri$c9b37d84b$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 3; Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 6; Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 7$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('b0369e8f-e7ba-5700-b0e5-9e30598c2b9d', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$utm-basquin-hcf$kuggfri$, $kuggfri$Vilken lag beskriver utmattningslivslängden vid högcykelutmattning (HCF)?$kuggfri$, $kuggfri$Basquins lag beskriver högcykelutmattning, där spänningarna ligger under sträckgränsen och deformationen är elastisk. Coffins lag gäller lågcykelutmattning och använder det plastiska töjningsintervallet. Båda lagarna gäller komponenter som cyklas med konstant amplitud kring medelspänningen noll. Paris lag beskriver spricktillväxt per cykel och Palmgren-Miners regel skadeackumulering när amplituden varierar.$kuggfri$, null, 146, false, $kuggfri$caf7cab09$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Basquins lag, $\\Delta\\sigma\\,N_f^{\\,b} = C_1$","correct":true},{"text":"Coffins lag, $\\Delta\\varepsilon^{pl}N_f^{\\,c} = C_2$","correct":false},{"text":"Paris lag, $dc/dN = A\\,\\Delta K^m$","correct":false},{"text":"Palmgren-Miners regel, $\\sum N_i/N_{f,i} = 1$","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 6; Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 11; Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 15$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('7cd7d1a9-b072-5026-80d5-91437bb72df4', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$utm-exempel-basquin-livslangd$kuggfri$, $kuggfri$En komponent följer Basquins lag med $b = 0{,}1$ och håller 200 000 cykler vid spänningsamplituden 100 MPa (medelspänning noll). Ungefär hur många cykler håller den om amplituden ökas till 120 MPa?$kuggfri$, $kuggfri$Basquins lag ger $\Delta\sigma_1 N_1^{\,b} = \Delta\sigma_2 N_2^{\,b}$, alltså $N_2 = N_1\left(\dfrac{\Delta\sigma_1}{\Delta\sigma_2}\right)^{1/b} = 200\,000\left(\dfrac{200}{240}\right)^{10} \approx 32\,300$ cykler. En ökning av spänningsamplituden med 20 % minskar livslängden med 84 %: utmattning är mycket känslig för spänningsnivån.

167 000 cykler fås om exponenten $1/b$ glöms bort, 196 000 om man använder $b$ i stället för $1/b$ och 1 240 000 om kvoten vänds.$kuggfri$, null, 147, false, $kuggfri$c72bc19e7$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"1 240 000 cykler","correct":false},{"text":"196 000 cykler","correct":false},{"text":"167 000 cykler","correct":false},{"text":"32 300 cykler","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 8; Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 6$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('1ac749e6-f7b1-5808-b2d4-8f1be71bcf9f', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$utm-paris-lag$kuggfri$, $kuggfri$Vad beskriver Paris lag, $dc/dN = A\,\Delta K^m$?$kuggfri$, $kuggfri$Paris lag beskriver spricktillväxten per cykel, $dc/dN$, som funktion av $\Delta K = K_{max} - K_{min} = \Delta\sigma\sqrt{\pi c}$. Eftersom sprickan växer ökar $\Delta K$ med tiden vid konstant cyklisk spänning, och snabbt brott inträffar när $K_{max}$ når $K_{1c}$. Lagen används för att beräkna hur många cykler som kan tillåtas innan sprickan når en farlig längd. De andra alternativen beskriver Basquins lag, Palmgren-Miners regel och Goodmans regel.$kuggfri$, null, 148, false, $kuggfri$c89b26d1f$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Hur mycket en utmattningsspricka växer per cykel som funktion av det cykliska spänningsintensitetsintervallet","correct":true},{"text":"Hur livslängden beror på spänningsamplituden vid högcykelutmattning","correct":false},{"text":"Hur skadan ackumuleras när spänningsamplituden varierar","correct":false},{"text":"Hur en medelspänning minskar det tillåtna spänningsintervallet","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 14; Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 15; Canvas, Läsanvisningar Kapitel 9, s. 1$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('ab1e0c14-84f2-53cf-af36-6ded72f2987f', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$utm-palmgren-miner$kuggfri$, $kuggfri$Enligt Palmgren-Miners regel inträffar utmattningsbrott när summan $\sum N_i/N_{f,i}$ når 1.$kuggfri$, $kuggfri$Sant. När den cykliska spänningsamplituden ändras beräknas livslängden med Palmgren-Miners regel för linjär skadeackumulering, $\sum_{i=1}^{n} N_i/N_{f,i} = 1$. Här är $N_i$ antalet cykler med amplitud $i$ och $N_{f,i}$ livslängden om hela belastningen hade haft den amplituden.$kuggfri$, null, 149, false, $kuggfri$c4ae83c78$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 11$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('a7ca1ce6-f19e-558f-8588-15330e37d255', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$utm-goodman-medelspanning$kuggfri$, $kuggfri$Hur påverkar en medelspänning i drag utmattningslivslängden, enligt Goodmans regel?$kuggfri$, $kuggfri$Enligt Goodmans regel, $\Delta\sigma_{\sigma_m} = \Delta\sigma_{\sigma_m=0}\left(1 - \sigma_m/\sigma_{ts}\right)$, motsvarar ett spänningsintervall med medelspänningen $\sigma_m$ ett större intervall vid medelspänningen noll, och det korrigerade intervallet sätts in i Basquins lag. I exempel 9.2 ($\sigma_{ts} = 200$ MPa) sjunker livslängden från 200 000 till ungefär 11 550 cykler när medelspänningen ökar från 0 till 50 MPa. Utmattning är mycket känslig för medelspänningen, och därför bör restspänningar i ytan helst vara tryckspänningar.$kuggfri$, null, 150, false, $kuggfri$cefc7165e$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Livslängden minskar","correct":true},{"text":"Livslängden ökar, eftersom materialet deformationshärdas","correct":false},{"text":"Livslängden påverkas inte, bara spänningsamplituden spelar roll","correct":false},{"text":"Medelspänningen påverkar bara lågcykelutmattning","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 4; Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 9; Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 10$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('3bd22354-9b0f-5657-83be-2a6b21f1dca8', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$utm-battre-utmattningsegenskaper$kuggfri$, $kuggfri$Vilka åtgärder ger bättre utmattningsegenskaper hos en metallkomponent?$kuggfri$, $kuggfri$Goda utmattningsegenskaper fås med liten kornstorlek, små inneslutningar och porer, släta ytor utan spänningskoncentrationer, skydd mot korrosion och tryckspänningar i ytan (kulbombning, nitrering, karburisering). Sprickor växer bara under dragdelen av en cykel, så tryckspänningar i ytan håller sprickorna stängda och minskar medelspänningen där, medan dragrestspänningar ökar den. Utmattningssprickor initieras oftast vid ytan, så en grov yta försämrar livslängden.$kuggfri$, null, 151, false, $kuggfri$cd82e5325$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Liten kornstorlek","correct":true},{"text":"Grov, obearbetad yta","correct":false},{"text":"Tryckrestspänningar i ytan, t.ex. genom kulbombning","correct":true},{"text":"Dragrestspänningar i ytan","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 39; Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 37; Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 10; Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 28$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('9951e13a-5c5a-5f4c-a8fc-e8fcf7c9da50', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$utm-initiering-vid-ytan$kuggfri$, $kuggfri$Utmattningssprickor initieras oftast vid ytan.$kuggfri$, $kuggfri$Sant. I ytliga korn med lämplig orientering bildas persistenta glidband (PSB) med mycket dislokationsaktivitet, som ger intrusioner och extrusioner i ytan. Atmosfär och oxidation skapar svaga zoner, och lokala spänningskoncentrationer gör att sprickan startar där. Sprickor kan initieras inne i materialet när ytan är jämn och har tryckrestspänningar, eller när det finns stora inre defekter som inneslutningar och porer.$kuggfri$, null, 152, false, $kuggfri$ced66a892$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 28; Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 29$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('a9bb99d5-5fd0-5385-848c-0f9bd8199bd5', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$utm-tre-stadier-brottyta$kuggfri$, $kuggfri$Beskriv de tre stadierna i ett utmattningsbrott och hur brottytan ser ut.$kuggfri$, $kuggfri$1. **Initiering:** oftast som en skjuvspricka i ytliga korn med lämplig orientering (glidband), där ytan eller en spänningskoncentration hjälper till.
2. **Tillväxt:** sprickan korsar några korngränser och växer sedan som en lång spricka vinkelrätt mot huvudspänningen (mod 1). Materialet framför sprickspetsen deformeras plastiskt i varje cykel, och sprickan växer en liten bit per cykel. På brottytan syns striationer (avstånd typiskt ca 1 µm) och makroskopiska linjer (beach marks).
3. **Slutbrott (restbrott):** när spricklängden har blivit så stor att spänningsintensiteten når $K_{1c}$ vid den pålagda spänningen brister resten av tvärsnittet snabbt.$kuggfri$, null, 153, false, $kuggfri$c29db313a$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 28; Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 30; Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 32; Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 33; Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 15$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('c0ed24fd-c97a-5e4b-88b7-e237d940b6c1', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$brott-sprott-brottyta-kannetecken$kuggfri$, $kuggfri$Vilka kännetecken hör till ett sprött brott?$kuggfri$, $kuggfri$Ett sprött brott sker utan nämnvärd plastisk deformation och ger en relativt jämn, glänsande och kornig brottyta; i keramer och glas är klyvbrott karakteristiskt. En matt, ojämn skål- och konformad yta och hålrum som växer samman vid inneslutningar kännetecknar i stället segt brott. Sprött brott uppträder främst vid låga temperaturer, höga belastningshastigheter och i spröda material.$kuggfri$, null, 154, false, $kuggfri$c010fb439$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Det sker utan nämnvärd plastisk deformation, ofta plötsligt","correct":true},{"text":"Brottytan är matt och ojämn, skål- och konformad","correct":false},{"text":"Brottytan är relativt jämn och glänsande med kornig struktur","correct":true},{"text":"Hålrum bildas vid inneslutningar och växer samman till brott","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Svarsförslag uppgift 4-6, IMS085 251030, s. 1; Canvas, Kapitel_08 Seghet och Brott, s. 27; Canvas, Kapitel_08 Seghet och Brott, s. 28$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('7e363efd-b54d-5879-aada-db61817436a6', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$brott-weibullmodul$kuggfri$, $kuggfri$Vad innebär ett högt värde på Weibullmodulen $m$ för en keram?$kuggfri$, $kuggfri$Weibullmodulen styr hur känslig brottsannolikheten är för spänningen: låga värden ger stor spridning, höga värden ger betydligt större säkerhet för överlevnad under referensspänningen. Weibullstatistik används för keramer eftersom sannolikheten att en komponent innehåller en defekt av kritisk storlek ökar med volymen, så brottspänningen beror på storleken. Referensspänningen och $m$ bestäms empiriskt och är inte ett mått på brottsegheten.$kuggfri$, null, 155, false, $kuggfri$cadc7875f$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Liten spridning i brottspänning och större säkerhet för överlevnad under referensspänningen","correct":true},{"text":"Stor spridning i brottspänning","correct":false},{"text":"Hög brottseghet $K_{1c}$","correct":false},{"text":"Att brottspänningen inte beror på komponentens storlek","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_08 Seghet och Brott, s. 34; Canvas, Kapitel_08 Seghet och Brott, s. 35$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('672973b2-e112-5592-b117-bfd94c151879', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$brott-exempel-ct-prov-last$kuggfri$, $kuggfri$Ett CT-prov ($K_{1c} = 25\ \text{MPa}\sqrt{\text{m}}$, $w = 50$ mm, $b = 20$ mm, sprickan $c = 10$ mm) följer $K_{1c} = 1{,}64\,\dfrac{F^*}{bw}\sqrt{\pi c}$. Vilken last $F^*$ krävs för brott?$kuggfri$, $kuggfri$$F^* = \dfrac{K_{1c}\,b\,w}{1{,}64\sqrt{\pi c}} = \dfrac{25\cdot 10^6 \cdot 0{,}020 \cdot 0{,}050}{1{,}64\sqrt{\pi \cdot 0{,}010}} \approx 86$ kN. I exempel 8.2 räcker därför inte en provningsmaskin med maxlasten 50 kN. 141 kN fås om faktorn 1,64 glöms bort och 8,6 kN om en tiopotens blir fel.$kuggfri$, null, 156, false, $kuggfri$cf9e00c2b$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"50 kN","correct":false},{"text":"86 kN","correct":true},{"text":"8,6 kN","correct":false},{"text":"141 kN","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_08 Seghet och Brott, s. 17; Canvas, Kapitel_08 Seghet och Brott, s. 14$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('821db7af-efc3-5e48-ad7d-4dd5d12bc613', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2207b77a-11fc-5b02-871d-12c0759eeabe', $kuggfri$vad-ar-brottseghet$kuggfri$, $kuggfri$Vad är brottseghet?$kuggfri$, $kuggfri$Ett materials motstånd mot spricktillväxt. Brottsegheten $K_{1c}$ ($\text{MPa}\sqrt{\text{m}}$; 1 för lastmod 1, c för kritisk) är det kritiska värdet på spänningsintensitetsfaktorn.

* En spricka växer när spänningsintensitetsfaktorn $K_1$ överskrider $K_{1c}$. Vid statisk last växer sprickan inte så länge $K_1$ är mindre än $K_{1c}$ (vid cyklisk last kan en utmattningsspricka däremot växa lite för varje cykel, se Paris lag).
* $K_1 = Y\sigma\sqrt{\pi c}$ tar hänsyn till både last (spänningen $\sigma$) och spricklängd $c$.
* Brottsegheten beror på energin som krävs för att driva sprickan: $K_{1c} = \sqrt{E\,G_c}$.$kuggfri$, null, 157, false, $kuggfri$cf996c9bc$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: brottvillkoret var omvänt (kortet sa att brott sker när K1c > K1, så stod det också på en bild 2025); Canvas, Kapitel_08 Seghet och Brott, s. 7; Canvas, Kapitel_08 Seghet och Brott, s. 14; Canvas, Fö 9 Brott och brottseghet, s. 7; Canvas, Fö 9 Brott och brottseghet, s. 10; Canvas, Kapitel_08 Seghet och Brott, s. 13; Canvas, Kapitel_08 Seghet och Brott, s. 18; Canvas, 2026-09-23 Kapitel_09 Utmattning, s. 15$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('42cd2906-dbe4-574a-95b4-939dbae3d88c', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$vad-hander-med-material-nar$kuggfri$, $kuggfri$Vad händer med material när temperaturen höjs?$kuggfri$, $kuggfri$* Atomerna vibrerar med större amplitud
* Atombindningarna försvagas något
* Atomerna rör sig lättare (diffusion)
* Fasomvandlingar vid bestämda temperaturer eller temperaturintervall
* Kemiska reaktioner går snabbare, ofta med exponentiell ökning$kuggfri$, null, 158, false, $kuggfri$c51588c64$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: "atomerna börjar vibrera" var fel, atomerna vibrerar redan och det är amplituden som ökar med temperaturen; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 2; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 7$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('4e2ac4fa-a0d0-54ee-9c03-80217a77bd04', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$beskriv-utforligt-vad-smalttemperatur$kuggfri$, $kuggfri$Beskriv utförligt vad smälttemperatur och glasomvandlingstemperatur är och vilka material respektive är relevant för.$kuggfri$, $kuggfri$Smälttemperatur:

* Kristallina material
* Metaller, keramer
* Går från fast till "lågviskös"
vätska vid smälttemperaturen, "Tm"

Glasomvandlingstemperatur

* Amorfa material
* Termoplaster, glas
* Gradvis övergång från fast till "viskös" vid
glasomvandlingstemperaturen "Tg".$kuggfri$, null, 159, true, $kuggfri$c3adc7f76$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('e7f65988-e404-597e-8ffe-eb9835e1a120', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$vad-definierar-ett-materials-relevanta$kuggfri$, $kuggfri$Vad definierar ett materials relevanta användningstemperatur?$kuggfri$, $kuggfri$Maximal användningstemperatur begränsas
t.ex. av:

* Försämrade mekaniska egenskaper
* Fasomvandlingar och kemiska förändringar
* Oxidation

Minimal användningstemperatur
begränsas t.ex. av:

* Sprödhet$kuggfri$, null, 160, true, $kuggfri$c82de5c58$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('c455cea6-92aa-5e5b-8caa-56330ef26788', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$beskriv-vad-ett-materials-specifika$kuggfri$, $kuggfri$Beskriv vad ett materials specifika värmekapacitet innebär för materialet.$kuggfri$, $kuggfri$Värmekapacitet är ett mått på hur mycket energi som krävs för att höja temperaturen i ett material.$kuggfri$, null, 161, false, $kuggfri$c1dfdb3bf$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('dd31f06f-87e6-5917-b386-e6757657c8cb', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$vad-ar-termisk-utvidgning-respektive$kuggfri$, $kuggfri$Vad är termisk utvidgning respektive termiska spänningar?$kuggfri$, $kuggfri$**Termisk utvidgning:** ett fast ämne expanderar vid uppvärmning eftersom atomerna rör sig längre från varandra. Den termiska töjningen är $\varepsilon_T = \alpha\,(T - T_0)$, där $\alpha$ är den termiska utvidgningskoefficienten (svagt temperaturberoende) och $T_0$ en referenstemperatur. Volymutvidgningen är ungefär tre gånger så stor som den linjära.

**Termiska spänningar:** termisk utvidgning ger upphov till spänningar, till exempel

* när två sammanfogade material har olika $\alpha$, så att det ena expanderar mer än det andra
* av temperaturgradienter, dvs. när olika delar av materialet har olika temperatur

Upprepade temperaturvariationer kan ge termisk utmattning.$kuggfri$, null, 162, false, $kuggfri$c84d2e1bb$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: "termiska gradienter" beskrevs som utvidgningens storlek och riktning på vektorform, men det är temperaturskillnader i materialet; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 13; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 15; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 16$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('66a397bd-fb7c-5288-af49-d83c48ac3e8b', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$vad-har-atombindningar-med-termisk$kuggfri$, $kuggfri$Vad har atombindningar med termisk utvidgning att göra?$kuggfri$, $kuggfri$Ett fast ämne expanderar vid uppvärmning eftersom atomerna rör sig längre från varandra. Starka atombindningar (djup bindningsenergikurva) ger både hög E-modul och hög smälttemperatur, och empiriskt har material med hög E-modul (styva fjädrar) låg utvidgningskoefficient.

Alla kristallina fasta ämnen expanderar ungefär 2 % från absoluta nollpunkten till smältpunkten. Därför är $\alpha$ ungefär omvänt proportionell mot $T_m$: svaga bindningar ger låg smälttemperatur och stor termisk utvidgning.$kuggfri$, null, 163, false, $kuggfri$c1fd9d004$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: kortet påstod att utvidgningskoefficienten beror på temperaturen eftersom bindningsstyrkan gör det, vilket inte stöds av föreläsningen, och upprepade formeln från kortet ovan; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 14; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 15; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 26$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('612ccd11-7365-5b5f-adc2-520a883bccf1', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$vilka-faktorer-ar-avgorande-for-ett$kuggfri$, $kuggfri$Vilka faktorer är avgörande för ett materials termiska ledningsförmåga?$kuggfri$, $kuggfri$Värme leds med två mekanismer:

* Kristallvibrationer (fononer): elastiska vågpaket som färdas med ljudets hastighet men bara en kort sträcka (medelfri väg, vanligen under 0,01 µm) innan de sprids
* Elektroner, som gör att metaller leder värme mycket bra

Både fononer och elektroner överför energi från områden med hög temperatur till områden med låg temperatur.

Fononerna hindras och sprids av kristallstörningar, t.ex. dislokationer och inlösta atomer. Inlösta legeringsatomer är sådana störningar, så legering förbättrar inte en metalls värmeledningsförmåga.$kuggfri$, null, 164, false, $kuggfri$c1c7ad399$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: "rena legeringar har bäst termisk ledningsförmåga" var självmotsägande (legering förbättrar inte ledningsförmågan), och energin går till område med låg temperatur (inte "låg energi"); Canvas, Fö 10 Material och värme, s. 10; Canvas, Fö 10 Material och värme, s. 11; Canvas, Fö 10 Material och värme, s. 12; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 20; Canvas, Quiz vecka 4, fråga 9; Canvas, Ashby et al Materials 3 utgåvan PRELIMINÄR Läsanvisning och detaljerade lärmål Kap 1-12, s. 4$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('7b0b11c5-e7d0-5cdb-9636-62bbd41a124e', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$beskriv-kort-vad-varmeflode-ar-och-hur$kuggfri$, $kuggfri$Beskriv kort vad värmeflöde är och hur det beräknas$kuggfri$, $kuggfri$Värmeflödet $q$ (W/m²) är den värmemängd per tidsenhet och area som leds genom materialet. Vid stationärt tillstånd (steady state) ges det av Fouriers lag, $q = -\lambda\,\Delta T/\Delta x$, där $\lambda$ är värmeledningsförmågan (W/(m·K)) och $\Delta T/\Delta x$ temperaturgradienten. Minustecknet anger att värmen flödar från hög mot låg temperatur.

För en vägg med tjockleken $t$ och temperaturerna $T_i$ och $T_o$ på var sin sida blir effektförlusten $q = \lambda\,(T_i - T_o)/t$.

Om temperaturen i stället ändras med tiden (transient värmeledning) styrs förloppet av den termiska diffusiviteten $a = \lambda/(\rho C_p)$ (m²/s).$kuggfri$, null, 165, false, $kuggfri$c535a01d6$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: kortet påstod att beräkning av värmeflöde inte ingår i kursen, men läsanvisningen 2026 kräver att man kan beräkna värmeflöde vid steady state; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 21; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 22; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 29; Canvas, Ashby et al Materials 3 utgåvan PRELIMINÄR Läsanvisning och detaljerade lärmål Kap 1-12, s. 5$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('40372cb8-24a4-5720-9294-3325e3b400fd', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$vad-ar-diffusion$kuggfri$, $kuggfri$Vad är diffusion?$kuggfri$, $kuggfri$Diffusion i ett fast material är den temperaturberoende process där atomer förflyttar sig genom kristallstrukturen via atomhopp. Rörelsen är slumpmässig men går netto från hög till låg koncentration, så diffusion jämnar ut koncentrationsskillnader. Notera särskilt att:

* Diffusionshastigheten ökar exponentiellt med temperaturen
* Den beror på vilken atom som rör sig i vilken kristall; små atomer rör sig snabbare än stora$kuggfri$, null, 166, false, $kuggfri$c7ea2db70$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: kortet blandade ihop atomdiffusion med temperaturspridning och beskrev diffusion som något som främst gäller gaser och vätskor; Canvas, Tentamen med svarsförslag MTT085 251030, uppgift 1j; Canvas, GLU 02 Fasdiagram, s. 7; Canvas, Fö 10 Material och värme, s. 13$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('7304b2bd-fdea-5abb-a6ea-26586c4eabf9', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$vilka-ar-ficks-1-a-och-2-a-lag$kuggfri$, $kuggfri$Vilka är Ficks 1:a och 2:a lag?$kuggfri$, $kuggfri$Ficks lagar beskriver allmänt hur diffusion beter sig i ett material, det behöver nödvändigtvis inte vara relaterat till temperatur.

Fick's 1:a lag beskriver hur flödet (J) är proportionellt mot den partiella derivatan av koncentrationen och Fick's 2:a beskriver hur den partiella derivatan av koncentrationen med avseende på tiden är proportionell mot andraderivatan av koncentrationen.

Man får en uppsättning partiella differentialekvationer som bäst löses numeriskt.$kuggfri$, null, 167, true, $kuggfri$c002628b7$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('461261dc-a5f2-5329-b11d-66bcc119e764', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$vad-ar-krypning-vad-finns-det-for-olika$kuggfri$, $kuggfri$Vad är krypning? Vad finns det för olika typer av krypning?$kuggfri$, $kuggfri$* Krypning sker vid över cirka ½ av smälttemperaturen
* Ger plastisk (permanent) deformation
* Två typer:
  - Diffusionskrypning
  - Dislokationskrypning

* Primär krypning = snabb deformation tills dislokationer möter hinder
* Steady-state = krypning med konstant töjningshastighet
* Tertiär krypning = Skador i materialet

* Kryphastigheten beror på krypningsmekanism men är allmänt exponentiellt beroende av temperaturen
* Spänningen kan ändra krypmekanism$kuggfri$, null, 168, false, $kuggfri$c9a78f03b$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('c243a915-c6e2-5c03-af1c-d492dc7cec90', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$beskriv-narmare-vad-diffusionskrypning$kuggfri$, $kuggfri$Beskriv närmare vad diffusionskrypning är.$kuggfri$, $kuggfri$Diffusionskrypning:

* Förändring av kristallernas korn
m.h.a. diffusion
* Kornen förlängs i
belastningsriktningen$kuggfri$, null, 169, true, $kuggfri$c7a27a1d1$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('90041ba4-0b37-5e7b-bfe3-f589755386f3', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$beskriv-narmare-vad-dislokationskrypning$kuggfri$, $kuggfri$Beskriv närmare vad dislokationskrypning är.$kuggfri$, $kuggfri$Dislokationskrypning:

* Plastisk deformation m.h.a.
dislokationsrörelse
* Diffusion hjälper dislokationerna att
komma runt hinder$kuggfri$, null, 170, true, $kuggfri$cef036588$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('f0ade95a-2159-538e-9fc9-7a71b74ba8c4', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$vad-ar-ett-krypbrott$kuggfri$, $kuggfri$Vad är ett krypbrott?$kuggfri$, $kuggfri$Krypbrott fås när det har
initierats porer som har tillväxt
till brott till följd av krypning.$kuggfri$, null, 171, true, $kuggfri$c3dc6cab1$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('a2697d01-2f97-5e6b-ba82-dc00af47da4a', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$krypning$kuggfri$, $kuggfri$Krypning$kuggfri$, $kuggfri$Långsam plastisk (permanent) deformation som beror på temperatur, tid och last. I metaller sker den vid temperaturer över cirka halva smälttemperaturen (i kelvin), och kryphastigheten ökar exponentiellt med temperaturen.

Två mekanismer: diffusionskrypning och power-law-krypning (dislokationskrypning). Vilken mekanism som dominerar beror på temperatur och spänning. Förloppet delas in i primär krypning (snabb deformation tills dislokationerna möter hinder), steady state-krypning med konstant töjningshastighet och tertiär krypning, där skador uppstår i materialet.$kuggfri$, null, 172, false, $kuggfri$c7b300b25$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Fö 10 Material och värme, s. 14; Canvas, Fö 10 Material och värme, s. 15; Canvas, Fö 10 Material och värme, s. 16; Canvas, Fö 10 Material och värme, s. 17; Canvas, Läsanvisningar Kapitel 12 och 13, s. 1; Canvas, Svar Materialteknik 2018-10-27, s. 1; Canvas, Svarsförslag Tentamen IMS085 2023-10-25, s. 1$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('ec0cbb3f-b72d-511a-a44b-4f2de7843737', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$aktiveringsenergi$kuggfri$, $kuggfri$Aktiveringsenergi$kuggfri$, $kuggfri$Den energibarriär som måste övervinnas m.h.a. termisk energi för att vissa processer skall kunna
ske, t.ex. kemiska reaktioner, diffusion, krypning.$kuggfri$, null, 173, true, $kuggfri$cfa1c56ac$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('8c55cc97-bd3e-51dd-99fa-c4487047393e', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$specifik-varmekapacitet$kuggfri$, $kuggfri$Specifik värmekapacitet$kuggfri$, $kuggfri$Värmekapacitet är den mängd energi som krävs för att höja temperaturen en grad (1 K) i en viss mängd material.
Specifik värmekapacitet, även kallad värmekapacitivitet, är den energi som krävs för att höja temperaturen 1 K för 1 kg av materialet, J/(kg·K).$kuggfri$, null, 174, false, $kuggfri$c48b24b7a$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 8; Canvas, Short_dictionary_ v2026, s. 13; Canvas, Tentamen Materialteknik med svar 2022-11-29, s. 2$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('57418a68-f6a4-50bb-9f40-1b3abe8fd4e8', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$diffusionskoefficient$kuggfri$, $kuggfri$Diffusionskoefficient$kuggfri$, $kuggfri$Ett mått på hur snabbt atomer rör sig (diffunderar) i ett material. Beror på temperaturen och vilka atomer som diffunderar, och i vilket material.$kuggfri$, null, 175, true, $kuggfri$cfdaa7092$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('f713be65-1239-5baa-8de6-e4180f688183', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$krypning-metaller$kuggfri$, $kuggfri$Krypning (metaller)$kuggfri$, $kuggfri$Plastisk deformation som beror på tid, temperatur och last.$kuggfri$, null, 176, false, $kuggfri$ce071af7a$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('8fb71a02-bb47-524d-9d58-e83dcd056a5d', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$ja-nej-krypning-ar-ett-fenomen-som-bara$kuggfri$, $kuggfri$Krypning i metaller sker vid temperaturer över ungefär halva smälttemperaturen, räknat i kelvin.$kuggfri$, $kuggfri$Sant. Krypning är långsam plastisk deformation som beror på temperatur, tid och last, och i metaller sker den över cirka $0{,}5\,T_m$ (i kelvin). Vad som är en "hög" temperatur beror alltså på materialets smälttemperatur.

Tentan 2020 hade påståendet "Krypning är ett fenomen som bara uppstår vid höga temperaturer" med facit ja. Det är omformulerat, eftersom "höga temperaturer" bara blir entydigt i förhållande till smälttemperaturen.$kuggfri$, null, 177, false, $kuggfri$c512281e1$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Tentamen Materialteknik med svar 2020-10-24, s. 2; Canvas, Fö 10 Material och värme, s. 14; Canvas, Svar Materialteknik 2018-10-27, s. 1; Canvas, Svarsförslag Tentamen IMS085 2023-10-25, s. 1$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('9b1531a9-6306-5e4c-a812-d45ab526ac9e', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$quiz-vad-ar-ratt-for-temperatur-tva-ratta$kuggfri$, $kuggfri$Vad stämmer om temperatur?$kuggfri$, $kuggfri$Värme är atomer i rörelse: atomerna vibrerar med en amplitud som ökar med temperaturen, så temperaturen hänger ihop med rörelseenergin och inte med bindningarnas potentiella energi. En temperaturhöjning ger större vibrationer, något svagare bindningar, snabbare diffusion, fasomvandlingar och snabbare kemiska reaktioner. Därför påverkas de flesta egenskaper, inte bara de mekaniska.$kuggfri$, null, 178, false, $kuggfri$c683ef8dc$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Den är ett mått på atomernas kinetiska energi (rörelse).","correct":true},{"text":"Den är ett mått på atomernas potentiella energi.","correct":false},{"text":"Den påverkar de flesta av materialens egenskaper.","correct":true},{"text":"Den påverkar bara materialens mekaniska egenskaper.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 4, fråga 1; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 2; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 3; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 7$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('ad588997-b72a-54d0-a338-a25e8d951abc', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$quiz-temperatur-och-material-tva-ratta-svar$kuggfri$, $kuggfri$Temperatur och material: vilka påståenden är sanna?$kuggfri$, $kuggfri$Rena metaller har en distinkt smälttemperatur, medan en legering stelnar inom ett temperaturintervall där smälta och fasta kristaller finns samtidigt (undantaget är eutektisk sammansättning, som stelnar vid en temperatur). Glasomvandlingstemperaturen $T_g$ gäller amorfa material (termoplaster, glas) och är en gradvis övergång från fast till visköst tillstånd, inte en omvandling till glas. Maximal användningstemperatur begränsas av t.ex. försämrade mekaniska egenskaper, fasomvandlingar och oxidation och bestäms av praktiska erfarenheter, inte av en fast 50 %-gräns.

Quizens formuleringar "Bara rena kristallina material har en väl definierad smälttemperatur" och "Värmekapacitivitet är kvoten mellan tillsatt energi och temperaturökning" är preciserade efter föreläsningarna.$kuggfri$, null, 179, false, $kuggfri$cb43e2f65$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Rena metaller har en distinkt smälttemperatur, medan legeringar i regel har ett smältintervall.","correct":true},{"text":"Glasomvandlingstemperaturen är temperaturen då ett material omvandlas till glas.","correct":false},{"text":"Maximal användningstemperatur är temperaturen då de mekaniska egenskaperna har minskat till 50 %.","correct":false},{"text":"Värmekapacitivitet är den energi som krävs för att höja temperaturen 1 K för 1 kg material.","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 4, fråga 2; Canvas, GLU 02 Fasdiagram, s. 9; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 4; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 9; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 4; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 6; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 8$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('91bff1e0-b5ff-5662-8e61-d36d5478ac29', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$quiz-nar-man-hojer-temperaturen-2-ratt$kuggfri$, $kuggfri$Vad händer när man höjer temperaturen i ett fast material?$kuggfri$, $kuggfri$Ett fast ämne expanderar vid uppvärmning eftersom atomerna rör sig längre från varandra; samma massa tar större volym, så densiteten minskar. Diffusionen, och därmed t.ex. krypningen, ökar exponentiellt med temperaturen. Det gäller materialen generellt och är något man tar hänsyn till, t.ex. med en maximal användningstemperatur, inte ett skäl att undvika ett material. Vid högre temperatur försvagas atombindningarna och de mekaniska egenskaperna försämras; brottgränsen ökar inte.

Quizens "för alla material" är struket ur det rätta alternativet.$kuggfri$, null, 180, false, $kuggfri$c9f9137c4$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Densiteten minskar, eftersom materialet expanderar.","correct":true},{"text":"Diffusionshastigheten ökar exponentiellt med temperaturen.","correct":true},{"text":"Material vars egenskaper ändras exponentiellt med temperaturen bör undvikas.","correct":false},{"text":"Sträckgränsen minskar men brottgränsen ökar.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 4, fråga 3; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 2; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 3; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 6; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 15; Canvas, GLU 02 Fasdiagram, s. 7$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('b39a64bd-9691-5720-8dfe-cdb4901672db', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$quiz-diffusion-2-ratt$kuggfri$, $kuggfri$Vad stämmer om diffusion?$kuggfri$, $kuggfri$Diffusion är slumpmässig rörelse av atomer som netto går från hög till låg koncentration, så koncentrationsskillnader jämnas ut, och små atomer rör sig snabbare än stora. Diffusion sker även i polymerer: vid formsprutning måste polymerkedjorna hinna diffundera över gränsen där två smältfronter möts, annars blir svetslinjen svag. Diffusionen ökar exponentiellt med temperaturen och beror på vilken atom som rör sig i vilken kristall. Krom tillsätts i stål för att ge ett skyddande kromoxidskikt (rostfritt stål), inte för att minska diffusionen.$kuggfri$, null, 181, false, $kuggfri$c4e109f49$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Diffusion jämnar ut koncentrationsskillnader.","correct":true},{"text":"Diffusion finns bara i metaller och keramer, inte i amorfa polymerer.","correct":false},{"text":"Stora atomer diffunderar långsammare än små.","correct":true},{"text":"Legering med Cr är det bästa sättet att minska diffusionen i stål.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 4, fråga 5; Canvas, GLU 02 Fasdiagram, s. 7; Canvas, Fö 10 Material och värme, s. 13; Canvas, Svarsförslag uppgift 4-6, IMS085 251030, s. 2; Canvas, Fö 12 Stål, s. 24$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('3d84989b-21c3-540a-b408-690270b58dbd', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$quiz-termiska-egenskaper-2-ratt$kuggfri$, $kuggfri$Termiska egenskaper: vilka påståenden är sanna?$kuggfri$, $kuggfri$Fouriers lag ger värmeflödet vid stationärt tillstånd; minustecknet visar att värmen går mot lägre temperatur. Värme leds av fononer och, i metaller, även av elektroner. Termisk utvidgning är en spänningsfri töjning som uppstår för att atomerna rör sig längre från varandra, inte en plastisk deformation. Fononerna hindras och sprids av kristallstörningar som inlösta atomer, så legering förbättrar inte värmeledningsförmågan.$kuggfri$, null, 182, false, $kuggfri$ce76b745b$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Vid stationärt tillstånd är värmeflödet värmeledningsförmågan gånger temperaturgradienten, $q = -\\lambda\\,\\Delta T/\\Delta x$.","correct":true},{"text":"Värmeledning sker bland annat med fononer (kristallvibrationer).","correct":true},{"text":"Termisk utvidgning ger en plastisk förlängning av materialet.","correct":false},{"text":"En metalls värmeledningsförmåga förbättras när den legeras.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 4, fråga 9; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 12; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 15; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 21; Canvas, Fö 10 Material och värme, s. 10; Canvas, Fö 10 Material och värme, s. 11$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('85c89155-272c-5ebf-b602-d9a363232f1a', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$varme-fourier-berakning$kuggfri$, $kuggfri$En ugnsvägg har isolering med $\lambda = 0{,}04$ W/(m·K) och tjockleken 0,10 m. Inne är det 200 °C och ute 20 °C. Hur stort är värmeflödet genom väggen vid stationärt tillstånd?$kuggfri$, $kuggfri$Vid stationärt tillstånd är $q = \lambda\,\dfrac{T_i - T_o}{t} = 0{,}04 \cdot \dfrac{200 - 20}{0{,}10} = 72$ W/m². 7,2 W/m² fås om man glömmer att dela med tjockleken, 0,72 W/m² om man multiplicerar med den och 720 W/m² om tjockleken sätts till 0,01 m. Material med låg värmeledningsförmåga minimerar effektförlusten.$kuggfri$, null, 183, false, $kuggfri$c69484895$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"0,72 W/m²","correct":false},{"text":"7,2 W/m²","correct":false},{"text":"72 W/m²","correct":true},{"text":"720 W/m²","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 22; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 21; Canvas, Ashby et al Materials 3 utgåvan PRELIMINÄR Läsanvisning och detaljerade lärmål Kap 1-12, s. 5$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('e4b9ef81-0d7b-5798-98ba-29e3fc3e06cf', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$varme-alfa-och-smalttemperatur$kuggfri$, $kuggfri$Material med hög smälttemperatur har i regel låg termisk utvidgningskoefficient.$kuggfri$, $kuggfri$Sant. Starka atombindningar ger hög smälttemperatur och hög E-modul, och alla kristallina fasta ämnen expanderar ungefär 2 % från absoluta nollpunkten till smältpunkten. Utvidgningskoefficienten korrelerar därför med $1/T_m$: blylegeringar har högt $\alpha$, medan titanlegeringar och stål har lägre.$kuggfri$, null, 184, false, $kuggfri$c785db418$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 15; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 26$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('c55ec76d-1d64-56ba-9aa1-82f9e3ca4f6a', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '6aaaf25d-9bb7-5fe8-81a0-52e742379456', $kuggfri$varme-undvika-termiska-spanningar$kuggfri$, $kuggfri$Hur kan man undvika stora termiska spänningar mellan två sammanfogade material?$kuggfri$, $kuggfri$Termiska spänningar uppstår när sammanfogade material har olika termisk utvidgningskoefficient $\alpha$, så att det ena expanderar mer än det andra vid en temperaturändring.

* Det enklaste är att välja material med liknande utvidgningskoefficienter, men det är ofta inte möjligt i en given konstruktion.
* Ett alternativ är en graderad fog: mellanliggande material med stegvis ändrat $\alpha$ (t.ex. stål fogat mot en nickellegering med lägre $\alpha$) fungerar som buffert och minskar skillnaden i utvidgning i varje fog.$kuggfri$, null, 185, false, $kuggfri$cab6d6521$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 16; Canvas, 2026-09-25 Kapitel_12 Material och värme, s. 18$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('21ec6dcd-d6ff-57d5-83b7-8f9c9e551096', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$vad-utgor-stal$kuggfri$, $kuggfri$Vad utgör stål?$kuggfri$, $kuggfri$Stål är järn legerat med kol som beroende på kolhalt och tillverkningsförhållanden kan ges olika egenskaper.$kuggfri$, null, 186, true, $kuggfri$c3b344416$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('57c5d9f0-71a4-5cb9-a79f-f28430b575bf', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$beskriv-vad-en-anlopning-ar$kuggfri$, $kuggfri$Beskriv vad en anlöpning är.$kuggfri$, $kuggfri$Anlöpning görs efter martensithärdning, eftersom martensiten är mycket hård men ofta för spröd. Det härdade stålet värms till en måttlig temperatur, under den eutektoida temperaturen 727 °C (i föreläsningens exempel ca 200 till 650 °C, i labb-PM ca 500 °C).

* Martensiten sönderfaller till anlöpt martensit: ferrit med mycket små cementitpartiklar (inte perlit)
* Hårdheten och sträckgränsen sjunker något, men segheten ökar kraftigt
* Temperatur och tid avgör cementitpartiklarnas storlek, så hårdheten kan styras med anlöpningstemperaturen$kuggfri$, null, 187, false, $kuggfri$c3ce3b159$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: kortet angav fel temperatur (precis under ca 910 °C) och fel produkt (perlit + cementit); anlöpning sker vid måttlig temperatur och ger ferrit med fina cementitpartiklar; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 24; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 25; Canvas, Lab_PM_M2_v2026, s. 11; Canvas, Lab_PM_M2_v2026, s. 13; Canvas, Lab_PM_M2_v2026, s. 14; Canvas, Fö 12 Stål, s. 16; Canvas, Fö 12 Stål, s. 23; Canvas, Fö 5 Fasdiagram och mikrostruktur 2, s. 22; Canvas, Fö 5 Fasdiagram och mikrostruktur 2, s. 23$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('fea1c5f8-d9ee-5264-bab3-991773e7f3b2', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$vilken-inverkan-har-kolhalten-pa$kuggfri$, $kuggfri$Vilken inverkan har kolhalten på stålets egenskaper?$kuggfri$, $kuggfri$Kolet bildar cementit ($\text{Fe}_3\text{C}$), en mycket hård fas. Vid långsam kylning ger 0 % C bara ferrit, under 0,8 % C ferrit och perlit, 0,8 % C bara perlit och över 0,8 % C perlit och cementit. Mer kol ger alltså mindre ferrit och mer cementit, och stålet blir hårdare och starkare men mindre duktilt. I härdade stål ger mer kol fler karbider, med samma effekt.

Stål med högre kolhalt (maskinstål, 0,25 till 0,75 % C) kan härdas men är svårare att svetsa än konstruktionsstål (under 0,25 % C).$kuggfri$, null, 188, false, $kuggfri$c59cbdf75$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Fö 12 Stål, s. 17; Canvas, Fö 12 Stål, s. 18; Canvas, Fö 12 Stål, s. 25; Canvas, Fö 12 Stål, s. 26; Canvas, Övning 7 m lösningar, s. 5$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('78f5947a-cb47-5cfd-9277-dbff23e2f513', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$vad-ar-martensit-och-hur-uppstar-det$kuggfri$, $kuggfri$Vad är martensit och hur uppstår det?$kuggfri$, $kuggfri$Kan fås vid snabbkylning av stål från austenitområdet. Det är utöver det en metastabil fas med tetragonal struktur = distorderad BCC.$kuggfri$, null, 189, true, $kuggfri$c9fcd032e$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('dbff3869-409d-5fe7-bf89-3617ef5b2173', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$vad-ar-ett-ttt-diagram-och-vad-anvands$kuggfri$, $kuggfri$Vad är ett TTT-diagram och vad används det till?$kuggfri$, $kuggfri$TTT-diagram står för Time Temperature Transformation- diagram och används för att bestämma tid och temperatur för värmebehandlingar.$kuggfri$, null, 190, false, $kuggfri$ca9efcb57$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('f8e9dc00-4834-5ba7-9185-3b93ea3001f1', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$varfor-legerar-man-stal-namn-minst-tva$kuggfri$, $kuggfri$Varför legerar man stål? Nämn minst två anledningar.$kuggfri$, $kuggfri$Stål legeras för att:

* lösningshärda ferriten
* öka härdbarheten: stora legeringsatomer fördröjer bildningen av perlit, så det finns mer tid att bilda martensit
* ge andra karbider än cementit, med stabilare högtemperaturegenskaper (t.ex. i verktygsstål)
* ge korrosionsmotstånd: med krom bildas ett skyddande kromoxidskikt (rostfritt stål)
* stabilisera austenit vid rumstemperatur (nickel i austenitiska rostfria stål)$kuggfri$, null, 191, false, $kuggfri$c7b239c9a$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Fö 12 Stål, s. 24; Canvas, Fö 12 Stål, s. 27; Canvas, Fö 12 Stål, s. 28; Canvas, Övning 7 m lösningar, s. 5$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('63539781-4cc7-5fa0-b1cc-2f71d7545490', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$vad-kannetecknar-underkategorin$kuggfri$, $kuggfri$Vad kännetecknar underkategorin: "Konstruktionsstål"?$kuggfri$, $kuggfri$* Kolhalt: < 0.25%

Konstruktionsstål kan delas in i två grupper; Kolstål och HSLA (High Strength Low Alloy)-steels, där låg kolhalt definieras som < 0.25%. Båda är svetsbara men kan ej härdas. Kolstål är billigt och används i exempelvis byggnader eller skepp. HSLA tillverkas mha en termomekanisk process som ger fin mikrostruktur och således hög sträckgräns. Används till exempel i fordonsplåtar och broar.$kuggfri$, null, 192, true, $kuggfri$c961c3901$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('97a3f631-75e9-5e4d-bda7-23035aa7f102', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$vad-kannetecknar-underkategorin-2$kuggfri$, $kuggfri$Vad kännetecknar underkategorin: "Maskinstål"?$kuggfri$, $kuggfri$* Kolhalt: 0.25-0.75 %

Maskinstål kan härdas och är legerat för att öka härdbarheten. Dock är det svårare att svetsa än exempelvis konstruktionsstål. Exempel på användningsområden är järnvägsräls, handverktyg, maskindelar etc.$kuggfri$, null, 193, true, $kuggfri$c8caf953a$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('1021c448-1f6f-58eb-8cfc-b6b301f1aa6b', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$vad-kannetecknar-underkategorin-3$kuggfri$, $kuggfri$Vad kännetecknar underkategorin: "Verktygsstål"?$kuggfri$, $kuggfri$* Kolhalt: 0.5-1.7 % C

Verktygsstål är legerat för att erhålla stabila karbider vid hög temperatur. Används i exempelvis gjutformar, pressverktyg, skärverktyg och kullager.$kuggfri$, null, 194, true, $kuggfri$c858b75c6$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('787e3a63-a165-5f3f-85c8-ac86e07302bf', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$vad-kannetecknar-underkategorin-4$kuggfri$, $kuggfri$Vad kännetecknar underkategorin: "Rostfritt stål"?$kuggfri$, $kuggfri$Legeras med Cr för att få ett kromoxidskikt på ytan → korrosionsskydd

* Ni, stabiliserar austenit vid rumstemperatur
* Tre typer: ferritiska (billiga), austenitiska (bäst korrosionsmotstånd, lågtemperaturegenskaper), martensitiska (kan härdas)$kuggfri$, null, 195, true, $kuggfri$cabac7777$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('87e465c8-9701-5028-b0ea-a8a44b73122a', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$vad-innebar-kalldeformation$kuggfri$, $kuggfri$Vad innebär kalldeformation?$kuggfri$, $kuggfri$Kallbearbetning, även känt som deformationshärdning eller kalldeformation, är en process som stärker metall genom plastisk deformation som exempelvis kallvalsning och tråddragning.

Mycket högre dislokationsdensitet efter
kallbearbetning → högre sträckgräns
(deformationshärdning)$kuggfri$, null, 196, true, $kuggfri$c51c48b13$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('ce391e59-9f19-59e1-b08f-c877fba14f51', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$vad-innebar-rekristallation$kuggfri$, $kuggfri$Vad innebär rekristallisation?$kuggfri$, $kuggfri$Rekristallisation är en process inom metallbearbetning där en deformerad metall omstrukturerar sin inre kristallstruktur för att minska spänningar och återställa dess ursprungliga egenskaper. När metallen deformeras plastiskt, till exempel genom valsning eller smidning, blir dess kristallstruktur och dislokationer störda, vilket leder till hårdare och sprödare egenskaper (detta kallas kallbearbetning).
Rekristallisation sker när en deformerad metall värms upp till en specifik temperatur, kallad rekristallisationstemperaturen. Vid denna temperatur börjar nya, icke-deformerade korn att bildas inuti materialet. Dessa nya korn ersätter de gamla, deformerade kornen och bidrar till att:

* Sänka metallens hårdhet och öka dess duktilitet – metallen blir mjukare och mer formbar.
* Minska inre spänningar – som byggts upp under deformationen.
* Förbättra materialets struktur – den får en jämnare och mer homogen kornstruktur.$kuggfri$, null, 197, true, $kuggfri$ca199d4d4$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('4318305f-f0ff-5d20-a30b-5400f1b1e1a3', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$vad-innebar-varmdeformation$kuggfri$, $kuggfri$Vad innebär varmdeformation?$kuggfri$, $kuggfri$Varmdeformation är en process där metaller deformeras vid temperaturer som är högre än deras rekristallisationstemperatur (ofta över cirka 0,5 gånger smälttemperaturen i kelvin). Vid dessa temperaturer kan metallens kristallstruktur rekonstrueras samtidigt som deformationen sker, vilket gör att nya korn kan bildas kontinuerligt under bearbetningen. Detta innebär att materialet inte härdas, och det behåller sin duktilitet och formbarhet. Varmdeformation används ofta för stora formändringar, exempelvis vid smidning och valsning i höga temperaturer.

Kortfattat:

* Ger deformation utan att höja sträckgränsen
* Stora deformationer är möjliga$kuggfri$, null, 198, true, $kuggfri$cdb45bca1$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('04a05efb-e55c-5270-8122-0b1ac989b140', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$beskriv-kortfattat-vad-skillnaden$kuggfri$, $kuggfri$Beskriv kortfattat vad skillnaden mellan kall- och varmdeformation är.$kuggfri$, $kuggfri$Skillnader kortfattat:

* Varmdeformation: Hög temperatur, inga spänningar byggs upp, materialet behåller sin formbarhet och stora dimensionsändringar kan ske under en och samma behandling.
* Kalldeformation: Låg temperatur, spänningar och hårdhet ökar, materialet blir starkare men samtidigt sprödare.$kuggfri$, null, 199, true, $kuggfri$c37607a46$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('16fb1c72-7d7a-5f85-8134-7aac280e17f9', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$ge-exempel-pa-minst-tva-plastiska$kuggfri$, $kuggfri$Ge exempel på minst två plastiska formningsmetoder.$kuggfri$, $kuggfri$Exempel:

* Smide
* Valsning
* Pressning
* Tråddragning$kuggfri$, null, 200, true, $kuggfri$c00a9f430$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('6f43d038-81cf-5128-a84d-8b8555e8f8e7', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$redogor-for-vad-gjutning-innebar-for$kuggfri$, $kuggfri$Redogör för vad gjutning innebär för materialet och ge exempel på minst två gjutningsmetoder.$kuggfri$, $kuggfri$* Gjutstruktur – Olika struktur i
olika delar av gjutgodset
* Defekter – porer, sprickor
* Ofta något sämre mekaniska
egenskaper än valsade eller
smidda material

Exempel:

* Formgjutning
(högt och lågt tryck)
* Sandgjutning
* Lost wax- casting$kuggfri$, null, 201, true, $kuggfri$c42fcaab7$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('2cd30d20-0100-53dd-bc85-68219f3627eb', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$redogor-for-vad-svetsning-innebar-for$kuggfri$, $kuggfri$Redogör för vad svetsning innebär för materialet och ge exempel på minst två svetsmetoder.$kuggfri$, $kuggfri$* Svets där materialet har smält och
stelnat – gjutstruktur
* Värmepåverkad zon (HAZ) –
förändrad mikrostruktur,
korntillväxt, förändrad härdning
* Ofta sprickor

Ex: TIG/MIG/MAG$kuggfri$, null, 202, true, $kuggfri$c16f68117$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('d83e65a5-c7e8-5056-af99-d6be43aa4222', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$beskriv-stalets-tillverkningsprocess-i$kuggfri$, $kuggfri$Beskriv stålets tillverkningsprocess i grova mått.$kuggfri$, $kuggfri$* Utgångsmaterial: järnoxid
* Reduceras i masugn:
järnoxid + kol + energi → tackjärn + koloxid
* Kolhalten i tackjärnet justeras till rätt kolhalt, stålet legeras, skrot kan tillsättas
* Processen kräver energi
  - processenergi
  - energi till reducering (är konstant)
* Återvinning sparar energi och råvaror, ger mindre utsläpp av koldioxid

Därefter behandlas stålet:

* Färskning = kolhalten justeras
* Legering
* Kontinuerlig gjutning
* Varmvalsning
* Kallbearbetning
* Kallvalsning, tråddragning, m.m. → plåt, räls, balkar, stång, tråd$kuggfri$, null, 203, true, $kuggfri$c3000bb92$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('29143e99-410b-5029-a80c-b4b741b849c0', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$ge-minst-tva-exempel-pa$kuggfri$, $kuggfri$Ge minst två exempel på värmebehandlingar för stål.$kuggfri$, $kuggfri$* Normalisering: austenitisering + långsam kylning → primär ferrit eller cementit + perlit. Andel perlit ges av kolhalten. Ger ”normal” mikrostruktur, lämpligt för konstruktioner där styvheten är viktig.
* Mjukglödgning: värmning till temperatur under austenittemperatur (723 C) → diffusion och korntillväxt, sfäroidiserad perlit, lägre sträckgräns. Används för
stål som skall maskinbearbetas och därefter härdas.
* Martensithärdning:
1. Värmning till austenitområdet
2. Snabbkylning → martensit
3. Anlöpning → anlöpt martensit = ferrit med mycket små cementitpartiklar
Kolhalten avgör andelen cementit. Temperatur och tid för anlöpningen avgör storleken på cementitpartiklarna. Används när hårdhet och sträckgräns är viktigt.$kuggfri$, null, 204, true, $kuggfri$ca57d373a$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('d48867d7-f794-5d1c-8520-b18ff8a7f054', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$namn-minst-tva-produktionsmassiga$kuggfri$, $kuggfri$Nämn minst två produktionsmässiga anledningar till att man legerar stål.$kuggfri$, $kuggfri$Stål legeras bland annat för att:

* Öka hållfastheten – Genom att tillsätta legeringsämnen som nickel eller krom kan stålets styrka och hållfasthet förbättras.

* Förbättra korrosionsbeständigheten – Krom och nickel ökar stålets motståndskraft mot rost och korrosion, vilket är särskilt viktigt för rostfria stål.

* Förbättra hårdheten och slitstyrkan – Tillsatser som kol, mangan och vanadin gör stålet hårdare och mer motståndskraftigt mot slitage, vilket är fördelaktigt i verktygsstål.

* Höja duktiliteten och segheten – Vissa legeringsämnen, som nickel, kan öka segheten och duktiliteten, vilket gör stålet mindre sprött vid låga temperaturer.

* Förbättra värmebeständigheten – Legeringar med ämnen som molybden och volfram hjälper stålet att behålla sina egenskaper vid höga temperaturer, vilket är viktigt för verktygsstål och höglegerat stål.

* Förbättra härdbarheten – Legeringar med ämnen som krom och molybden ökar stålets förmåga att härdas djupt, vilket gör att materialet får en jämn hårdhet vid härdning.$kuggfri$, null, 205, false, $kuggfri$cfdf4c241$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('a07dfcae-611f-59ba-a558-0bb5070999d1', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$ttt-diagram$kuggfri$, $kuggfri$TTT-diagram$kuggfri$, $kuggfri$TTT-diagram (time, temperature, transformation) visar hur lång tid det tar för instabil austenit att omvandlas, t.ex. till perlit, vid olika temperaturer. Ur diagrammet kan man därför avläsa hur snabbt man måste kyla från austenitområdet för att undvika perlit och i stället bilda martensit. Diagrammet är olika för olika stål och används för att bestämma tid och temperatur för värmebehandlingar.$kuggfri$, null, 206, false, $kuggfri$c586cfb2f$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Fö 12 Stål, s. 20; Canvas, Fö 5 Fasdiagram och mikrostruktur 2, s. 21$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('46a9fe24-7e1b-5258-b01f-6e1daf283cc8', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$mjukglodgning$kuggfri$, $kuggfri$Mjukglödgning$kuggfri$, $kuggfri$En värmebehandling av stål där man får sfäroidiserad perlit, vilket ger ett material med lägre sträckgräns men som är lättare att maskinarbeta. Stålet värms upp till en temperatur under austenitiseringstemperaturen, och
diffusion ger sfäroidiserad cementit.$kuggfri$, null, 207, true, $kuggfri$ca83d25c6$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('585b72a0-f107-5a46-9859-412f31526333', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$verktygsstal$kuggfri$, $kuggfri$Verktygsstål$kuggfri$, $kuggfri$Höglegerat stål med hög kolhalt. Används i härdat tillstånd. Hårt och värmetåligt.$kuggfri$, null, 208, true, $kuggfri$cf5e4fef2$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('843de66d-7d6a-5be1-91b9-d310fa20cd83', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$ja-nej-nar-ett-material-varmvalsas-sa$kuggfri$, $kuggfri$När ett material varmvalsas ökar sträckgränsen.$kuggfri$, $kuggfri$Falskt. Varmbearbetning sker över rekristallisationstemperaturen, så plastisk deformation och rekristallisation sker samtidigt. Deformationen höjer därför inte sträckgränsen, och stora deformationer är möjliga. Det är vid kallbearbetning som dislokationsdensiteten och därmed sträckgränsen ökar (deformationshärdning).$kuggfri$, null, 209, false, $kuggfri$c7576a4b1$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Tentamen Materialteknik med svar 2020-10-24, s. 2; Canvas, Fö 12 Stål, s. 4; Canvas, Fö 12 Stål, s. 5; Canvas, Fö 12 Stål, s. 6$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('d0618afe-bca0-547e-af97-57e89cc816bb', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$ja-nej-i-stal-bildar-kol-cementit-men-i$kuggfri$, $kuggfri$I grått gjutjärn och segjärn förekommer allt kol som ren grafit.$kuggfri$, $kuggfri$Falskt. Gjutjärn har 2 till 4 % C, och i de vanliga typerna gråjärn och segjärn består mikrostrukturen av perlit och grafit. Perlit är ferrit och cementit ($\text{Fe}_3\text{C}$), så en del av kolet är bundet som cementit. Grafiten är fjällformad i gråjärn och sfärisk i segjärn. I stål bildar kolet cementit.

Tentan 2020 hade påståendet "I stål bildar kol cementit, men i gjutjärn förekommer kolet som ren grafit" med facit ja. Det är en förenkling, därför är påståendet omformulerat.$kuggfri$, null, 210, false, $kuggfri$c15906d76$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Tentamen Materialteknik med svar 2020-10-24, s. 2; Canvas, Fö 12 Stål, s. 17; Canvas, Fö 12 Stål, s. 29; Canvas, Lab_PM_M2_v2026, s. 12; Canvas, Övning 7 m lösningar, s. 5$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('8b407853-d672-5c01-80cc-efba89c5a5fa', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$quiz-ttt-diagram-tva-ratt$kuggfri$, $kuggfri$TTT-diagram: vilka påståenden är sanna?$kuggfri$, $kuggfri$TTT står för time, temperature, transformation. Diagrammet visar tiden för omvandling av instabil austenit till perlit vid olika temperaturer, och därmed vilken avsvalningshastighet som krävs för att i stället bilda martensit. Martensit bildas bara från austenit, genom snabbkylning; perlit omvandlas inte till martensit.$kuggfri$, null, 211, false, $kuggfri$c5ac8c387$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Ur TTT-diagrammet kan man läsa hur lång tid det tar för instabil austenit att omvandlas till perlit.","correct":true},{"text":"TTT står för tryck, temperatur, transition.","correct":false},{"text":"Med ett TTT-diagram kan man bestämma hur snabbt man måste kyla för att bilda martensit.","correct":true},{"text":"Ur TTT-diagrammet kan man läsa hur lång tid det tar för perlit att omvandlas till martensit.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 2, fråga 9; Canvas, Fö 12 Stål, s. 20; Canvas, Fö 5 Fasdiagram och mikrostruktur 2, s. 21; Canvas, Lab_PM_M2_v2026, s. 13$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('b6fe36bb-75e6-5ce4-8b3b-5d40d972b9ad', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$quiz-ttt-diagram-for-stal-2-ratt$kuggfri$, $kuggfri$TTT-diagram för stål: vilka påståenden är sanna?$kuggfri$, $kuggfri$TTT-diagrammet visar omvandlingstiden för instabil austenit och därmed den kylhastighet som krävs för martensit, dvs. fasomvandlingarnas kinetik. Hävstångsregeln används i fasdiagram, som visar de stabila faserna vid jämvikt. Martensit kan bara bildas ur austenit, så perlit som redan har bildats blir inte martensit vid snabbkylning.$kuggfri$, null, 212, false, $kuggfri$cb21761b5$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Ett TTT-diagram för stål visar tiden för instabil austenit att omvandlas till perlit.","correct":true},{"text":"Med hävstångsregeln kan andelen av strukturbeståndsdelarna beräknas ur TTT-diagrammet.","correct":false},{"text":"Ett TTT-diagram visar hur snabbt man måste kyla från austenitområdet för att bilda martensit.","correct":true},{"text":"Genom att först bilda perlit och sedan snabbkyla och bilda martensit undviks sprickbildning.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 4, fråga 8; Canvas, Fö 5 Fasdiagram och mikrostruktur 2, s. 21; Canvas, Fö 12 Stål, s. 2; Canvas, GLU 02 Fasdiagram, s. 8; Canvas, Lab_PM_M2_v2026, s. 13$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('c129d9e0-b3ec-5d1f-9865-71b180444c3b', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$quiz-kall-och-varmbearbetning-2-ratt$kuggfri$, $kuggfri$Kall- och varmbearbetning: vilka påståenden är sanna?$kuggfri$, $kuggfri$Kallbearbetning ger mycket högre dislokationsdensitet, vilket höjer sträckgränsen (deformationshärdning) och minskar brottförlängningen; det beror inte på att atomerna trycks samman. Även rena metaller deformationshärdas, t.ex. ren aluminium och ren koppar. När ett kallbearbetat material värms upp rekristalliserar det: nya små korn med få dislokationer bildas, sträckgränsen sjunker och brottförlängningen ökar.

I quizen stod "brottgränsen" och "dislokationsfria korn"; föreläsningen talar om sträckgräns och om korn med få dislokationer.$kuggfri$, null, 213, false, $kuggfri$cb30bbbcb$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Rekristallisation innebär att nya korn med få dislokationer bildas när ett kallbearbetat material värms upp.","correct":true},{"text":"Vid kallvalsning ökar sträckgränsen och brottförlängningen minskar.","correct":true},{"text":"Vid kallvalsning trycks atomerna samman och materialet blir tätare.","correct":false},{"text":"För att en metall ska bli hårdare vid kallbearbetning måste den vara legerad.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 4, fråga 10; Canvas, Fö 12 Stål, s. 4; Canvas, Fö 12 Stål, s. 5; Canvas, Kapitel_06 Plasticitet och Duktilitet, s. 36; Canvas, Kapitel_06 Plasticitet och Duktilitet, s. 43$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('18756b90-2600-525f-b979-fcfbccdd1334', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$stal-normalisering$kuggfri$, $kuggfri$Normalisering$kuggfri$, $kuggfri$Värmebehandling av stål: austenitisering följd av långsam kylning i luft. Man får jämviktsstrukturen, primär ferrit eller cementit plus perlit, där andelen perlit ges av kolhalten. Normalisering ger en "normal" mikrostruktur, lämplig för konstruktioner där styvheten är viktig.$kuggfri$, null, 214, false, $kuggfri$cbfdb57e8$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Short_dictionary_ v2026, s. 10; Canvas, Fö 12 Stål, s. 15; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 15; Canvas, Tentamen med svarsförslag MTT085 251030, uppgift 1h$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('9e9d8319-bf10-515b-bed5-9bfb653cbbae', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$stal-hardbarhet-legering$kuggfri$, $kuggfri$Varför ökar legeringsämnen stålets härdbarhet?$kuggfri$, $kuggfri$Martensit bildas när stål kyls så snabbt från austenitområdet att kolet inte hinner diffundera och bilda perlit. Stora legeringsatomer fördröjer perlitbildningen, så det finns mer tid att bilda martensit; därför är t.ex. maskinstål legerade för att öka härdbarheten. TTT-diagrammet, som visar tiden för omvandling till perlit, är olika för olika stål. Härdning ändrar inte E-modulen, och snabbare koldiffusion skulle tvärtom underlätta perlitbildningen.$kuggfri$, null, 215, false, $kuggfri$cb1eef7e1$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Stora legeringsatomer fördröjer bildningen av perlit, så det finns mer tid att bilda martensit vid kylningen","correct":true},{"text":"Legeringsatomerna bildar martensit redan vid stelningen","correct":false},{"text":"Legeringsatomerna höjer E-modulen så att stålet blir hårdare","correct":false},{"text":"Legeringsatomerna gör att kolet diffunderar snabbare","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Fö 12 Stål, s. 24; Canvas, Fö 12 Stål, s. 26; Canvas, Fö 5 Fasdiagram och mikrostruktur 2, s. 20; Canvas, Fö 5 Fasdiagram och mikrostruktur 2, s. 21; Canvas, Tentamen Materialteknik med svar 2020-10-24, s. 2$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('b57a3a08-5d1c-5579-9b2c-3002b7a1b4e3', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '86266117-7fc7-5ca1-b416-41853cb7dbce', $kuggfri$stal-gjutjarn-gra-och-seg$kuggfri$, $kuggfri$Vad stämmer för gråjärn och segjärn?$kuggfri$, $kuggfri$Gjutjärn har 2 till 4 % C. I de vanliga typerna gråjärn och segjärn består mikrostrukturen av perlit och grafit. I gråjärn är grafiten fjällformad, vilket ger lägre E-modul (ungefär hälften av ståls), ett relativt sprött material och god vibrationsdämpning. I segjärn är grafiten sfärisk, vilket ger högre seghet. Gjutjärn används t.ex. till maskindelar och maskinstativ.$kuggfri$, null, 216, false, $kuggfri$c3805c571$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Mikrostrukturen består av perlit och grafit","correct":true},{"text":"Gråjärn har fjällformad grafit, vilket ger lägre E-modul (ungefär hälften av ståls) och ett relativt sprött men vibrationsdämpande material","correct":true},{"text":"Segjärn har fjällformad grafit och är därför sprödare än gråjärn","correct":false},{"text":"Gjutjärn har lägre kolhalt än stål","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Fö 12 Stål, s. 29; Canvas, Övning 7 m lösningar, s. 5$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('3b75db4a-1061-5ff9-8d7b-e716bf614bf0', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '8ce9dd0a-ffc6-5dba-9cc9-a562ccc19e65', $kuggfri$vad-kannetecknar-aluminium$kuggfri$, $kuggfri$Vad kännetecknar Aluminium?$kuggfri$, $kuggfri$* Lägre vikt än stål, densiteten är 2,7 kg/dm3
* FCC struktur → god plastisk formbarhet
* God maskinbarhet
* God elektrisk- och värmeledning
* Korrosionsskydd: Al reagerar med O₂ och bildar ett
skyddande oxidskikt på ytan$kuggfri$, null, 217, true, $kuggfri$c63c7cc6a$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('ef2b31d6-ec9b-515d-b7fb-bc7a3776a9dc', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '8ce9dd0a-ffc6-5dba-9cc9-a562ccc19e65', $kuggfri$vad-kannetecknar-magnesium$kuggfri$, $kuggfri$Vad kännetecknar Magnesium?$kuggfri$, $kuggfri$* Låg densitet 1,8 kg/dm3
* HCP struktur → begränsad plastisk formbarhet
* God maskinbarhet
* God gjutbarhet, större delen används som gjutgods
* Bildar poröst oxidskikt, sämre korrosionsskydd
* Brännbart – men bara som pulver eller tunn plåt
* Energikrävande produktion$kuggfri$, null, 218, true, $kuggfri$c20735d95$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('9b03ecd8-4974-5c17-942b-5a4cef3f2271', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '8ce9dd0a-ffc6-5dba-9cc9-a562ccc19e65', $kuggfri$vad-kannetecknar-titan$kuggfri$, $kuggfri$Vad kännetecknar Titan?$kuggfri$, $kuggfri$* Medel densitet 4,1 kg/dm3
* Utmärkt hållfasthet
* Utmärkt korrosionsskydd
* Dyrt på grund av tillverkningsprocessen
* Används i ren form eller legerat
* Biokompatibelt (inte negativt för kroppen), används t.ex. i implantat$kuggfri$, null, 219, false, $kuggfri$cb8f39e2b$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: "Titan är den enda metallen som är biokompatibel" är en överdrift; tentasvaren anger bara att titan är biokompatibelt; Canvas, Fö 13 Aluminium och andra metaller, s. 13; Canvas, Fö 13 Aluminium och andra metaller, s. 14; Canvas, Svar Materialteknik 2019-10-26, s. 2; Canvas, Tentamen Materialteknik mrd svar 2021-10-23 (korrigerad), uppgift 5$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('8ebec9f1-1a10-5584-8632-c04eaa66a0cc', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '8ce9dd0a-ffc6-5dba-9cc9-a562ccc19e65', $kuggfri$vad-kannetecknar-koppar-och-dess$kuggfri$, $kuggfri$Vad kännetecknar Koppar och dess legeringar?$kuggfri$, $kuggfri$* Hög densitet 8,9 kg/dm3
* Koppar: Utmärkt formbarhet, hög elektrisk och termisk
ledningsförmåga, pris=50 SEK/kg
* Mässing: legerat med 5-40 % Zn, bra form- och maskinbarhet.
* Brons: legerat med 5-25 % Sn, bra hållfasthet men lite
duktilitet, gjuts ofta
* Lagerbrons har bra tribologiska egenskaper$kuggfri$, null, 220, true, $kuggfri$c49d1abff$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('5ce3fa31-862d-55e9-a2ff-d4e5d50e41de', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '8ce9dd0a-ffc6-5dba-9cc9-a562ccc19e65', $kuggfri$vad-kannetecknar-nickel-och-sa-kallade$kuggfri$, $kuggfri$Vad kännetecknar Nickel- och så kallade superlegeringar?$kuggfri$, $kuggfri$* Medel densitet 7,9-8,7 kg/dm3
* E-modul: 200-220 GPa
* Sträckgräns: 272-900 MPa
* Brottseghet: 127-251 $\text{MPa}\sqrt{\text{m}}$
* Användningstemperatur: -273-1040 °C
* Carbon footprint: 13 kg/kg
* Pris: 150 SEK/kg (för superlegeringar)
* Exceptionella högtemperatur- egenskaper med god
oxidations och korrosionsegenskaper
* Legeras med Cr, Co, Al, Ti Mo,
Zr, Fe, Hf$kuggfri$, null, 221, true, $kuggfri$c1e905552$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('ba1b61a0-ef02-5e39-9723-449237f645f9', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '8ce9dd0a-ffc6-5dba-9cc9-a562ccc19e65', $kuggfri$varfor-anvander-man-inte-alltid-stal$kuggfri$, $kuggfri$Varför använder man inte alltid stål eftersom det är billigast?$kuggfri$, $kuggfri$Stål har bra mekaniska egenskaper, låg miljöbelastning per kilo och återfinns i många olika varianter för olika användningsområden till det billigaste priset, men aluminium har lägre densitet, fortfarande bra pris, är lättbearbetat och har bra naturligt korrosionsskydd.

Stål är bra, men i vissa situationer väljs andra material för att deras speciella egenskaper gör de särskilt fördelaktiga.$kuggfri$, null, 222, true, $kuggfri$cb19f9e5f$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('35410586-b689-51cf-b5f3-b1f791bf2152', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '8ce9dd0a-ffc6-5dba-9cc9-a562ccc19e65', $kuggfri$aldring$kuggfri$, $kuggfri$Åldring$kuggfri$, $kuggfri$Sista steget i utskiljningshärdning, t.ex. av värmebehandlingsbara aluminiumlegeringar:

1. Upplösningsbehandling: legeringsämnet löses så att legeringen blir en enda fas ($\alpha$).
2. Snabbkylning: en metastabil, övermättad $\alpha$-fas bildas.
3. Åldring: vid förhöjd temperatur (artificiell åldring) eller rumstemperatur (naturlig åldring) ger diffusion små, jämnt fördelade utskiljningar, som höjer sträckgränsen.

Utskiljningarnas storlek beror på tid och temperatur, vilket ger underåldrat, toppåldrat (högst sträckgräns) och överåldrat tillstånd.$kuggfri$, null, 223, false, $kuggfri$ccf1a0367$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 26; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 27; Canvas, GLU 02 Fasdiagram, s. 1; Canvas, Fö 5 Fasdiagram och mikrostruktur 2, s. 18; Canvas, Fö 5 Fasdiagram och mikrostruktur 2, s. 19; Canvas, Short_dictionary_ v2026, s. 1; Canvas, Short_dictionary_ v2026, s. 10$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('22b91be4-1d32-5d02-b3ec-d2f57e5208a0', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '8ce9dd0a-ffc6-5dba-9cc9-a562ccc19e65', $kuggfri$superlegering$kuggfri$, $kuggfri$Superlegering$kuggfri$, $kuggfri$Vanligtvis legeringar med Ni-bas som har excellenta högtemperaturegenskaper, oxidations- och korrosionsmotstånd.$kuggfri$, null, 224, true, $kuggfri$c1fc01a34$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('d88c4686-0310-5539-a950-4eae049c8012', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '8ce9dd0a-ffc6-5dba-9cc9-a562ccc19e65', $kuggfri$quiz-magnesium-2-ratt$kuggfri$, $kuggfri$Vad stämmer för magnesium?$kuggfri$, $kuggfri$Magnesium har HCP-struktur med få glidsystem, vilket ger begränsad plastisk formbarhet. Det har god gjutbarhet och god maskinbarhet, och ungefär 75 % används som gjutgods. Magnesium är relativt sprött: Mg-legeringarnas brottseghet är 12 till 18 $\text{MPa}\sqrt{\text{m}}$, lägre än aluminiumlegeringarnas (19 till 41 $\text{MPa}\sqrt{\text{m}}$).$kuggfri$, null, 225, false, $kuggfri$ca469bbe7$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Det har många glidsystem för dislokationsrörelse och får därmed låg sträckgräns.","correct":false},{"text":"Det lämpar sig bäst för gjutning.","correct":true},{"text":"Det är svårt att maskinbearbeta.","correct":false},{"text":"En av de största nackdelarna är låg brottseghet.","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 4, fråga 4; Canvas, Fö 13 Aluminium och andra metaller, s. 11; Canvas, Fö 13 Aluminium och andra metaller, s. 12; Canvas, Fö 13 Aluminium och andra metaller, s. 7; Canvas, Fö 13 Aluminium och andra metaller, s. 8; Canvas, Fö 12 Stål, s. 2; Canvas, Svar Materialteknik 2019-10-26, s. 2$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('cbcdfa6c-9253-58fa-b9d5-9f9e374c360f', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '8ce9dd0a-ffc6-5dba-9cc9-a562ccc19e65', $kuggfri$quiz-aluminium-2-ratt$kuggfri$, $kuggfri$Vad stämmer för aluminium?$kuggfri$, $kuggfri$Aluminium reagerar med syre och bildar ett skyddande oxidskikt på ytan. Tillverkning av aluminium kräver betydligt mer energi per kilo än stål (i föreläsningens exempel med dryckesburkar 200 mot 23 per kg), men omsmältning vid återvinning kräver mycket mindre energi. Al-Cu-legeringar kan utskiljningshärdas. Aluminium har FCC-struktur och god plastisk formbarhet; det är magnesium som har HCP-struktur.

Quizens fjärde alternativ var ett påhittat legeringsnamn och har ersatts, och "korroderar inte" har preciserats.$kuggfri$, null, 226, false, $kuggfri$c9e4dabfd$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Det skyddas mot korrosion av ett oxidskikt (Al₂O₃) som bildas på ytan.","correct":true},{"text":"Det kräver mindre energi per kilo att tillverka än stål.","correct":false},{"text":"Det kan utskiljningshärdas om det legeras med koppar.","correct":true},{"text":"Det har HCP-struktur och därför begränsad plastisk formbarhet.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 4, fråga 6; Canvas, Fö 13 Aluminium och andra metaller, s. 3; Canvas, Kapitel_03 Materialval, s. 45; Canvas, Tentamen Materialteknik med svar 2020-10-24, s. 4; Canvas, Svarsförslag Tentamen MTT085 25-01, s. 6$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('ffcf72fb-b29c-5da1-8008-8fbcf7be1673', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '8ce9dd0a-ffc6-5dba-9cc9-a562ccc19e65', $kuggfri$quiz-indelning-och-legering-av-aluminium-2$kuggfri$, $kuggfri$Indelning och legering av aluminium: vilka påståenden är sanna?$kuggfri$, $kuggfri$Vid snabbkylning av en värmebehandlingsbar aluminiumlegering bildas en metastabil $\alpha$-fas; martensit bildas i stål. Lösnings- och utskiljningshärdning kräver legering, så ren aluminium härdas genom deformationshärdning (t.ex. hushållsfolie; valsad ren Al har högre sträckgräns än glödgad). Gjutlegeringar legeras med Si för att få ett eutektikum, som ger hållfasthet och slitstyrka och är lätt att gjuta. Aluminium har god maskinbarhet.

Quizens formulering "Enda sättet att höja sträckgränsen på ren aluminium är att deformationshärda" är uppmjukad, eftersom även en finkornigare struktur ger ett starkare material.$kuggfri$, null, 227, false, $kuggfri$c8f580b22$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"När man snabbkyler aluminium kan metastabil martensit bildas.","correct":false},{"text":"Ren aluminium härdas i praktiken genom deformationshärdning, t.ex. valsning.","correct":true},{"text":"Gjutlegeringar legeras med Si för att öka användningstemperaturen.","correct":false},{"text":"En fördel med aluminium är att det är lätt att maskinbearbeta.","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 4, fråga 7; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 5; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 12; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 26; Canvas, Kapitel_06 Plasticitet och Duktilitet, s. 31; Canvas, Kapitel_06 Plasticitet och Duktilitet, s. 43; Canvas, Kapitel_06 Plasticitet och Duktilitet, s. 45; Canvas, Fö 13 Aluminium och andra metaller, s. 3; Canvas, Fö 13 Aluminium och andra metaller, s. 9$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('46148811-8ddd-5695-8be6-e634608cfb3b', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '8ce9dd0a-ffc6-5dba-9cc9-a562ccc19e65', $kuggfri$al-varmebehandlingsbara-legeringar$kuggfri$, $kuggfri$Vilka smideslegeringar av aluminium är värmebehandlingsbara, dvs. kan utskiljningshärdas?$kuggfri$, $kuggfri$Aluminiumlegeringar delas in i smideslegeringar och gjutlegeringar. Av smideslegeringarna är 2xxx, 6xxx och 7xxx värmebehandlingsbara: de utskiljningshärdas och får hög sträckgräns (t.ex. 2000- och 7000-serierna i flyg och rymd). Serierna 1000, 3000 och 5000 är inte värmebehandlingsbara, dvs. kan inte utskiljningshärdas, och härdas i stället genom lösnings- och deformationshärdning.$kuggfri$, null, 228, false, $kuggfri$ca68fb347$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Serierna 2xxx, 6xxx och 7xxx","correct":true},{"text":"Serierna 3xxx och 5xxx","correct":false},{"text":"1000-serien (folie, elektriska ledare)","correct":false},{"text":"Alla smideslegeringar, oavsett legeringsämne","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Fö 13 Aluminium och andra metaller, s. 4; Canvas, Fö 13 Aluminium och andra metaller, s. 7; Canvas, Fö 13 Aluminium och andra metaller, s. 8; Canvas, Övning 7 m lösningar, s. 5$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('516cee13-192c-57bc-8ac7-86fdc5234931', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '8ce9dd0a-ffc6-5dba-9cc9-a562ccc19e65', $kuggfri$al-stal-hardning-jamforelse$kuggfri$, $kuggfri$Beskriv likheter och skillnader mellan härdning av stål och utskiljningshärdning av aluminium.$kuggfri$, $kuggfri$**Likheter**

* Båda metallerna måste legeras för att kunna härdas: Fe med C, Al med t.ex. Cu.
* Metallen värms till ett enfasområde där legeringsämnet löses (austenitisering respektive upplösningsbehandling).
* Snabbkylning ger en metastabil fas (martensit respektive metastabil $\alpha$-fas).
* Uppvärmning till måttlig temperatur ger utskiljningar av en jämviktsfas; tiden vid temperaturen avgör utskiljningarnas storlek och därmed sträckgränsen.

**Skillnader**

* Sista steget heter anlöpning för stål och åldring för aluminium.
* Vid anlöpning minskar sträckgränsen kontinuerligt med tiden, medan den vid åldring först ökar, når ett maximum (toppåldrat) och sedan minskar (överåldrat).$kuggfri$, null, 229, false, $kuggfri$cf2a0d162$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Tentamen Materialteknik med svar 2020-10-24, s. 4; Canvas, Tentamen Materialteknik med svar 2020-10-24, s. 5; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 23; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 24; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 25; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 26; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 27$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('ba5df6c6-bba4-5e43-bfdb-9b6877750e68', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '8ce9dd0a-ffc6-5dba-9cc9-a562ccc19e65', $kuggfri$al-toppaldrat$kuggfri$, $kuggfri$Vid åldring av en värmebehandlingsbar aluminiumlegering: vilket tillstånd ger högst sträckgräns?$kuggfri$, $kuggfri$Toppåldrat material är så starkt som legeringen kan bli, med måttlig seghet (t.ex. båtmaster och slalomstavar). Underåldrat är segare men har lite lägre sträckgräns. Överåldrat är lite svagare och segare men tåligare mot hög temperatur, eftersom utskiljningarna har vuxit klart; det används t.ex. i motorblock. Det är åldringen, som ger små jämnt fördelade utskiljningar, som höjer sträckgränsen efter snabbkylningen.$kuggfri$, null, 230, false, $kuggfri$caaa806c1$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Underåldrat","correct":false},{"text":"Toppåldrat (peak aged, T6)","correct":true},{"text":"Överåldrat","correct":false},{"text":"Direkt efter snabbkylningen, före åldringen","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 26; Canvas, GLU_5-8 Mikrostruktur och intro till Fasdiagram, s. 27; Canvas, Fö 5 Fasdiagram och mikrostruktur 2, s. 19$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('acfeec12-ffff-579e-977d-1aa9cb574cd3', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2a0cb9e4-83a2-5694-93d8-c2458390173a', $kuggfri$vad-i-materialtillverkningsprocessen$kuggfri$, $kuggfri$Vad i materialtillverkningsprocessen kräver energi och vad innebär detta för miljön?$kuggfri$, $kuggfri$Energiintensiva processer:

* Energi för reducering av mineral till metall
* Övrig energi för tillverkning och formning, transport, användning. Kan minskas genom att återanvända värme.

Miljöbelastning:

* Ingrepp i naturen
* Utsläpp av CO₂
* Andra utsläpp och föroreningar
* CO₂ används som mått på miljöbelastning (carbon footprint)$kuggfri$, null, 231, true, $kuggfri$c2b807d63$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('a5f96185-f3ee-560e-9cff-60712edba982', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2a0cb9e4-83a2-5694-93d8-c2458390173a', $kuggfri$hur-ateranvandningsbara-ar-egentligen$kuggfri$, $kuggfri$Hur återanvändningsbara är egentligen metaller? Vad finns det för utmaningar med det?$kuggfri$, $kuggfri$* Metallskrot är en utmärkt råvara för metalltillverkning
* Kräver mindre energi än tillverkning från malm: 1/10 för Al och 1/3 för stål
* Ger mindre miljöbelastning
* Metall tillverkad från skrot har samma egenskaper som metall tillverkad från mineral

Utmaningar:

* Legeringshalten måste kontrolleras – problem med blandat skrot och metallföroreningar
* Koppar och tenn förstör stål
* Fe försprödar Al
* Bly, kadmium och kvicksilver är ofta oönskat i
legeringar
* Skrotet måste samlas in, transporteras, sorteras$kuggfri$, null, 232, true, $kuggfri$c3a714455$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('6ef88389-170e-583b-a2ae-e3dc3e9e2f82', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2a0cb9e4-83a2-5694-93d8-c2458390173a', $kuggfri$hur-bra-ar-aluminium-sett-ur-ett$kuggfri$, $kuggfri$Hur bra är aluminium sett ur ett hållbarhetsperspektiv?$kuggfri$, $kuggfri$Aluminium:

* Al hör till de grundämnen som finns i god tillgång
* Framställning av primäraluminium kräver mycket energi, betydligt mer per kilo än stål
* Omsmältning vid återvinning kräver mycket mindre energi, bland annat för att smälttemperaturen är lägre än ståls → lämpligt för produkter som kan återvinnas, mindre lämpligt för produkter som inte kan återvinnas

Problem vid återvinning av aluminium:

* Legeringshalten måste ligga inom toleranserna för legeringen, så skrot av olika legeringar måste sorteras och hållas åtskilt.$kuggfri$, null, 233, false, $kuggfri$ccf09d49e$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Rättelse: kortet sa att aluminium är det vanligaste grundämnet i jordskorpan, vilket inte stämmer och inte står i kursmaterialet; Canvas, Fö 13 Hållbarhet, s. 13; Canvas, Fö 13 Hållbarhet, s. 17; Canvas, Kapitel_03 Materialval, s. 45; Canvas, Tentamen Materialteknik med svar 2022-11-29, s. 5$kuggfri$, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('da15976c-ee6f-565e-9b8e-3c68a9d4267e', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2a0cb9e4-83a2-5694-93d8-c2458390173a', $kuggfri$hur-bra-ar-stal-respektive-rostfritt$kuggfri$, $kuggfri$Hur bra är stål respektive rostfritt stål sett ur ett hållbarhetsperspektiv?$kuggfri$, $kuggfri$Stål:

* God tillgång i jordskorpan
* Relativt låg miljöbelastning per kg
* Hög hållfasthet i förhållande till miljöbelastning
* Korroderar, kräver ofta ytbehandling
* Höghållfasta stål kan användas i lättkonstruktioner

Rostfritt stål:

* Legering med järn, Cr (ca 18 %), Ni (ca 8 %), ev Mo (2 %)
* Tillgången av legeringsämne i jordskorpan är förhållandevis liten
* Legeringsämnena kan vara ohälsosamma och allergena i fri form.
Oftast inte bundna i rostfritt stål.
* Bra korrosionsmotstånd och livslängd. Bör återvinnas.$kuggfri$, null, 234, true, $kuggfri$c47332ef9$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('5f8b0978-8f26-57e6-be83-caa802e2a03c', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2a0cb9e4-83a2-5694-93d8-c2458390173a', $kuggfri$vad-finns-det-for-problem-med$kuggfri$, $kuggfri$Vad finns det för problem med återvinningen av blandat skrot?$kuggfri$, $kuggfri$* Vid återanvändning av skrot är kontroll av legeringsämne ett problem
* Överflödiga legeringsämne och förorenande metaller kan vara eller är oekonomiska att ta bort
* Sorterat skrott är mer användbart och har högre värde$kuggfri$, null, 235, true, $kuggfri$cbd45b05d$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('8b76e766-64a5-5f1a-8d74-b664b0cff35d', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2a0cb9e4-83a2-5694-93d8-c2458390173a', $kuggfri$vad-ar-co-footprint-respektive-embodied$kuggfri$, $kuggfri$Vad är "CO₂- footprint" respektive "Embodied Energy"?$kuggfri$, $kuggfri$CO₂ footprint:

* Mängd CO₂ som bildas vid produktion av 1 kg material

För metaller:
- CO₂ bildas vid produktion av energi
- CO₂ bildas vid kemiska reaktioner vid reduktion av malm till metall

Embodied energy:

* Energin som krävs för att producera 1 kg av materialet

För metaller:
- Energi som krävs för reduktionsreaktionen
- Transport, värmning, processer$kuggfri$, null, 236, true, $kuggfri$c195f485e$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('76812786-40c0-56b4-aafa-370453362126', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2a0cb9e4-83a2-5694-93d8-c2458390173a', $kuggfri$hur-ser-tillgangen-pa-metaller-i$kuggfri$, $kuggfri$Hur ser tillgången på metaller i jordskorpan ut?$kuggfri$, $kuggfri$* De vanligaste metallerna finns i stor omfattning i jordskorpan: Fe, Al, Mg, Ti
* Vissa legeringsämnen finns i begränsad mängd i jordskorpan
* 69 element räknas som strategiska eller kritiska: sällsynta
jordartsmetaller, platina-gruppen, fissionsämne (U, Th, Pu), W, Ta, Nb, Ga, In$kuggfri$, null, 237, true, $kuggfri$c424d67c2$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('6373f8d9-c953-5059-a85d-59b636e61cda', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2a0cb9e4-83a2-5694-93d8-c2458390173a', $kuggfri$sammanfatta-lite-kort-hur-metaller$kuggfri$, $kuggfri$Sammanfatta lite kort hur metaller lämpar sig för återvinning.$kuggfri$, $kuggfri$* Metaller lämpar sig väl för återvinning
  - Sparar resurser och energi
  - Ger lika bra material
* Problem med föroreningar och legeringsämne
* CO₂ footprint och embodied energy ger viss
vägledning – kan användas i materialindex
* Bör titta på totala miljöbelastningen under
livscykeln$kuggfri$, null, 238, true, $kuggfri$c69c09f4b$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('6a417f80-0c34-5ad4-89f5-90a0c4e7963c', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2a0cb9e4-83a2-5694-93d8-c2458390173a', $kuggfri$co-foot-print$kuggfri$, $kuggfri$CO₂-foot print$kuggfri$, $kuggfri$Den mängd CO₂ som bildas vid produktion av ett kilo material.$kuggfri$, null, 239, false, $kuggfri$cf4c70247$kuggfri$, $kuggfri$begrepp$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('f6c41f1e-d664-5a78-bb12-3027eecc4bb3', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2a0cb9e4-83a2-5694-93d8-c2458390173a', $kuggfri$quiz-miljoegenskaper-vad-ar-sant-tva-ratta$kuggfri$, $kuggfri$Miljöegenskaper: vilka påståenden är sanna?$kuggfri$, $kuggfri$CO₂-avtryck och inbäddad energi kan användas i materialindex, genom att densiteten $\rho$ ersätts med $CO_2\,\rho$ eller $H_m\,\rho$ när utsläpp eller energi ska minimeras. Återvinning minskar behovet av råvara, energiåtgången och CO₂-utsläppen. Kursens "material för morgondagen" ska ha både lågt CO₂-avtryck och låg inbäddad energi. Stål har låga CO₂-utsläpp per kilo; det är den stora användningen som ger stora globala utsläpp.$kuggfri$, null, 240, false, $kuggfri$c3faf8814$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"CO₂-avtryck (CO₂ footprint) och inbäddad energi (embodied energy) kan ge vägledning i materialvalet.","correct":true},{"text":"Material med högt CO₂-avtryck bör återvinnas.","correct":true},{"text":"Miljösmarta material har lågt CO₂-avtryck och hög inbäddad energi.","correct":false},{"text":"Problemet med stål är de stora CO₂-utsläppen per kilo tillverkat stål.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz vecka 1, fråga 6; Canvas, Fö 13 Hållbarhet, s. 6; Canvas, Fö 13 Hållbarhet, s. 11; Canvas, Fö 13 Hållbarhet, s. 13; Canvas, Tentamen Materialteknik med svar 2022-11-29, s. 5; Canvas, Tentamen Materialteknik mrd svar 2021-10-23 (korrigerad), formelbladet$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('b49069b5-5827-5ade-b542-a4d929c95b12', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2a0cb9e4-83a2-5694-93d8-c2458390173a', $kuggfri$hallb-atervinning-racker-inte$kuggfri$, $kuggfri$Varför räcker inte återvinning för att lösa framtidens materialförsörjning, och vad behövs utöver återvinning?$kuggfri$, $kuggfri$Återvinning räcker inte eftersom mängden material i användning ökar: efterfrågan på metaller är i dag ungefär två tredjedelar större än mängden skrot, så en modell för cirkulär ekonomi fungerar inte ensam. Dessutom uppstår förluster, och återvinning kostar energi och resurser.

Utöver återvinning behövs t.ex.:

* minskad materialanvändning, genom bättre design och höghållfasta material
* lång livslängd, återbruk och refabricering
* rätt materialval och tillverkningsmetod, cirkulära produktlösningar och ökad användning av förnybara material$kuggfri$, null, 241, false, $kuggfri$c8478d2be$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Svarsförslag uppgift 4-6, IMS085 251030, s. 2; Canvas, Fö 13 Hållbarhet, s. 7; Canvas, Fö 13 Hållbarhet, s. 17; Canvas, Fö 13 Hållbarhet, s. 21; Canvas, Fö 13 Hållbarhet, s. 22$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('746a0484-94ed-53aa-95a0-97d7b6d4435d', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2a0cb9e4-83a2-5694-93d8-c2458390173a', $kuggfri$hallb-andlig-resurs$kuggfri$, $kuggfri$Vad menas med att ett material är en ändlig resurs? Ge ett exempel där resursbristen är en växande utmaning.$kuggfri$, $kuggfri$Ett material är en ändlig resurs när det finns i begränsade mängder och riskerar att ta slut inom överskådlig tid.

Exempel: sällsynta jordartsmetaller, som används i magneter och där efterfrågan ökar snabbare än tillgången. Många tekniskt viktiga metaller är kritiska eller sällsynta, och återvinningsgraden är i vissa fall mycket låg, t.ex. för gallium, indium och germanium i halvledare.$kuggfri$, null, 242, false, $kuggfri$c7f4f21f7$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Svarsförslag uppgift 4-6, IMS085 251030, s. 2; Canvas, Fö 13 Hållbarhet, s. 8$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('0e690f81-2656-5683-9230-b0d5cf5dcddf', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2a0cb9e4-83a2-5694-93d8-c2458390173a', $kuggfri$hallb-eco-audit-vagracken$kuggfri$, $kuggfri$I kursens eco audit-exempel med krockbarriärer: vilken livscykelfas dominerar för ett fast vägräcke respektive en barriär monterad på en bil?$kuggfri$, $kuggfri$Eco audit visar i vilken livscykelfas mest resurser används, och därmed vad materialvalet ska optimera. För det fasta vägräcket dominerar materialproduktionen, så kriteriet blir böjhållfasthet per energienhet, index $\sigma_y^{2/3}/(H_p\,\rho)$. För barriären på bilen dominerar användningen, så kriteriet blir böjhållfasthet per massa, $\sigma_y^{2/3}/\rho$.$kuggfri$, null, 243, false, $kuggfri$c02582c13$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Vägräcket: materialproduktionen. Bilens barriär: användningen.","correct":true},{"text":"Vägräcket: användningen. Bilens barriär: materialproduktionen.","correct":false},{"text":"Materialproduktionen i båda fallen.","correct":false},{"text":"Användningen i båda fallen.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Kapitel_03 Materialval, s. 43; Canvas, Kapitel_03 Materialval, s. 46$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('73530d18-891e-5454-8a59-6f5952e80c7c', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2a0cb9e4-83a2-5694-93d8-c2458390173a', $kuggfri$hallb-atervinning-metaller$kuggfri$, $kuggfri$Vad stämmer om återvinning av metaller?$kuggfri$, $kuggfri$Vinsterna med återvinning av metaller är minskat behov av råvara, minskad energiåtgång, minskade CO₂-utsläpp och mindre deponi. En återvunnen metall får i princip inga försämrade egenskaper; metaller kan ge lika bra material. Problemet är föroreningar och legeringshalt: halten måste ligga inom toleranserna för legeringen, och eftersom det är dyrt och ofta omöjligt att raffinera metallen måste skrot av olika metaller sorteras och hållas åtskilt.$kuggfri$, null, 244, false, $kuggfri$c3fcc85c0$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Återvinning minskar behovet av råvara från naturen, energiåtgången och CO₂-utsläppen.","correct":true},{"text":"Återvunnen metall får alltid sämre egenskaper än metall tillverkad från malm.","correct":false},{"text":"Skrot av olika metaller och legeringar behöver sorteras och hållas åtskilt.","correct":true},{"text":"Legeringshalten i skrotet spelar ingen roll, eftersom metallen enkelt kan raffineras vid omsmältningen.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Tentamen Materialteknik med svar 2022-11-29, s. 5; Canvas, Fö 13 Hållbarhet, s. 21; Canvas, Fö 12 Stål, s. 12$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('02946e90-989c-56f9-a83c-903da2bdf953', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2a0cb9e4-83a2-5694-93d8-c2458390173a', $kuggfri$hallb-strategi-foretag$kuggfri$, $kuggfri$Nämn viktiga punkter i en hållbarhetsstrategi för materialval och materialanvändning på ett företag.$kuggfri$, $kuggfri$* Välj material som ger fungerande produkter med lång livslängd.
* Välj material som ger låga utsläpp av föroreningar och liten resurs- och energianvändning vid tillverkningen.
* Undvik kritiska och strategiska material.
* Välj material med litet CO₂-avtryck och låg inbäddad energi.
* Välj material som kan återvinnas.
* Tänk på hela produktcykeln: materialtillverkning, produkttillverkning, användning och återvinning.

Hållbara produkter fås av en kombination av rätt materialval, bra design, rätt tillverkningsmetod och rätt återvinning.$kuggfri$, null, 245, false, $kuggfri$cbcd6d341$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Tentamen Materialteknik med svar 2020-10-24, s. 3; Canvas, Fö 13 Hållbarhet, s. 22$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('14f66d86-e5b9-547e-81b4-36dae29462d3', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2a0cb9e4-83a2-5694-93d8-c2458390173a', $kuggfri$hallb-co2-i-materialindex$kuggfri$, $kuggfri$Hur tar man hänsyn till CO₂-avtrycket i ett materialindex för en lätt och stark balk, $\sigma_y^{2/3}/\rho$?$kuggfri$, $kuggfri$För att minimera CO₂-utsläpp eller inbäddad energi i stället för massa ersätts $\rho$ med $CO_2\,\rho$ respektive $H_m\,\rho$, där $CO_2$ och $H_m$ är utsläpp respektive energi per kg material. Indexet blir då $\sigma_y^{2/3}/(CO_2\,\rho)$, och i kursens vägräckesexempel används på samma sätt $\sigma_y^{2/3}/(H_p\,\rho)$. Att multiplicera indexet med CO₂-avtrycket skulle gynna material med höga utsläpp.$kuggfri$, null, 246, false, $kuggfri$cf89543b5$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Densiteten $\\rho$ ersätts med $CO_2\\,\\rho$ (CO₂-avtryck per kg gånger densitet)","correct":true},{"text":"Indexet multipliceras med CO₂-avtrycket","correct":false},{"text":"Sträckgränsen $\\sigma_y$ ersätts med CO₂-avtrycket","correct":false},{"text":"CO₂-avtrycket kan inte användas i ett materialindex, det kräver en livscykelanalys","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Tentamen Materialteknik mrd svar 2021-10-23 (korrigerad), formelbladet; Canvas, Kapitel_03 Materialval, s. 46; Canvas, Fö 13 Hållbarhet, s. 6$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('3a294a95-c4a8-5b72-bd4f-4fc16511a0c4', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2a0cb9e4-83a2-5694-93d8-c2458390173a', $kuggfri$hallb-hoghallfast-mindre-material$kuggfri$, $kuggfri$Höghållfasta metaller kan minska en produkts miljöbelastning, eftersom mindre material behövs.$kuggfri$, $kuggfri$Sant. Föreläsningen nämner höghållfasta metaller, som ger mindre material, tillsammans med bättre design, förbättrade tillverkningsmetoder, lätta metaller och kompositer när låg vikt behövs och återvunnen metall som sätt att konstruera miljövänligare med metaller.$kuggfri$, null, 247, false, $kuggfri$c23793811$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Fö 13 Hållbarhet, s. 17$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('15cd0ed2-9360-587e-af27-f1d623427237', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '2a0cb9e4-83a2-5694-93d8-c2458390173a', $kuggfri$hallb-biobaserad-bionedbrytbar$kuggfri$, $kuggfri$En biobaserad plast är alltid bionedbrytbar.$kuggfri$, $kuggfri$Falskt. Biobaserad betyder att plasten är framställd av biomassa (förnybara resurser), medan bionedbrytbar betyder att mikroorganismer kan bryta ned den till bland annat koldioxid och vatten. Egenskaperna är oberoende av varandra: biobaserad PE är inte bionedbrytbar, PCL och PBAT är bionedbrytbara men fossilbaserade, och PLA är både biobaserad och bionedbrytbar.$kuggfri$, null, 248, false, $kuggfri$c8cdfd9cc$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fö21, s. 20; Canvas, 2025 MTT085 Fö21, s. 21; Canvas, 2025 MTT085 Fö21, s. 23; Canvas, 2025 MTT085 Fö21, s. 24; Canvas, 2025 MTT085 Fö21, s. 25$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('6d7e0d18-64af-599f-81cf-b01a66a055f3', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$namn-minst-tva-olika-typer-av-polymerer$kuggfri$, $kuggfri$Nämn minst två olika typer av polymerer och vad som kännetecknar dem.$kuggfri$, $kuggfri$* Termoplaster
  - Långa polymerkedjor
  - Svaga bindningar mellan
kedjorna
  - Kan formas med värme
  - Återvinningsbara
* Härdplaster
  - Nätverk av molekyler
  - Kovalenta bindningar
  - Kan inte formas med värme
  - Inte återvinningsbara
* Gummi (elastomerer)
  - Glest tvärbundna
polymerkedjor
  - Kan inte formas med värme
  - Inte återvinningsbara$kuggfri$, null, 249, true, $kuggfri$c6f076d40$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, null, null, true);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('283dbbeb-23e8-5332-9eeb-f0f2ac460b39', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$quiz-a-semi-crystalline-polymer-en$kuggfri$, $kuggfri$Vad stämmer om en delkristallin (semi-crystalline) polymer?$kuggfri$, $kuggfri$Termoplaster delas in i amorfa och delkristallina. Över Tm är polymeren en smälta, och i smält tillstånd är alla polymerer amorfa. Om en polymer kan bli delkristallin beror på hur ordnad kedjan är (kedjorna måste kunna packas sida vid sida), inte på gjutning; en amorf polymer blir inte delkristallin av att gjutas. Tm ligger över Tg: vid Tg mjuknar de amorfa delarna medan kristalliterna håller ihop materialet ända upp till Tm.$kuggfri$, null, 250, false, $kuggfri$cd30609fd$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Den är en typ av termoplast","correct":true},{"text":"Den är amorf över smälttemperaturen","correct":true},{"text":"Den tillverkas genom att en amorf polymer (t.ex. PS) gjuts","correct":false},{"text":"Den smälter under glasomvandlingstemperaturen","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fo15-18, fråga 1; Canvas, MTT085 PM 1, s. 7, 9; Canvas, MTT085 PM 2, s. 4; Canvas, MTT085 PM 3, s. 4$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('9951067a-f742-56ab-9cac-75f9e454e930', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$quiz-thermoplastic-polymers-termoplastiska$kuggfri$, $kuggfri$Vad stämmer om termoplaster?$kuggfri$, $kuggfri$Termoplaster är antingen amorfa eller delkristallina. Som smälta är de skjuvförtunnande: viskositeten minskar när skjuvhastigheten ökar. De hårdnar inte vid uppvärmning; modulen sjunker kraftigt vid Tg (och vid Tm för delkristallina). Polymerer är termiska isolatorer eftersom långa molekyler kan fördela värmeenergin på många vibrationsmoder.$kuggfri$, null, 251, false, $kuggfri$c07930d0d$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Som smälta har de en skjuvförtunnande viskositetsfunktion","correct":true},{"text":"De är amorfa eller delkristallina","correct":true},{"text":"De hårdnar när temperaturen ökar","correct":false},{"text":"De är värmeledande polymerer","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fo15-18, fråga 2; Canvas, MTT085 PM 1, s. 7; Canvas, MTT085 PM 3, s. 6; Canvas, MTT085 PM 2, s. 1, 3$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('9ab0affa-2df7-52a4-b3ab-ec709c2492ba', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$quiz-copolymers-sampolymerer-tva-ratta-svar$kuggfri$, $kuggfri$Vad stämmer om sampolymerer (copolymers)?$kuggfri$, $kuggfri$En sampolymer har två eller fler monomertyper i samma kedja och kan vara linjär eller (långkedje)grenad. Efter hur monomererna är ordnade skiljer man på slumpvisa, alternerande, block- och ympsampolymerer (graft); slagseg polystyren (PS-HI) görs till exempel genom att polystyren ympas på polybutadien. Polydispersitetsindex, PDI = Mw/Mn, beskriver hur bred molekylviktsfördelningen är och har inget med antalet monomertyper att göra. Eftersom Mw ≥ Mn kan PDI aldrig bli negativt.$kuggfri$, null, 252, false, $kuggfri$cf46c7f9d$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"De innehåller två eller fler typer av monomerer i samma kedja","correct":true},{"text":"De kan vara linjära eller grenade","correct":true},{"text":"De är polymerer med högt polydispersitetsindex","correct":false},{"text":"De är polymerer med negativt polydispersitetsindex","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fo15-18, fråga 3; Canvas, Tentamen MTT085 24-01, s. 8; Canvas, Svarsforslag Tentamen MTT085 24-01, s. 3; Canvas, 05142_03-3 (Osswald kap. 3), s. 25–26; Canvas, MTT085-Turorials-Part12, s. 1; Canvas, MTT085 PM 1, s. 6$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('ffdcde92-80fd-5de8-907a-56ab654808bf', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$quiz-thermosets-hardplaster-tva-ratta-svar$kuggfri$, $kuggfri$Vad stämmer om härdplaster (thermosets)?$kuggfri$, $kuggfri$Härdplaster är högt tvärbundna amorfa polymerer. Nätverket bildas vid härdningen (curing) av monomerer som kan binda till fler än två andra monomerer. Som amorfa polymerer har de ett Tg, men de bryts ned innan de hinner smälta och har därför ingen Tm. Härdplast är en indelning efter struktur (hög tvärbindningsgrad), inte efter användningsområde; epoxi, den vanligaste härdplasten, har till exempel ett Tg kring 120 °C.$kuggfri$, null, 253, false, $kuggfri$ca4539993$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"De tillverkas av monomerer med fler än två bindningsställen (funktionalitet > 2)","correct":true},{"text":"De är amorfa","correct":true},{"text":"De saknar glasomvandlingstemperatur men har en smälttemperatur","correct":false},{"text":"De definieras som den grupp polymerer som tagits fram för högtemperaturtillämpningar","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fo15-18, fråga 4; Canvas, MTT085 PM 1, s. 10; Canvas, 2025 MTT085 Fo15, s. 44; Canvas, MTT085 PM 2, s. 4$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('04c32d7f-ff3f-5199-926f-daae4004189d', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-pdi-vad-mater$kuggfri$, $kuggfri$Vad mäter polydispersitetsindex, PDI = Mw/Mn?$kuggfri$, $kuggfri$PDI är kvoten mellan viktmedelmolekylvikten Mw och antalsmedelmolekylvikten Mn och är ett mått på hur bred molekylviktsfördelningen är: ju högre PDI, desto bredare fördelning. Medelvärdena är Mn och Mw själva, inte kvoten. PDI mäter varken flytbarhet eller någon övergångstemperatur.$kuggfri$, null, 254, false, $kuggfri$c2b10a850$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Hur bred molekylviktsfördelningen är","correct":true},{"text":"Medelvärdet av molekylviktsfördelningen","correct":false},{"text":"Polymersmältans flytbarhet","correct":false},{"text":"Polymersmältans glasomvandlingstemperatur","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 1, s. 5–6; Canvas, 2025 MTT085 Fo15, s. 31; Canvas, Tentamen MTT085 24-10, s. 15$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('bd6ff061-f62f-5707-a296-f26502b37a58', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-mn-mw-berakning$kuggfri$, $kuggfri$En polymer består av lika många kedjor med molekylvikten 100 000, 200 000 och 300 000 g/mol. Vad blir Mn och Mw?$kuggfri$, $kuggfri$Med $n_i$ kedjor av molekylvikten $M_i$ (här $n_i$ lika för alla tre):

$M_n = \dfrac{\sum n_i M_i}{\sum n_i} = \dfrac{100\,000 + 200\,000 + 300\,000}{3} = 200\,000$ g/mol

$M_w = \dfrac{\sum n_i M_i^2}{\sum n_i M_i} = \dfrac{(1 + 4 + 9)\cdot 10^{10}}{6 \cdot 10^{5}} \approx 233\,333$ g/mol

Mw väger de tunga kedjorna tyngre och blir därför större än Mn; Mw = Mn gäller bara om alla kedjor är lika långa. PDI blir här ungefär $1{,}17$.$kuggfri$, null, 255, false, $kuggfri$cee96c3c0$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Mn = 200 000 g/mol och Mw ≈ 233 000 g/mol","correct":true},{"text":"Mn ≈ 233 000 g/mol och Mw = 200 000 g/mol","correct":false},{"text":"Mn = Mw = 200 000 g/mol","correct":false},{"text":"Mn = 200 000 g/mol och Mw = 300 000 g/mol","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fo15, s. 28; Canvas, MTT085 PM 1, s. 5$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('83779b45-3c8f-5f5b-aa02-fb3a917ad7c0', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-polymerisationsgrad-pe-berakning$kuggfri$, $kuggfri$Uppskatta polymerisationsgraden för en polyeten med molekylvikten 150 000 g/mol (etenmonomeren väger 28 g/mol).$kuggfri$, $kuggfri$Polymerisationsgraden är antalet repeterande enheter: $DP = M/M_0 = 150\,000/28 \approx 5\,357$. Etenmonomeren C₂H₄ väger $2\cdot 12 + 4\cdot 1 = 28$ g/mol. 3 570 är svaret för en kedja på 100 000 g/mol, 10 700 fås om man räknar med CH₂ (14 g/mol) i stället för hela monomeren, och 4 200 000 fås om man multiplicerar i stället för att dividera.$kuggfri$, null, 256, false, $kuggfri$c97d945b4$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Ca 5 360 repeterande enheter","correct":true},{"text":"Ca 3 570 repeterande enheter","correct":false},{"text":"Ca 10 700 repeterande enheter","correct":false},{"text":"Ca 4 200 000 repeterande enheter","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085-Turorials-Part12, s. 4; Canvas, 2021 MTT085 Ovningsuppgifter - Polymera material, s. 2; Canvas, MTT085 PM 1, s. 2$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('dadb2efa-4868-535b-a1ec-17949a1e290a', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-kedjelangd-pe-berakning$kuggfri$, $kuggfri$Hur lång är en fullt utsträckt polyetenmolekyl med molekylvikten 100 000 g/mol? (Repeterande enhet 28 g/mol, 0,252 nm per enhet.)$kuggfri$, $kuggfri$Antalet repeterande enheter är $n = 100\,000/28 \approx 3\,571$. Den utsträckta längden blir $l = 3\,571 \cdot 0{,}252 \text{ nm} \approx 900$ nm. 25 µm fås om man multiplicerar molekylvikten direkt med 0,252 nm i stället för antalet enheter.$kuggfri$, null, 257, false, $kuggfri$c453f6c2f$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Ca 900 nm (0,9 µm)","correct":true},{"text":"Ca 0,9 nm","correct":false},{"text":"Ca 25 µm","correct":false},{"text":"Ca 90 µm","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Svar Materialteknik 2019-10-26, s. 3; Canvas, MTT085-Turorials-Part12, s. 4$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('dc47a08e-fe2b-56d8-b92d-1a07dc442765', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-vinylpolymerer-sidogrupper$kuggfri$, $kuggfri$Vinylpolymerer har den repeterande enheten –[CH₂–CHX]ₙ–. Vilka par av sidogrupp X och polymer är rätt?$kuggfri$, $kuggfri$Sidogrupperna i kursen: X = H ger PE, X = CH₃ ger PP, X = C₆H₅ (fenylgrupp) ger PS och X = Cl ger PVC. De två felaktiga alternativen har bytt plats på PP och PS.$kuggfri$, null, 258, false, $kuggfri$c9610c88d$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"X = H ger polyeten (PE)","correct":true},{"text":"X = Cl ger polyvinylklorid (PVC)","correct":true},{"text":"X = CH₃ ger polystyren (PS)","correct":false},{"text":"X = C₆H₅ ger polypropen (PP)","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fo15, s. 20; Canvas, MTT085 PM 1, s. 3; Canvas, Svar Materialteknik 2018-10-27, s. 7$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('567691ef-7d20-5b22-9090-41de770e26f2', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-sfaruliter-polariserat-ljus$kuggfri$, $kuggfri$Vilken typ av polymer har du om du ser sfäruliter i ett optiskt mikroskop med polariserat ljus?$kuggfri$, $kuggfri$Sfäruliter är överstrukturer av kristallina lameller och finns bara i delkristallina polymerer; de syns tydligt i polariserat ljus och kan vara från ungefär 1 till 500 µm stora. Amorfa termoplaster saknar överstruktur (slumpvis orienterade kedjor), och härdplaster och elastomerer är amorfa tvärbundna polymerer.$kuggfri$, null, 259, false, $kuggfri$c0420c1fd$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"En delkristallin termoplast","correct":true},{"text":"En amorf termoplast","correct":false},{"text":"En tvärbunden elastomer","correct":false},{"text":"En härdplast","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Tentamen MTT085 24-10, s. 17–18; Canvas, MTT085 PM 1, s. 8–9; Canvas, 2025 MTT085 Fo15, s. 41$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('473b8752-11e6-5c4f-b319-e551d75d1b2c', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-transparent-isotaktisk-pp$kuggfri$, $kuggfri$En extruderad isotaktisk polypropen (Tg ≈ −10 °C, Tm ≈ 165 °C) är helt transparent. Vad är den troliga orsaken?$kuggfri$, $kuggfri$PP är normalt en delkristallin termoplast, och isotaktisk PP kan nå hög kristallinitet. Kristalliterna gör vanligtvis materialet translucent eller opakt, så en helt transparent detalj tyder på att snabb kylning hindrade kristallisationen. Materialet är fortfarande en termoplast och kan därför smältas om och återvinnas.$kuggfri$, null, 260, false, $kuggfri$c5e303a6c$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Snabb kylning hindrade materialet från att kristallisera","correct":true},{"text":"PP är en amorf polymer","correct":false},{"text":"Materialet är tvärbundet till en härdplast","correct":false},{"text":"Isotaktisk PP kan inte kristallisera","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Tentamen Materialteknik mrd svar 2021-10-23 korrigerad, uppgift 7a; Canvas, MTT085 PM 1, s. 9; Canvas, 2025 MTT085 Fo16, s. 17$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('50fd9e64-98f0-56a7-9f99-1b37409bf8cb', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-hardplast-tg-atervinning$kuggfri$, $kuggfri$Hur påverkar de termiska egenskaperna hos härdplaster deras återvinningsbarhet?$kuggfri$, $kuggfri$Härdplaster är högt tvärbundna amorfa polymerer. Som amorfa har de ett Tg, där de mjuknar något, men de kovalenta tvärbindningarna gör att de bryts ned innan de kan smälta. De saknar alltså Tm och kan inte smältas om och formas på nytt.$kuggfri$, null, 261, false, $kuggfri$c9e7e9c46$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Härdplaster har ett Tg men kan inte smältas om och bearbetas på nytt","correct":true},{"text":"Härdplaster har både Tm och Tg och kan därför formas om vid höga temperaturer","correct":false},{"text":"Härdplaster kan smältas om vid Tm och bearbetas på nytt","correct":false},{"text":"Härdplaster har en kritisk temperatur där de kristalliserar under återvinningen","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Tentamen MTT085 24-10, s. 18; Canvas, MTT085 PM 2, s. 4; Canvas, 2025 MTT085 Fo16, s. 19; Canvas, MTT085 PM 1, s. 10$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('97c92a0c-779a-52d9-b40a-f5b3b9cc448a', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-overgangstemperaturer-per-typ$kuggfri$, $kuggfri$Vilka övergångstemperaturer har de olika polymertyperna?$kuggfri$, $kuggfri$Amorfa termoplaster har bara Tg. Delkristallina har Tg, där de amorfa delarna mjuknar, och Tm, där kristalliterna smälter. Tvärbundna polymerer (härdplaster och elastomerer) är amorfa och har därför ett Tg, men de bryts ned innan de smälter och har ingen Tm.$kuggfri$, null, 262, false, $kuggfri$cb0411111$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Amorf termoplast: Tg men ingen Tm","correct":true},{"text":"Delkristallin termoplast: både Tg och Tm","correct":true},{"text":"Härdplast: både Tg och Tm","correct":false},{"text":"Tvärbunden elastomer: Tm men inget Tg","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fo16, s. 21; Canvas, MTT085 PM 2, s. 3–4$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('da6e82be-8e94-5770-8792-c2e354ffaf16', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-anvandningsintervall-delkristallin$kuggfri$, $kuggfri$Inom vilket temperaturintervall används en delkristallin termoplast?$kuggfri$, $kuggfri$Mellan Tg och Tm har de amorfa delarna mjuknat medan kristalliterna håller ihop materialet, och segheten ökar i det intervallet. Under Tg blir delkristallina polymerer typiskt mycket spröda, och över Tm är de smältor. Användningsintervallet är därför Tg < T < Tm.$kuggfri$, null, 263, false, $kuggfri$cde9adecc$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Mellan Tg och Tm","correct":true},{"text":"Under Tg","correct":false},{"text":"Över Tm","correct":false},{"text":"Mellan Tm och nedbrytningstemperaturen","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 2, s. 4; Canvas, 2025 MTT085 Fo16, s. 18$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('de64eb5d-aeb9-5579-883e-62a43fcaf17c', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-skjuvmodul-amorf-vid-tg$kuggfri$, $kuggfri$Vad händer med skjuvmodulen hos en amorf termoplast, t.ex. PS, när temperaturen passerar Tg?$kuggfri$, $kuggfri$Vid Tg vibrerar kedjorna så kraftigt att de kan röra sig betydligt friare, och skjuvmodulen faller med ungefär tre dekader (logaritmisk axel i DMTA-kurvan). En amorf termoplast har ingen Tm och inga kristalliter; det är i en delkristallin polymer som kristalliterna håller ihop materialet över Tg.$kuggfri$, null, 264, false, $kuggfri$c1425198d$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Den sjunker med ungefär tre dekader (ca 1 000 gånger)","correct":true},{"text":"Den ökar, eftersom kedjorna låses fast","correct":false},{"text":"Den är i stort sett oförändrad tills Tm nås","correct":false},{"text":"Den sjunker bara lite, eftersom kristalliterna håller ihop materialet","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 2, s. 3–4; Canvas, 2025 MTT085 Fo16, s. 13$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('1ceedd76-2354-5513-867a-3121cd74963c', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-tillsats-mjukgorare$kuggfri$, $kuggfri$Vilken tillsats sänker hårdheten och styvheten hos en plast?$kuggfri$, $kuggfri$Mjukgörare ökar avståndet mellan molekylerna, vilket sänker styvheten och Tg. Stabilisatorer skyddar mot termisk och kemisk nedbrytning (värme, solljus, syre), antistatmedel hindrar att plasten laddas upp elektrostatiskt och flamskyddsmedel minskar brännbarheten.$kuggfri$, null, 265, false, $kuggfri$ceaa80d83$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Mjukgörare","correct":true},{"text":"Stabilisator","correct":false},{"text":"Antistatmedel","correct":false},{"text":"Flamskyddsmedel","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085-Turorials-Part12, s. 1–2; Canvas, 05142_03-3 (Osswald kap. 3), s. 3$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('8d938d92-46f9-5232-92b4-b7c055b734a1', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-pdi-ett-monodispers$kuggfri$, $kuggfri$Ett PDI på 1 betyder att alla kedjor i polymeren är lika långa.$kuggfri$, $kuggfri$Eftersom Mw ≥ Mn är PDI = Mw/Mn alltid minst 1. Mw = Mn, alltså PDI = 1, gäller bara om alla kedjor är lika långa (monodispers polymer). De flesta polymerer är polydispersa med PDI > 1.$kuggfri$, null, 266, false, $kuggfri$c187fcbc9$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 1, s. 6; Canvas, 05142_03-3 (Osswald kap. 3), s. 6$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('63e21d2d-46bb-59c9-b07c-3397a3f2fec7', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-ataktisk-pp-kristallinitet$kuggfri$, $kuggfri$Ataktisk polypropen når lättare en hög kristallinitetsgrad än isotaktisk polypropen.$kuggfri$, $kuggfri$Det är tvärtom. I isotaktisk PP sitter alla CH₃-grupper på samma sida, så kedjorna kan packas sida vid sida och nå hög kristallinitet. I ataktisk PP sitter sidogrupperna slumpvis, vilket gör det svårt för grannkedjorna att låsas i ett ordnat läge.$kuggfri$, null, 267, false, $kuggfri$cd07346eb$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 1, s. 9; Canvas, 05142_03-3 (Osswald kap. 3), s. 9$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('d01cfe0c-6d62-58e3-ab60-226999748744', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-restmonomer-tg$kuggfri$, $kuggfri$Restmonomer som finns kvar i polymeren efter polymerisationen, och som är löslig i polymeren, höjer dess Tg.$kuggfri$, $kuggfri$Restmonomer som är löslig i polymeren fungerar som mjukgörare och sänker Tg. Mjukgörare ökar avståndet mellan molekylerna så att de rör sig lättare.$kuggfri$, null, 268, false, $kuggfri$cd20ba14c$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085-Turorials-Part12, s. 4; Canvas, 05142_03-3 (Osswald kap. 3), s. 3$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('45bac8ca-f0d5-5254-ac41-a56b80ae4fa8', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-samma-mn-samma-fordelning$kuggfri$, $kuggfri$Två polymerer med samma antalsmedelmolekylvikt Mn har alltid samma molekylviktsfördelning.$kuggfri$, $kuggfri$Mn är bara ett medelvärde av fördelningen. Hur bred fördelningen är beskrivs av PDI = Mw/Mn, och två polymerer med samma Mn kan ha olika Mw och därmed olika bred fördelning. Kursboken visar till exempel polystyren med PDI 1,1, 2,2 och 3,1 med olika egenskaper.$kuggfri$, null, 269, false, $kuggfri$c16ed5f57$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 1, s. 3, 5–6; Canvas, 05142_03-3 (Osswald kap. 3), s. 6–7; Canvas, Tentamen MTT085 25-01, s. 9$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('dbfb6179-eb1b-5c5b-b5ee-1379f6c12e07', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-amorf-termoplast-under-tg$kuggfri$, $kuggfri$En amorf termoplast används, med säkerhetsmarginal, vid temperaturer under sitt Tg.$kuggfri$, $kuggfri$Över Tg förlorar en amorf termoplast sin styvhet, eftersom det inte finns några kristalliter som håller ihop materialet. Användningstemperaturen är därför T < Tg med en säkerhetsmarginal. För delkristallina termoplaster är det i stället Tm som begränsar uppåt.$kuggfri$, null, 270, false, $kuggfri$ce0b57061$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 2, s. 4; Canvas, Lab-PM Polymer_MTT085-1, s. 2$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('f9c753c5-9643-5452-9368-9ed9aed9defa', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-takticitet-inte-forgrening$kuggfri$, $kuggfri$Takticitet och långkedjeförgrening är samma sak.$kuggfri$, $kuggfri$Takticitet beskriver hur sidogrupperna är placerade längs kolkedjan (isotaktisk, syndiotaktisk, ataktisk). Långkedjeförgrening (topologi) betyder att molekylen har sidokedjor, som i LDPE.$kuggfri$, null, 271, false, $kuggfri$c0d0067dd$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Tentamen Materialteknik med svar 2020-10-24, s. 8; Canvas, MTT085 PM 1, s. 7$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('d6f86627-50aa-5d14-a95d-a597122bb60a', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-kovalent-och-van-der-waals$kuggfri$, $kuggfri$I polyeten hålls huvudkedjan ihop av starka kovalenta C–C-bindningar, medan kedjorna binds till varandra av svaga van der Waals-krafter.$kuggfri$, $kuggfri$C–C-bindningarna i huvudkedjan är kovalenta och starka, medan krafterna mellan kedjorna är van der Waals-krafter och svaga. Därför bestäms polymerens hållfasthet i praktiken av krafterna mellan kedjorna, och längre kedjor ger ett starkare material.$kuggfri$, null, 272, false, $kuggfri$cdabf6254$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 1, s. 3; Canvas, 05142_03-3 (Osswald kap. 3), s. 2; Canvas, 2025 MTT085 Fo15, s. 14$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('3a6aebce-c633-5399-9940-c33f754f420b', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-hdpe-ldpe-kristallinitet$kuggfri$, $kuggfri$HDPE har högre kristallinitet än LDPE eftersom LDPE:s långkedjeförgreningar hindrar kedjorna från att packas tätt.$kuggfri$, $kuggfri$HDPE består av linjära molekyler och kan nå en kristallinitet på upp till ca 75 %. LDPE har långkedjeförgreningar som hindrar grannkedjorna från att närma sig och låsas sida vid sida, vilket ger lägre kristallinitet.$kuggfri$, null, 273, false, $kuggfri$c7b2079bb$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 1, s. 9; Canvas, 2025 MTT085 Fo15, s. 35$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('8f684ce6-4de6-5b9f-b4ce-adfed2527c47', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-begrepp-monomer$kuggfri$, $kuggfri$Monomer$kuggfri$, $kuggfri$Den repeterande byggstenen i en polymer: en molekyl som kan binda till likadana molekyler och bilda en polymerkedja genom polymerisation. Exempel: eten (C₂H₄, en gas) är monomeren i polyeten.$kuggfri$, null, 274, false, $kuggfri$c7a16e172$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085-Turorials-Part12, s. 1; Canvas, MTT085 PM 1, s. 1$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('460329c1-b30b-5eb3-ac6f-56bf7a551b15', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-begrepp-polymerisationsgrad$kuggfri$, $kuggfri$Polymerisationsgrad$kuggfri$, $kuggfri$Antalet repeterande enheter n i en polymerkedja. Den kan uppskattas som molekylvikten delad med monomerens molekylvikt: $DP = M/M_0$.$kuggfri$, null, 275, false, $kuggfri$c9fb402cb$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 1, s. 2; Canvas, 05142_03-3 (Osswald kap. 3), s. 1; Canvas, MTT085-Turorials-Part12, s. 4$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('8618552f-17ac-5cf0-9455-ef38c43505a4', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-begrepp-takticitet$kuggfri$, $kuggfri$Takticitet (tacticity)$kuggfri$, $kuggfri$Hur sidogrupperna är placerade längs kolkedjan. Isotaktisk: alla på samma sida. Syndiotaktisk: regelbundet omväxlande. Ataktisk: slumpvis. Takticiteten avgör hur hög kristallinitet polymeren kan nå; isotaktisk PP blir mer kristallin än ataktisk.$kuggfri$, null, 276, false, $kuggfri$c523d47fb$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 05142_03-3 (Osswald kap. 3), s. 9; Canvas, MTT085 PM 1, s. 7, 9$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('d9140ad5-4928-5582-af62-1a968be6a154', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-begrepp-sampolymer$kuggfri$, $kuggfri$Sampolymer (copolymer)$kuggfri$, $kuggfri$En polymer vars kedjor innehåller två eller fler typer av monomerer (en homopolymer har bara en). Typer: slumpvis, alternerande, block och ymp (graft). Exempel: ABS (akrylnitril-butadien-styren) och SBR (styren-butadiengummi).$kuggfri$, null, 277, false, $kuggfri$ce213ea18$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 05142_03-3 (Osswald kap. 3), s. 25–26; Canvas, MTT085-Turorials-Part12, s. 1$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('370fceac-3581-5cd3-8911-9ec604678c01', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-begrepp-polymerblandning$kuggfri$, $kuggfri$Polymerblandning (polymer blend)$kuggfri$, $kuggfri$En blandning av två eller fler polymerer som görs för att förbättra egenskaperna hos de enskilda polymererna. Till skillnad från en sampolymer sitter de olika monomererna inte i samma kedja. Exempel: PP-PC, PVC-ABS och LDPE + HDPE.$kuggfri$, null, 278, false, $kuggfri$ccb3b8dde$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 05142_03-3 (Osswald kap. 3), s. 27; Canvas, 2025 MTT085 Fo15, s. 34$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('d21e7463-8d8a-55a3-a2ac-aa2fc377bc4d', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-begrepp-sfarulit$kuggfri$, $kuggfri$Sfärulit (spherulite)$kuggfri$, $kuggfri$Den största strukturen (längdskalan) i en delkristallin polymer: kristalliterna bildar lameller, som i sin tur bygger upp sfäruliter, och mellan dem finns amorfa områden. Sfäruliter kan vara ungefär 1 till 500 µm stora, alltså mycket större än ljusets våglängd, och syns tydligt i ett mikroskop med polariserat ljus.$kuggfri$, null, 279, false, $kuggfri$cca57b38b$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 1, s. 8–9; Canvas, 2025 MTT085 Fo16, s. 15; Canvas, MTT085 Polymeric materials L6, s. 8$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('11b1379c-2006-5afc-82e1-8e59d3461288', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-begrepp-tvarbindning$kuggfri$, $kuggfri$Tvärbindning (crosslinking)$kuggfri$, $kuggfri$Bindningspunkter, i tekniska polymerer oftast kovalenta, som knyter ihop kedjorna till ett nätverk. De bildas vid härdning (curing) av monomerer med fler än två bindningsställen. Kovalent tvärbundna polymerer kan inte smältas om. Hög tvärbindningsgrad ger en styv härdplast, låg ger en elastomer.$kuggfri$, null, 280, false, $kuggfri$ceb55ddbc$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 1, s. 10; Canvas, 2025 MTT085 Fo15, s. 44$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('84bccc40-c54b-56d7-bf13-d8c3783c54a1', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-begrepp-glasomvandlingstemperatur$kuggfri$, $kuggfri$Glasomvandlingstemperatur (Tg)$kuggfri$, $kuggfri$Temperaturen där en amorf polymer, eller de amorfa delarna av en delkristallin polymer, går från glasartat tillstånd till ett gummiartat eller smält tillstånd. Omvandlingen är reversibel och är inte smältpunkten; styvheten sjunker kraftigt vid Tg.$kuggfri$, null, 281, false, $kuggfri$cb726591d$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085-Turorials-Part12, s. 4; Canvas, MTT085 PM 2, s. 3–4$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('75df7fe7-7794-56c9-a4d8-32e08f5bc392', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-varfor-termiska-isolatorer$kuggfri$, $kuggfri$Varför är polymerer bra termiska isolatorer?$kuggfri$, $kuggfri$I metaller leds värme som vågor av gittervibrationer (fononer). En lång polymermolekyl kan ses som atomer med bindningar som inte är lika i alla riktningar, så en temperaturökning kan fördelas på väldigt många vibrationsmoder i molekylen. Därför isolerar polymerer. Skum isolerar bäst, t.ex. frigolit (PS-skum), eftersom de innehåller mycket luft.$kuggfri$, null, 282, false, $kuggfri$cbb2d5390$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 2, s. 1–2; Canvas, 2025 MTT085 Fo16, s. 7–8, 21; Canvas, 2025 MTT085 Fo15, s. 21$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('41e82126-2866-5636-8cfa-85bcda660c3e', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-hardplast-elastomer-likhet-skillnad$kuggfri$, $kuggfri$Vad är en likhet och en skillnad i struktur mellan en härdplast och en elastomer?$kuggfri$, $kuggfri$**Likhet:** båda är amorfa, tvärbundna polymerer som inte kan smältas om.

**Skillnad:** tvärbindningstätheten. Härdplaster är högt tvärbundna och därför styva. Elastomerer är glest tvärbundna, så stora delar av kedjorna är fria och klarar mycket stora töjningar. Tg beror på tvärbindningsgraden: för elastomerer kan den ligga så lågt som −50 °C, för härdplaster så högt som ca 120 °C (epoxi).$kuggfri$, null, 283, false, $kuggfri$c462353d1$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Tentamen Materialteknik mrd svar 2021-10-23 korrigerad, uppgift 7b; Canvas, MTT085 PM 1, s. 10; Canvas, MTT085 PM 2, s. 4$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('11aa2f18-9e99-57b3-afe3-956e5962fabf', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', 'ca58740d-bf59-5401-9bf0-3e5f7e352f54', $kuggfri$polymer-transparens-amorf-delkristallin$kuggfri$, $kuggfri$Varför är amorfa termoplaster transparenta medan delkristallina ofta är translucenta eller opaka?$kuggfri$, $kuggfri$**Amorfa** termoplaster (t.ex. PS, PC, PMMA) består av slumpvis orienterade kedjor utan överstruktur och är transparenta om de inte innehåller pigment eller andra tillsatser.

**Delkristallina** (t.ex. PE, PP, PA) innehåller kristalliter och amorfa områden med olika brytningsindex, så ljus sprids vid gränserna mellan dem. När kristalliterna och sfäruliterna är ungefär lika stora som eller större än ljusets våglängd blir materialet translucent eller opakt.$kuggfri$, null, 284, false, $kuggfri$c56778262$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 1, s. 8–10; Canvas, 2025 MTT085 Fo16, s. 15$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('feca862f-6cd5-569d-9d89-0718b0478aae', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$quiz-the-melt-flow-index-smaltflodesindex$kuggfri$, $kuggfri$Vilka påståenden om smältflödesindex (melt flow index, MFI) stämmer?$kuggfri$, $kuggfri$MFI är massan polymer i gram som en kolv belastad med en standardiserad vikt pressar ut genom ett cylindriskt munstycke under 10 minuter, vid standardiserad temperatur. Enheten är därför g/10 min. En trögare smälta (högre viskositet) ger mindre utpressat material och alltså lägre MFI. MFI är ett flödesmått, inte ett mått på brottöjning, och det mäts i en MFI-mätare (melt flow indexer) med kolv och munstycke, inte i en extruder.$kuggfri$, null, 285, false, $kuggfri$cf8a5da6a$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Det anges i gram per 10 minuter.","correct":true},{"text":"Det står i omvänt förhållande till viskositeten: högre viskositet ger lägre MFI.","correct":true},{"text":"Det mäter brottöjningen hos polymerer.","correct":false},{"text":"Det bestäms i försök med en enskruvsextruder utan munstycke.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fö15-18, fråga 5; Canvas, MTT085 PM 3, s. 7; Canvas, 2025 MTT085 Fö17, s. 23$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('c9199cfe-e78e-5de2-ae5e-de6f3557d00c', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$quiz-extrusion-extrudering-tva-ratta-svar$kuggfri$, $kuggfri$Vilka påståenden om extrudering stämmer?$kuggfri$, $kuggfri$Fiberspinning är en sekundär formning som kopplas till extrudering: smältan extruderas genom ett munstycke med ett eller flera hål och dras ut av valspar. Extruderns munstycke ger slutprofilen, t.ex. rör, filmer, filament och profiler. Extrudering är en bearbetningsmetod, inte en provningsmetod. Granulatet ska inte smälta i tratten: inmatningszonen kyls ofta just för att granulatet inte ska smälta och sätta igen inloppet, och smältningen sker först i cylinderns uppvärmda del.$kuggfri$, null, 286, false, $kuggfri$c7283ef60$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Det är grundprocessen för fiberspinning.","correct":true},{"text":"Det kan användas för att tillverka rör.","correct":true},{"text":"Det är en metod för att prova polymerers termiska egenskaper.","correct":false},{"text":"Det kräver att polymeren smälts redan i tratten.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fö15-18, fråga 6; Canvas, MTT085 Polymeric materials L4-5, s. 2; Canvas, MTT085 Polymeric materials L4-5, s. 4$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('c4ca9887-e586-58b0-b7bb-524a77ee6815', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$quiz-shear-thinning-skjuvtunning-tva-ratta$kuggfri$, $kuggfri$Vilka påståenden om skjuvförtunning (shear thinning) stämmer?$kuggfri$, $kuggfri$Viskositetsfunktionen har tre områden i ordning efter ökande skjuvhastighet: nollskjuvviskositeten vid låga skjuvhastigheter, det skjuvförtunnande området och oändlig-skjuv-viskositeten. I det skjuvförtunnande området sträcks kedjorna, orienteras i flödesriktningen och trasslas ur, så viskositeten minskar när skjuvhastigheten ökar. Det första området ligger alltså vid låga, inte höga, skjuvhastigheter. Skjuvförtunning gäller smältans viskositet, inte seghet.$kuggfri$, null, 287, false, $kuggfri$c4f9d0177$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Den orsakas av att polymerkedjorna gradvis orienteras i flödesriktningen, sträcks ut och trasslas ur.","correct":true},{"text":"Den är det andra området i viskositetskurvan för en polymersmälta.","correct":true},{"text":"Den är det första området i viskositetsfunktionen, vid mycket höga skjuvhastigheter.","correct":false},{"text":"Den avser att segheten hos polymera material minskar.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fö15-18, fråga 7; Canvas, MTT085 PM 3, s. 6; Canvas, 2025 MTT085 Fö17, s. 19$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('9279129f-16d6-546a-bafa-32e1934805ae', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$quiz-during-polymer-processing-vid$kuggfri$, $kuggfri$Vilka påståenden om skjuvhastigheten vid polymerbearbetning stämmer?$kuggfri$, $kuggfri$Små eller långsamma deformationer ändrar inte kedjornas orientering, medan stora eller snabba deformationer orienterar molekylerna i flödesriktningen. Varje bearbetningsmetod har sitt typiska skjuvhastighetsområde; fiberspinning ger mest orientering av kedjorna, medan formpressning, som sker vid låga skjuvhastigheter, ger lite orientering. Eftersom polymersmältor är skjuvförtunnande beror viskositeten av skjuvhastigheten. Skjuvhastigheten har enheten 1/s; Pa·s är enheten för viskositet.$kuggfri$, null, 288, false, $kuggfri$c19c91af9$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Höga skjuvhastigheter ger starkare molekylorientering i flödesriktningen.","correct":true},{"text":"De typiska skjuvhastigheterna skiljer sig mellan processer som extrudering, formsprutning och fiberspinning.","correct":true},{"text":"Skjuvhastigheten påverkar inte viskositeten.","correct":false},{"text":"Skjuvhastigheten mäts i pascalsekunder (Pa·s).","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fö15-18, fråga 8; Canvas, MTT085 PM 3, s. 6; Canvas, 2025 MTT085 Fö17, s. 9; Canvas, 2025 MTT085 Fö17, s. 22; Canvas, 2025 MTT085 Fö17, s. 28$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('31d1b81d-02a8-536e-ac52-45f7e8d99fc8', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$quiz-die-swelling-formsprutningssvallning$kuggfri$, $kuggfri$Vilka påståenden om extrudatsvällning (die swell) stämmer?$kuggfri$, $kuggfri$I munstycket utsätts smältan för skjuvflöde i det skjuvförtunnande området, så kedjorna sträcks, orienteras och kan trasslas ur. När smältan har lämnat munstycket och står under atmosfärstryck relaxerar kedjorna tillbaka mot sin föredragna konformation, och extrudatet blir större än munstyckets öppning. Det är alltså en elastisk effekt hos en viskoelastisk vätska; en newtonsk (rent viskös) vätska sväller inte. Smältflödet mäts med MFI, inte med extrudatsvällningen.$kuggfri$, null, 289, false, $kuggfri$cac656cda$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Den är en viskoelastisk effekt som uppstår när en polymersmälta lämnar munstycket.","correct":true},{"text":"Den orsakas av att orienterade och utsträckta polymerkedjor relaxerar.","correct":true},{"text":"Den är ett mått på smältflödeshastigheten.","correct":false},{"text":"Den förekommer bara i newtonska vätskor.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fö15-18, fråga 9; Canvas, 2025 MTT085 Fö17, s. 26-27; Canvas, MTT085 PM 3, s. 7-8$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('1dc68c3e-1485-5a32-a2a1-1a9a5ebae761', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$quiz-the-viscosity-function-of-a-polymer$kuggfri$, $kuggfri$Vilka påståenden om viskositetsfunktionen för en polymersmälta stämmer?$kuggfri$, $kuggfri$Viskositetsfunktionen ritas som viskositet mot skjuvhastighet i log-log-skala. Polymersmältor kallas skjuvförtunnande eftersom viskositeten minskar när de skjuvas snabbare; i nollskjuvområdet är den konstant, och den övre platån är svår att nå för smältor. Kurvorna sjunker när temperaturen höjs, och de skiljer sig mellan polymerer (t.ex. ABS, PC och PA6) och beror av molekylvikt och molekylviktsfördelning.$kuggfri$, null, 290, false, $kuggfri$c28639a47$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Den har tre huvudområden: en nollskjuvplatå, ett skjuvförtunnande område och en platå vid oändlig skjuvhastighet.","correct":true},{"text":"Den visar att viskositeten totalt sett minskar med ökande skjuvhastighet (skjuvförtunning).","correct":true},{"text":"Den är oberoende av temperaturen.","correct":false},{"text":"Den är densamma för alla polymersmältor.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fö15-18, fråga 10; Canvas, MTT085 PM 3, s. 6; Canvas, 2025 MTT085 Fö17, s. 19; Canvas, 2025 MTT085 Fö17, s. 22$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('af5eaa4d-1147-5278-abf3-22197b9a3234', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$quiz-the-injection-molding-cycle$kuggfri$, $kuggfri$Vilka påståenden om formsprutningscykeln stämmer?$kuggfri$, $kuggfri$Cykeln börjar när formen stängs; sedan sprutas smältan in, eftertryck läggs på, nästa skott matas fram och detaljen stöts ut när den har svalnat. Cykeltiden är $t_{\text{cykel}} = t_{\text{stängning}} + t_{\text{kylning}} + t_{\text{utstötning}}$, och kyltiden, då detaljen stelnar i formen, är ungefär 80 % av den. Det är detaljen i formen som ska kylas, inte skruven, och cykeln är en tillverkningsföljd, inte en mätmetod.$kuggfri$, null, 291, false, $kuggfri$c936d59ff$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Den domineras av stelningstiden.","correct":true},{"text":"Den börjar med att formen stängs.","correct":true},{"text":"Den mäter smältans viskositet.","correct":false},{"text":"Den domineras av avkylningen av skruven.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fö19-21, fråga 1; Canvas, MTT085 Polymeric materials L4-5, s. 6-7; Canvas, Tentamen Materialteknik med svar 2022-11-29, s. 7$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('0c62eceb-4108-506d-861a-4db3a1f21667', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$quiz-a-single-screw-extruder-en$kuggfri$, $kuggfri$Vilka påståenden om en enskruvsextruder stämmer?$kuggfri$, $kuggfri$I doseringszonen byggs det tryck upp som pressar smältan genom munstycket i extruderns ände; trycket är högst närmast munstycket, inte vid tratten. Munstycket ger produktens profil, t.ex. rör och slangfilm, och med film casting eller filmblåsning som sekundär formning blir det tunna filmer. Granulatet smälter inte i tratten; inmatningszonen kyls ofta just för att förhindra det.$kuggfri$, null, 292, false, $kuggfri$c0e98e7e6$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Skruven har en doseringszon (metering zone) som bygger upp trycket under flödet.","correct":true},{"text":"Den kan användas för att tillverka rör och tunna filmer.","correct":true},{"text":"Trycket byggs upp i inmatningszonen vid tratten.","correct":false},{"text":"Den smälter granulatet direkt i tratten.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fö19-21, fråga 2; Canvas, MTT085 Polymeric materials L4-5, s. 2-5; Canvas, Svarsförslag Tentamen MTT085 24-01, s. 3$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('c27d4aed-00c4-5110-b8b5-1c3d39516f1f', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$quiz-injection-molding-machines$kuggfri$, $kuggfri$Vilka påståenden om formsprutningsmaskiner stämmer?$kuggfri$, $kuggfri$En formsprutningsmaskin består av insprutningsenhet, plasticeringsenhet, form och stängningsenhet (clamping unit), och granulatet matas in genom en tratt. Maskinen arbetar i en cykel (stängning, insprutning, eftertryck, kylning, utstötning), inte kontinuerligt. Delkristallina polymerer formsprutas också; föreläsningen påpekar bara att kristallisationsvärmen måste föras bort och att de krymper mer, vilket delvis kompenseras med längre eftertryckstid och högre tryck.$kuggfri$, null, 293, false, $kuggfri$c1ad645b0$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"De arbetar kontinuerligt utan cykel.","correct":false},{"text":"De har en tratt för inmatning av granulat.","correct":true},{"text":"De har en insprutningsenhet och en stängningsenhet.","correct":true},{"text":"De kan inte användas för delkristallina polymerer.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fö19-21, fråga 3; Canvas, MTT085 Polymeric materials L4-5, s. 6; Canvas, 2025 MTT085 Fö18, s. 36; Canvas, 2025 MTT085 Fö19, s. 7$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('5bfaccc4-f814-5d4a-b5ce-f2f1b97a13d5', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$quiz-p-v-t-diagrams-refer-to-p-v-t-diagram$kuggfri$, $kuggfri$Vad står pVT-diagram för, och vad visar de?$kuggfri$, $kuggfri$Ett pVT-diagram visar specifik volym (volym per massa, alltså inversen av densiteten) som funktion av temperaturen vid olika tryck. I diagrammet syns t.ex. knäcken vid glasövergången för amorfa polymerer, språnget vid kristallisation för delkristallina och att högt tryck höjer Tg och Tm. Viskositet och MFI ingår inte i diagrammet.$kuggfri$, null, 294, false, $kuggfri$cdb320bf8$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Tryck, volym och temperatur (pressure-volume-temperature).","correct":true},{"text":"De beskriver sambandet mellan en polymers densitet och temperatur, också i smält tillstånd.","correct":true},{"text":"Tryck, viskositet och temperatur.","correct":false},{"text":"De kvantifierar smältflödesindex.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fö19-21, fråga 5; Canvas, MTT085 Polymeric materials L4-5, s. 9; Canvas, 2025 MTT085 Fö19, s. 8-9$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('4a826b1c-ad2d-5df0-bd92-2ca55ddee175', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$quiz-extrusion-extrudering$kuggfri$, $kuggfri$Vilka påståenden om extrudering som process stämmer?$kuggfri$, $kuggfri$Principen för extrudering är att en smälta pumpas genom ett munstycke, och trycket för det byggs upp i skruvens doseringszon. Med film casting som sekundär formning blir det tunna filmer, t.ex. för förpackningar. Granulatet smälter först i cylinderns uppvärmda del, inte i tratten. Att formen stängs är första steget i formsprutningscykeln; vid extrudering finns ingen sluten form, utan smältan pressas ut genom munstycket och ger produkter av i princip kontinuerlig längd.$kuggfri$, null, 295, false, $kuggfri$c4b55d06d$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Den bygger på att trycket byggs upp i doseringszonen så att polymeren pressas genom munstycket.","correct":true},{"text":"Den kan användas för att tillverka tunna förpackningsfilmer.","correct":true},{"text":"Den kräver att granulatet smälts i tratten.","correct":false},{"text":"Den börjar med att formen stängs.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fö19-21, fråga 6; Canvas, MTT085 Polymeric materials L4-5, s. 2-3; Canvas, MTT085 Polymeric materials L4-5, s. 5-6; Canvas, MTT085 Tutorials-Part 3-5, s. 2$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('8ba4e981-d1fa-524b-9df1-668bb91259bc', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$quiz-injection-moulding-formsprutning$kuggfri$, $kuggfri$Vilka påståenden om formsprutning stämmer?$kuggfri$, $kuggfri$Formsprutning passar för massproducerade detaljer med komplexa former och är mer mångsidig än extrudering i fråga om vilka produkter som kan tillverkas, så den är inte begränsad till konstant godstjocklek. Flash uppstår när eftertrycket är för högt: trycket i kaviteten överstiger maskinens låskraft och smälta tränger ut i formens delningsplan. För lågt eftertryck ger i stället för stor krympning.$kuggfri$, null, 296, false, $kuggfri$c871bdffc$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Den arbetar enligt formsprutningscykeln.","correct":true},{"text":"Den kan bara tillverka produkter med konstant godstjocklek.","correct":false},{"text":"Den kan ge flash om eftertrycket är för lågt.","correct":false},{"text":"Maskinen har en insprutningsenhet.","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fö19-21, fråga 7; Canvas, MTT085 Polymeric materials L4-5, s. 1; Canvas, MTT085 Polymeric materials L4-5, s. 6; Canvas, 05142_06b-4, s. 23; Canvas, 05142_06b-4, s. 26; Canvas, MTT085 Tutorials-Part 3-5, s. 2$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('d3c48a0d-1442-53e4-9724-ae8ba6ec8916', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$quiz-film-casting-filmcasting$kuggfri$, $kuggfri$Vilka påståenden om film casting stämmer?$kuggfri$, $kuggfri$Vid film casting extruderas smältan genom ett spaltmunstycke (slit die) och dras ut på en kyld vals (chill roll), som kyler filmen och ger den en dragkvot. Resultatet är tunna filmer, t.ex. för förpackningar. Sekundär formning (fiberspinning, film casting, filmblåsning) hör till extrudering, inte till formsprutning. Extrudatsvällning är en elastisk effekt vid munstycket, inte målet med processen.$kuggfri$, null, 297, false, $kuggfri$cbc4f5cc7$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Syftet är att framkalla extrudatsvällning (die swell).","correct":false},{"text":"Det är en sekundär formning efter extrudering.","correct":true},{"text":"Det är en sekundär formning efter formsprutning.","correct":false},{"text":"Det används för att tillverka tunna polymerfilmer.","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fö19-21, fråga 8; Canvas, MTT085 Polymeric materials L4-5, s. 4-5; Canvas, 2025 MTT085 Fö18, s. 23$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('2b28d687-5ce8-5556-92a1-b0643906b14e', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$quiz-the-components-of-a-mold-for-injection$kuggfri$, $kuggfri$Vilka delar ingår i en formsprutningsform?$kuggfri$, $kuggfri$Formen består av sprue och fördelningskanaler (runners), ingöt (gate), formkavitet, kylsystem (ibland) och utstötarsystem (oftast stift). Doseringszonen hör till extruderns skruv, inte till formen. Shish-kebab är en kristallstruktur som kan bildas i materialet när det skjuvas och kyls samtidigt, inte en del av formen.$kuggfri$, null, 298, false, $kuggfri$cab032590$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Skruvens doseringszon","correct":false},{"text":"Shish-kebab-kristallstrukturer","correct":false},{"text":"Utstötarstift (ejector pins)","correct":true},{"text":"I vissa fall ett kylsystem","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fö19-21, fråga 9; Canvas, MTT085 Polymeric materials L4-5, s. 7; Canvas, MTT085 Polymeric materials L4-5, s. 9; Canvas, 2025 MTT085 Fö18, s. 40$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('f8c227b2-db65-5784-b7e2-8f477cf8d5bb', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$quiz-during-solidification-under-stelning$kuggfri$, $kuggfri$Vilka påståenden om stelningen efter bearbetning stämmer?$kuggfri$, $kuggfri$Bearbetning kan låsa in strukturer som inte är i jämvikt, t.ex. flödesinducerad orientering och sträckning av kedjorna. Snabb avkylning sänker kristalliniteten eftersom mikrostrukturen fryses innan kedjorna hunnit ordna sig helt; på så sätt kan man till och med förhindra kristallisation (jfr PET-flaskor). Shish-kebab är kristallstrukturer och bildas i delkristallina polymerer (vanligast isotaktisk PP och PE), inte i amorfa. Vid avkylning stelnar polymeren genom glasövergång eller kristallisation; kedjorna bryts inte ned.$kuggfri$, null, 299, false, $kuggfri$c10345cce$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Polymerkedjornas orientering kan frysas in.","correct":true},{"text":"Kristallisationen kan frysas så att den inte hinner fullbordas.","correct":true},{"text":"Skjuvflöde kan ge shish-kebab-strukturer i amorfa polymerer.","correct":false},{"text":"Polymerer depolymeriseras alltid vid avkylning.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fö19-21, fråga 10; Canvas, MTT085 Polymeric materials L4-5, s. 9; Canvas, MTT085 Tutorials-Part 3-5, s. 2; Canvas, 2025 MTT085 Fö19, s. 6-9$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('8971c461-3c38-5d8e-b52e-a0c1dfa293ff', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-viskositet$kuggfri$, $kuggfri$Viskositet$kuggfri$, $kuggfri$En vätskas motstånd mot flöde. Newtons viskositetslag: $\sigma = \eta\dot{\gamma}$, dvs. skjuvspänningen $\sigma$ är proportionell mot skjuvhastigheten $\dot{\gamma}$, och proportionalitetskonstanten $\eta$ är (skjuv)viskositeten. Enheten är Pa·s. För en newtonsk vätska beror $\eta$ bara av temperatur och tryck; för en polymersmälta beror den också av skjuvhastigheten.$kuggfri$, null, 300, false, $kuggfri$c3b01942b$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 3, s. 1-3; Canvas, 2025 MTT085 Fö17, s. 8-10; Canvas, Tentamen Materialteknik med svar 2022-11-29, s. 7$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('ecb8e44e-6407-5172-9d6e-ce35d4458983', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-skjuvhastighet$kuggfri$, $kuggfri$Skjuvhastighet (shear rate)$kuggfri$, $kuggfri$Hur snabbt ett material deformeras i skjuvning, $\dot{\gamma} = \dfrac{d\gamma}{dt}$. I enkel skjuvning mellan två plattor på avståndet $h$, där den övre rör sig med hastigheten $v$ och den undre står still, är $\dot{\gamma} = v/h$. Enheten är 1/s. Man använder skjuvhastigheten i stället för skjuvtöjningen som mått på flödet, eftersom töjningen växer obegränsat så länge vätskan flyter.$kuggfri$, null, 301, false, $kuggfri$c493c375c$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 3, s. 1-2; Canvas, 2025 MTT085 Fö17, s. 7-9$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('907ee593-0311-5731-92e8-1121e01419e6', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-skjuvfortunning$kuggfri$, $kuggfri$Skjuvförtunning (shear thinning)$kuggfri$, $kuggfri$Att viskositeten hos en polymersmälta minskar när skjuvhastigheten ökar. Orsaken är att kedjorna i flödet sträcks, orienteras i flödesriktningen och trasslas ur (om molekylvikten är över intrasslingsmolekylvikten), så att de ger mindre motstånd mot flödet.$kuggfri$, null, 302, false, $kuggfri$c589a45c5$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 3, s. 5-6; Canvas, Tentamen Materialteknik mrd svar 2021-10-23 korrigerad, s. 1$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('a42848f6-caa7-5e79-9d33-da72a56b3491', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-svetslinje$kuggfri$, $kuggfri$Svetslinje (weld line)$kuggfri$, $kuggfri$Linjen i en formsprutad detalj där två eller flera flödesfronter möts, när detaljens form gör att smältflödet delas i kaviteten. Svetslinjen är en svag punkt i detaljen, så man måste tänka på var den hamnar. För låg insprutningstemperatur kan ge svaga svetslinjer.$kuggfri$, null, 303, false, $kuggfri$c065b813d$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 Polymeric materials L4-5, s. 8; Canvas, 2025 MTT085 Fö18, s. 41; Canvas, MTT085 Tutorials-Part 3-5, s. 2$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('b9f7d94a-a205-57bd-9934-eb944c3b2e83', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-eftertryck$kuggfri$, $kuggfri$Eftertryck (holding pressure)$kuggfri$, $kuggfri$Det tryck som hålls på smältan vid formsprutning efter att kaviteten fyllts, för att motverka krympningen när materialet stelnar. Eftertrycket hålls tills ingötet har stelnat; därefter fortsätter detaljen att kylas utan förhöjt tryck.$kuggfri$, null, 304, false, $kuggfri$caa723556$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 Polymeric materials L4-5, s. 6; Canvas, 05142_06b-4, s. 24; Canvas, Tentamen Materialteknik med svar 2013-08-20, s. 8$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('8849a43e-6bb3-5453-8c64-996ea88f8520', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-shish-kebab$kuggfri$, $kuggfri$Shish-kebab-struktur$kuggfri$, $kuggfri$En speciell kristallstruktur i delkristallina polymerer, vanligast i isotaktisk polypropen och polyeten: en fibrillär kärna (shish) som omväxlar med lameller av veckade kedjor (kebab). Den bildas när smältan skjuvas samtidigt som den kyls, t.ex. vid formsprutning, och ger betydligt bättre mekaniska egenskaper än motsvarande jämviktsstruktur med sfäruliter.$kuggfri$, null, 305, false, $kuggfri$c7e2a615f$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 Polymeric materials L4-5, s. 9; Canvas, 2025 MTT085 Fö19, s. 14$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('261f191d-6f28-52d6-8ccf-e39a7c9c2f9c', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-varfor-viskoelastisk-smalta$kuggfri$, $kuggfri$Varför är en polymersmälta viskoelastisk?$kuggfri$, $kuggfri$- **Elastisk del:** kedjorna kan sträckas av flödet men har en föredragen konformation som de återgår till när flödet upphör. De lagrar alltså energi under flödet.
- **Viskös del:** kedjorna glider förbi varandra, och friktionen mellan molekylerna ger det viskösa motståndet.

När flödet stoppas återtar kedjorna sin föredragna konformation men flyttar inte tillbaka till sina ursprungliga platser. Därför kan smältan flyta.$kuggfri$, null, 306, false, $kuggfri$c6902ebde$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 3, s. 4-5; Canvas, 2025 MTT085 Fö17, s. 24-25$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('34a893cf-36f4-5b18-ad33-6e1182628028', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-viskositetsfunktionens-omraden$kuggfri$, $kuggfri$Beskriv viskositetsfunktionen för en polymersmälta och vad kedjorna gör i varje område$kuggfri$, $kuggfri$Viskositet mot skjuvhastighet i log-log-skala, med tre områden:

1. **Nollskjuvviskositet** (platå vid låga skjuvhastigheter): spänningarna från flödet är i samma storleksordning som spänningarna från kedjornas termiska rörelse, så kedjorna behåller sin föredragna konformation. Nivån beror på material, molekylvikt och molekylviktsfördelning.
2. **Skjuvförtunnande område:** kedjorna sträcks, orienteras i flödesriktningen och trasslas ur, och viskositeten minskar med ökande skjuvhastighet.
3. **Oändlig-skjuv-viskositet** (övre platå): maximal sträckning, orientering och uttrassling är nådd, och viskositeten beror inte längre av skjuvhastigheten. Den är mycket svår att mäta för smältor och kan utelämnas i en skiss.$kuggfri$, null, 307, false, $kuggfri$c80389433$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 3, s. 5-6; Canvas, 2025 MTT085 Fö17, s. 19; Canvas, Svar Materialteknik 2018-10-27, s. 3$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('2d5cd0ac-8e00-5eff-b05e-17ff927b733d', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-extruderns-zoner$kuggfri$, $kuggfri$Vad händer med polymeren i enskruvsextruderns tre zoner?$kuggfri$, $kuggfri$Granulatet matas genom tratten in i cylindern.

1. **Inmatningszonen** (solids conveying zone): skruven transporterar och packar granulatet. Zonen kyls ofta så att granulatet inte smälter och sätter igen inloppet.
2. **Smält- eller övergångszonen** (transition zone): i cylinderns uppvärmda del smälter granulatet och homogeniseras.
3. **Doseringszonen** (metering zone): trycket byggs upp så att smältan pressas genom munstycket (die) i extruderns ände.$kuggfri$, null, 308, false, $kuggfri$cae5d6f88$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 Polymeric materials L4-5, s. 2-3; Canvas, 05142_06a-3, s. 7; Canvas, MTT085 Tutorials-Part 3-5, s. 2; Canvas, Tentamen Materialteknik mrd svar 2021-10-23 korrigerad, s. 1$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('4534df7f-7a28-56e1-9bb0-2fc70a4e4e49', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-formsprutningscykelns-steg$kuggfri$, $kuggfri$Beskriv formsprutningscykelns steg i ordning$kuggfri$, $kuggfri$1. Formen stängs (här börjar cykeln).
2. Insprutningsenheten förs fram och smältan sprutas in i kaviteten via sprue, fördelningskanaler och ingöt.
3. Kaviteten fylls och eftertryck läggs på för att motverka krympningen, tills ingötet har stelnat.
4. Insprutningsenheten dras tillbaka och skruven roterar och matar fram nästa skott.
5. Detaljen kyls i formen tills den är tillräckligt styv, sedan öppnas formen och detaljen stöts ut.

$t_{\text{cykel}} = t_{\text{stängning}} + t_{\text{kylning}} + t_{\text{utstötning}}$, där kyltiden är ungefär 80 % av cykeltiden.$kuggfri$, null, 309, false, $kuggfri$c795cd51f$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 Polymeric materials L4-5, s. 6-7; Canvas, 05142_06b-4, s. 24-25; Canvas, MTT085 Tutorials-Part 3-5, s. 2$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('921b5cc5-01cf-5808-be8c-fb9e39d08cca', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-kyltid-och-godstjocklek$kuggfri$, $kuggfri$Hur påverkar godstjockleken cykeltiden vid formsprutning, och varför?$kuggfri$, $kuggfri$Kyltiden dominerar cykeln (ungefär 80 %), och den ökar ungefär med kvadraten på godstjockleken. Dubbel tjocklek ger alltså ungefär fyra gånger så lång kyltid och därmed mycket längre cykel. Orsaken är plastens låga värmeledningsförmåga (låg termisk diffusivitet), som gör att värmen leds ut långsamt ur detaljen.$kuggfri$, null, 310, false, $kuggfri$c93da90b9$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 Tutorials-Part 3-5, s. 2-3; Canvas, 05142_06b-4, s. 25$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('7e6cf84b-614e-54e8-91ff-0e23ca36272c', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-filmblasning$kuggfri$, $kuggfri$Beskriv filmblåsning (film blowing)$kuggfri$, $kuggfri$Filmblåsning är en sekundär formning efter extrudering. Smältan pressas genom ett ringformat munstycke (blåshuvud) och bildar en slang. Luft blåses in genom munstyckets centrum och blåser upp slangen, som samtidigt dras ut, så att väggtjockleken minskar kraftigt. Filmen kyls av luft utifrån och stelnar innan den når klämvalsarna (nip rollers). Klämvalsarna pressar ihop filmen så att övertrycket i blåsan hålls kvar och drar filmen i axiell riktning. Till sist rullas filmen upp.$kuggfri$, null, 311, false, $kuggfri$c972c79eb$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 Polymeric materials L4-5, s. 5-6; Canvas, MTT085 Tutorials-Part 3-5, s. 2; Canvas, Tentamen Materialteknik med svar 2013-08-20, s. 8$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('3b36715f-d0df-5721-a008-d3aa3577e30a', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-sf-smalta-amorf$kuggfri$, $kuggfri$I smält tillstånd är alla polymerer amorfa, även de som är delkristallina i fast tillstånd.$kuggfri$, $kuggfri$Sant. Oavsett om polymeren är amorf eller delkristallin i fast tillstånd har den i smältan en oordnad, slumpmässig molekylorientering, dvs. den är amorf.$kuggfri$, null, 312, false, $kuggfri$c5e7ad2d7$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 3, s. 4; Canvas, 2025 MTT085 Fö17, s. 17; Canvas, 2025 MTT085 Fö17, s. 28$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('48c745ee-202c-5fda-8505-ffe6927a29c4', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-sf-viskositet-temperatur$kuggfri$, $kuggfri$Viskositeten hos en polymersmälta ökar när temperaturen höjs.$kuggfri$, $kuggfri$Falskt. Viskositeten minskar när temperaturen höjs ($\eta \propto 1/T$ på föreläsningsbilden); viskositetskurvorna för t.ex. ABS, PC och PA6 ligger lägre ju högre temperaturen är.$kuggfri$, null, 313, false, $kuggfri$cb0a4ba14$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 3, s. 6; Canvas, 2024 MTT085 Fö17, s. 27; Canvas, 2025 MTT085 Fö17, s. 22$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('d03c3a35-1950-5430-83fa-cc90490bcbdd', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-sf-viskositet-molekylvikt$kuggfri$, $kuggfri$Vid i övrigt lika förhållanden har en polymersmälta med högre molekylvikt högre viskositet.$kuggfri$, $kuggfri$Sant. Viskositeten ökar med molekylvikten ($\eta \propto M_w$ på föreläsningsbilden). Omvänt ger lägre molekylvikt lägre viskositet, så att materialet blir lättare att bearbeta. Fyllmedel höjer också viskositeten.$kuggfri$, null, 314, false, $kuggfri$cfbdc04b4$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2024 MTT085 Fö17, s. 27; Canvas, MTT085 Tutorials-Part 3-5, s. 3$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('f1635160-044a-5c63-9c14-91995e171323', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-sf-mfi-temperatur$kuggfri$, $kuggfri$MFI för en polymer ökar om den mäts vid högre temperatur.$kuggfri$, $kuggfri$Sant. Viskositeten sjunker när temperaturen höjs, och MFI har omvänd innebörd mot viskositeten: med samma vikt pressas mer smälta ut på 10 minuter, så MFI blir högre.$kuggfri$, null, 315, false, $kuggfri$c07971553$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 3, s. 6-7; Canvas, 2024 MTT085 Fö17, s. 27; Canvas, Tentamen MTT085 25-01, s. 10$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('1660b2c2-dea6-5274-a0ec-ca40f97ac3ea', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-sf-tryck-inmatningszon$kuggfri$, $kuggfri$I en enskruvsextruder är trycket högst i inmatningszonen vid tratten.$kuggfri$, $kuggfri$Falskt. Trycket byggs upp i doseringszonen (metering zone) och är högst närmast munstycket, där det behövs för att pressa smältan genom munstycket. Inmatningszonen transporterar granulatet från tratten.$kuggfri$, null, 316, false, $kuggfri$cd9b274c0$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 Polymeric materials L4-5, s. 2-4; Canvas, Svarsförslag Tentamen MTT085 24-01, s. 3$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('7b408caf-8075-539d-8862-5c8e7befefe9', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-sf-nollskjuv-orientering$kuggfri$, $kuggfri$Vid låga skjuvhastigheter, i nollskjuvområdet, orienteras polymerkedjorna kraftigt i flödesriktningen.$kuggfri$, $kuggfri$Falskt. Vid små eller långsamma deformationer hinner kedjornas termiska rörelse återställa deras föredragna konformation, så orienteringen ändras inte och viskositeten är konstant. Kedjorna orienteras först vid högre skjuvhastigheter, i det skjuvförtunnande området.$kuggfri$, null, 317, false, $kuggfri$c0e007f7f$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 3, s. 6; Canvas, 2025 MTT085 Fö17, s. 28; Canvas, Tentamen Materialteknik med svar 2020-10-24, s. 6$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('93cc2ecc-f95c-5da6-87a4-178f632fbf77', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-sf-hog-insprutningstemperatur$kuggfri$, $kuggfri$För hög insprutningstemperatur vid formsprutning kan ge termisk nedbrytning av polymeren.$kuggfri$, $kuggfri$Sant. Smälttemperaturen begränsas uppåt av termisk nedbrytning av materialet och nedåt av kortskott (ofylld kavitet) och svaga svetslinjer.$kuggfri$, null, 318, false, $kuggfri$c516dcaa3$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Tentamen Materialteknik med svar 2022-11-29, s. 7; Canvas, 05142_06b-4, s. 26; Canvas, MTT085 Tutorials-Part 3-5, s. 2$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('422cab47-9609-501a-abfd-d72dee3f8afd', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-sf-delkristallin-krymper-mer$kuggfri$, $kuggfri$Delkristallina termoplaster krymper mer än amorfa när de stelnar.$kuggfri$, $kuggfri$Sant. Amorfa termoplaster förtätas minst vid stelning, eftersom kedjorna inte kan ordna sig i regelbundna, tätpackade kristaller. Delkristallina polymerer krymper mer; vid formsprutning motverkas det delvis med längre eftertryckstid och högre tryck.$kuggfri$, null, 319, false, $kuggfri$cd389ad71$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fö19, s. 7; Canvas, MTT085 Tutorials-Part 3-5, s. 2$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('62ca1f80-94d1-5a84-a887-ce23591effb4', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-sf-snabbkylning-kristallinitet$kuggfri$, $kuggfri$Snabbare avkylning ger en högre kristallinitetsgrad i en delkristallin polymer.$kuggfri$, $kuggfri$Falskt. Snabb avkylning sänker kristalliniteten, eftersom mikrostrukturen fryses innan kedjorna hunnit ordna sig helt i kristaller.$kuggfri$, null, 320, false, $kuggfri$c5c9ecc4c$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fö19, s. 9; Canvas, MTT085 Tutorials-Part 3-5, s. 2$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('917dfb3e-f36e-532d-bad9-b4133e482149', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-alt-viskositet-enhet$kuggfri$, $kuggfri$Vilken enhet har viskositet?$kuggfri$, $kuggfri$Ur $\sigma = \eta\dot{\gamma}$ fås $\eta = \sigma/\dot{\gamma}$, dvs. Pa delat med 1/s, alltså Pa·s. 1/s är enheten för skjuvhastighet, Pa för spänning och g/10 min för smältflödesindex (MFI).$kuggfri$, null, 321, false, $kuggfri$c8027fa0c$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Pa·s","correct":true},{"text":"1/s","correct":false},{"text":"g/10 min","correct":false},{"text":"Pa","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fö17, s. 9; Canvas, MTT085 PM 3, s. 2; Canvas, Tentamen Materialteknik med svar 2022-11-29, s. 7$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('a934a282-34fb-55d7-9cae-8996eedaf809', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-alt-mfi-jamforelse$kuggfri$, $kuggfri$Två polymerer har MFI 2 g/10 min (A) respektive 13 g/10 min (B), mätta enligt samma standard. Vilka påståenden stämmer?$kuggfri$, $kuggfri$MFI är antalet gram som pressas ut under 10 minuter med en standardiserad vikt vid standardiserad temperatur. Polymer B gav 13 g och A bara 2 g, så A är trögast. MFI har omvänd innebörd mot viskositeten: högre MFI betyder lägre viskositet. MFI är ett flödesmått och säger inget om brottöjning.$kuggfri$, null, 322, false, $kuggfri$c90d019a8$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Polymer A har högre viskositet än polymer B.","correct":true},{"text":"Med samma vikt och temperatur pressades mer av polymer B ut på 10 minuter.","correct":true},{"text":"Polymer B har högre viskositet, eftersom högre MFI betyder trögare smälta.","correct":false},{"text":"MFI-värdena anger polymerernas brottöjning.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 PM 3, s. 7; Canvas, Tentamen Materialteknik med svar 2022-11-29, s. 7$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('380e3145-de95-541b-92cf-c2fcd357d4f5', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-alt-produkt-extrudering$kuggfri$, $kuggfri$Vilka produkter tillverkas typiskt genom extrudering, med eller utan sekundär formning?$kuggfri$, $kuggfri$Extrudering ger produkter med en viss tvärsnittsprofil, t.ex. rör, slangar, filament, profiler och filmer; med film casting eller filmblåsning blir det tunn film. Tryckknappen i en kulspetspenna formsprutas (tentan 2016-10), och massproducerade detaljer med komplex form är just det formsprutning passar för.$kuggfri$, null, 323, false, $kuggfri$cdd8096b8$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Rör","correct":true},{"text":"Tunn förpackningsfilm","correct":true},{"text":"Tryckknappen i en kulspetspenna","correct":false},{"text":"Massproducerade detaljer med komplex tredimensionell form","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 Polymeric materials L4-5, s. 4-5; Canvas, Tentamen Materialteknik med svar 2016-10-29, s. 7; Canvas, 05142_06b-4, s. 23$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('7cec6ed3-bf7b-5bb5-b7fc-2dfe224b6bd8', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-alt-formsprutningsmaskinens-enheter$kuggfri$, $kuggfri$Vilka är huvudenheter i en formsprutningsmaskin?$kuggfri$, $kuggfri$Enligt föreläsningsanteckningarna har en formsprutningsmaskin fyra huvudenheter: insprutningsenhet, plasticeringsenhet (en sorts enskruvsextruder), form och stängningsenhet. Sekundär formning (fiberspinning, film casting, filmblåsning) hör till extrudering, och kalandrering är en egen bearbetningsmetod.$kuggfri$, null, 324, false, $kuggfri$ccae13423$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Plasticeringsenheten","correct":true},{"text":"Formen","correct":true},{"text":"Enheten för sekundär formning","correct":false},{"text":"Kalandreringsenheten","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 Polymeric materials L4-5, s. 6; Canvas, MTT085 Tutorials-Part 3-5, s. 1; Canvas, Svarsförslag Tentamen MTT085 24-10, s. 19; Canvas, 2025 MTT085 Fö17, s. 22$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('5ad366de-e6ff-517a-8a11-bef8a95b1bad', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-alt-processfonster$kuggfri$, $kuggfri$Vilka par av processfel och orsak stämmer för formsprutning?$kuggfri$, $kuggfri$Processfönstret (molding diagram) begränsas av smälttemperatur och eftertryck. För låg temperatur ger kortskott och svaga svetslinjer, för hög temperatur ger termisk nedbrytning. För lågt eftertryck ger för stor krympning, för högt eftertryck ger flash: trycket i kaviteten överstiger låskraften och smälta tränger ut i formens delningsplan.$kuggfri$, null, 325, false, $kuggfri$c0a49b9b6$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"För låg smälttemperatur ger kortskott (ofylld kavitet).","correct":true},{"text":"För högt eftertryck ger flash.","correct":true},{"text":"För låg smälttemperatur ger termisk nedbrytning.","correct":false},{"text":"För lågt eftertryck ger flash.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 05142_06b-4, s. 26; Canvas, MTT085 Tutorials-Part 3-5, s. 2$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('3c9acbe1-5f5c-5956-8e14-ab3926adc59d', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-alt-formens-kanaler$kuggfri$, $kuggfri$Vilka påståenden om formsprutningsformens kanaler stämmer?$kuggfri$, $kuggfri$Smältan går från cylindern genom sprue och fördelas via fördelningskanalerna till ingöten (gates), som leder in i kaviteterna. Ingötet är en liten öppning jämfört med detaljen och kanalerna och stelnar därför före detaljen. Har formen bara en kavitet fungerar sprue själv som ingöt (sprue gate).$kuggfri$, null, 326, false, $kuggfri$c8216c565$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Sprue förbinder cylindern med formen.","correct":true},{"text":"Fördelningskanalerna (runners) fördelar smältan till kaviteterna via ingöten.","correct":true},{"text":"Ingötet är formens största kanal och stelnar därför sist.","correct":false},{"text":"Om formen bara har en kavitet behövs ingen sprue.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 Polymeric materials L4-5, s. 6-7; Canvas, 2025 MTT085 Fö18, s. 40$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('82235d62-1ecf-54bb-8927-81a7102bec0e', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-alt-orienterade-fibrer$kuggfri$, $kuggfri$Hur tillverkar man tunna polymerfibrer med starkt orienterad molekylstruktur?$kuggfri$, $kuggfri$Vid fiberspinning extruderas smältan genom ett munstycke med ett eller flera hål och dras ut av valspar med mycket hög töjningshastighet, vilket ger högre molekylorientering än skjuvflöde. Film casting ger tunn film, inte fibrer. Formsprutning och formpressning ger formade detaljer, och formpressning sker vid låga skjuvhastigheter och ger lite orientering.$kuggfri$, null, 327, false, $kuggfri$cfe3bcfcf$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Extrudering med fiberspinning som sekundär formning","correct":true},{"text":"Extrudering med film casting som sekundär formning","correct":false},{"text":"Formsprutning med långt eftertryck","correct":false},{"text":"Formpressning (compression molding)","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Svar Materialteknik 2019-10-26, s. 4; Canvas, MTT085 Polymeric materials L4-5, s. 4-5; Canvas, MTT085 PM 3, s. 6$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('b77d8ccb-a5d7-53a1-87f2-1f099e376cec', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '5e84b0fc-3b12-5447-b13d-c1e3ca6a4e68', $kuggfri$reo-alt-tryck-overgangstemperatur$kuggfri$, $kuggfri$Hur påverkar högt tryck under bearbetning övergångstemperaturerna?$kuggfri$, $kuggfri$Högt tryck pressar ihop molekylerna, så det krävs mer termisk energi för att frigöra dem så att de kan flyta. Därför höjs Tg för amorfa och Tm för delkristallina termoplaster, vilket syns i pVT-diagrammen.$kuggfri$, null, 328, false, $kuggfri$cc29a7830$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Glasövergångstemperaturen hos en amorf termoplast höjs.","correct":true},{"text":"Smälttemperaturen hos en delkristallin termoplast höjs.","correct":true},{"text":"Smälttemperaturen hos en delkristallin termoplast sänks.","correct":false},{"text":"Trycket påverkar bara viskositeten, inte övergångstemperaturerna.","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 Polymeric materials L4-5, s. 9; Canvas, Svar Materialteknik 2019-10-26, s. 4$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('0fcfdbc7-b726-5552-9801-23674c214d53', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$quiz-creep-krypning$kuggfri$, $kuggfri$Vad stämmer om krypning (creep) hos polymerer?$kuggfri$, $kuggfri$I ett krypprov hålls spänningen konstant och töjningen mäts över tiden. Konstant töjning med uppmätt spänning är i stället ett relaxationsprov. Snitt genom krypkurvorna vid konstant tid ger isokrona spännings-töjningskurvor. Slagprov är korttidsprov, där polymerer oftast kan betraktas som rent elastiska, medan krypprov är långtidsprov.$kuggfri$, null, 329, false, $kuggfri$c01b2dc62$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Ett krypprov görs med konstant töjning","correct":false},{"text":"Ett krypprov görs med konstant spänning","correct":true},{"text":"Krypkurvor kan användas för att konstruera isokrona diagram","correct":true},{"text":"Krypning är ett mått på slagseghet","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Quiz Polymeric materials Fo19-21, fråga 4; Canvas, 2025 MTT085 Fo20, s. 15, 20; Canvas, 05142_09 (Osswald kap. 9), s. 5, 39; Canvas, MTT085 Polymeric materials L6, s. 2$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('48538114-1b4a-54aa-bc3a-b7b0a1029f33', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-sprott-brott-nar$kuggfri$, $kuggfri$När får polymerer sprött brott i ett kortvarigt dragprov?$kuggfri$, $kuggfri$Sprött brott uppträder i regel hos termoplaster under Tg och hos högt tvärbundna polymerer, vid mycket små töjningar (kring 1 % eller mindre). Delkristallina termoplaster mellan Tg och Tm får i stället duktilt brott. En amorf termoplast över Tg har förlorat sin styvhet och får inte sprött brott i ett kortvarigt dragprov; sprött brott över Tg kan däremot uppträda vid krypbrott och utmattning.$kuggfri$, null, 330, false, $kuggfri$cba89b160$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Termoplaster under sitt Tg","correct":true},{"text":"Högt tvärbundna polymerer (härdplaster)","correct":true},{"text":"Delkristallina termoplaster mellan Tg och Tm","correct":false},{"text":"Amorfa termoplaster över sitt Tg","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fo21, s. 7; Canvas, 05142_10 (Osswald kap. 10), s. 8; Canvas, MTT085 Polymeric materials L6, s. 7; Canvas, Tentamen Materialteknik med svar 2020-10-24, s. 9$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('31e47fc5-fdbc-5118-b525-cadf3e61f1c5', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-duktilt-brott-vilken$kuggfri$, $kuggfri$Vilken polymer bör få duktilt brott i ett kortvarigt dragprov?$kuggfri$, $kuggfri$Duktilt brott förutsätter flera längdskalor i materialet (sfäruliter, lameller, amorfa områden), och utan mjukgörare gäller det bara delkristallina termoplaster mellan Tg och Tm. Under Tg får både amorfa och delkristallina termoplaster sprött brott, och högt tvärbundna härdplaster är spröda.$kuggfri$, null, 331, false, $kuggfri$c7f526428$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"En delkristallin termoplast mellan Tg och Tm","correct":true},{"text":"En amorf termoplast under Tg","correct":false},{"text":"En delkristallin termoplast under Tg","correct":false},{"text":"En härdplast","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 05142_10 (Osswald kap. 10), s. 12; Canvas, MTT085 Polymeric materials L6, s. 7–8; Canvas, 2025 MTT085 Fo21, s. 10; Canvas, Tentamen MTT085 25-01, s. 13$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('1df13097-698e-544b-a022-d227205814e4', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-krackelering-vad-stammer$kuggfri$, $kuggfri$Vad stämmer om krackelering (crazing) i en amorf polymer?$kuggfri$, $kuggfri$Krazer är mikrosprickor som bildas vinkelrätt mot den största huvudspänningen, med start vid spänningskoncentrationer som repor, dammpartiklar eller inhomogeniteter i materialet. De försämrar klarheten och reflekterar ljus, vilket gör dem tydliga i transparenta material.$kuggfri$, null, 332, false, $kuggfri$c1de5e953$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Krazerna bildas i plan vinkelräta mot den största huvudspänningen","correct":true},{"text":"Krazerna kärnbildas vid spänningskoncentrationer som repor och dammpartiklar","correct":true},{"text":"Krazerna bildas i plan parallella med den största huvudspänningen","correct":false},{"text":"Krazerna påverkar inte materialets klarhet","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fo21, s. 9; Canvas, 05142_10 (Osswald kap. 10), s. 10$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('e5f519e8-a7c5-550a-8049-88a9eaecf7ec', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-duktilt-brott-ordning$kuggfri$, $kuggfri$I vilken ordning sker händelserna när en delkristallin termoplast, t.ex. PP, dras till brott vid rumstemperatur?$kuggfri$, $kuggfri$Först är deformationen linjärelastisk och reversibel (för PP upp till ca 0,5 %). Sedan blir kurvan olinjär när mikrosprickor bildas i gränsytorna mellan sfäruliterna, som syns som stress whitening. Vid spänningsmaximum nås flytpunkten, spänningen sjunker och halsbildning följer, med en lång kalldragning där sfärulitstrukturen deformeras och bryts upp. Linjärt område, krackelering och sprött brott vid ca 1 % töjning beskriver i stället en amorf termoplast under Tg.$kuggfri$, null, 333, false, $kuggfri$c1129a921$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Linjärelastiskt område, mikrosprickor mellan sfäruliterna (stress whitening), flytpunkt, halsbildning och kalldragning","correct":true},{"text":"Halsbildning, stress whitening, linjärelastiskt område, flytpunkt","correct":false},{"text":"Linjärelastiskt område, krackelering, sprött brott vid ca 1 % töjning","correct":false},{"text":"Kalldragning, flytpunkt, linjärelastiskt område, stress whitening","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fo21, s. 10–13; Canvas, 05142_10 (Osswald kap. 10), s. 12–14$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('5b693aa2-aded-52ff-9ffe-6eec5c217160', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-stress-whitening-var$kuggfri$, $kuggfri$Var bildas de mikrosprickor som ger stress whitening i en delkristallin polymer?$kuggfri$, $kuggfri$Sfäruliterna är den största längdskalan i en delkristallin polymer, och den största längdskalan går sönder först. Mikrosprickorna bildas därför i gränsytorna mellan sfäruliterna och blir ungefär lika långa som sfäruliterna. När de blir synliga kallas de stress whitening. Tvärbindningspunkter finns inte i en termoplast.$kuggfri$, null, 334, false, $kuggfri$c0009ad60$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"I gränsytorna mellan sfäruliterna","correct":true},{"text":"Inuti de enskilda kristallina lamellerna","correct":false},{"text":"Längs de kovalenta bindningarna i huvudkedjan","correct":false},{"text":"Vid tvärbindningspunkterna mellan kedjorna","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fo21, s. 12; Canvas, 05142_10 (Osswald kap. 10), s. 12–14; Canvas, MTT085 Polymeric materials L6, s. 8$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('e7603fd5-950e-502b-9632-5dcd5c498ae7', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-isokrona-kurvor-konstruktion$kuggfri$, $kuggfri$Hur konstrueras isokrona spännings-töjningskurvor ur krypdata?$kuggfri$, $kuggfri$Isokron betyder "samma tid": varje kurva gäller en viss belastningstid, t.ex. 1 dag eller 1 år. Snitt vid konstant töjning med spänningen mot tiden ger i stället isometriska kurvor. Slagprov är korttidsprov och ger inga krypdata.$kuggfri$, null, 335, false, $kuggfri$cd694bec5$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Genom snitt i krypkurvorna vid konstant tid, med spänningen plottad mot töjningen","correct":true},{"text":"Genom snitt i krypkurvorna vid konstant töjning, med spänningen plottad mot tiden","correct":false},{"text":"Genom snitt vid konstant spänning, med töjningen plottad mot temperaturen","correct":false},{"text":"Genom slagprov vid olika temperaturer","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fo20, s. 20; Canvas, 05142_09 (Osswald kap. 9), s. 39$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('a812b307-2d5f-5912-b9dc-8e3c0f911a1b', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-kryp-rent-viskost-svar$kuggfri$, $kuggfri$Vilket svar ger en rent viskös vätska i ett krypprov med konstant spänning σ₀?$kuggfri$, $kuggfri$En rent viskös vätska följer Newtons viskositetslag, så töjningen blir $\gamma(t) = \dfrac{\sigma_0}{\eta}\,t$. En ögonblicklig töjning som sedan är konstant är det rent elastiska svaret (Hooke). En elastisk start som sedan går mot ett gränsvärde är det fastfaslika viskoelastiska svaret.$kuggfri$, null, 336, false, $kuggfri$c52f35e98$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Töjningen växer linjärt med tiden, med lutningen σ₀/η","correct":true},{"text":"En ögonblicklig töjning som sedan är konstant","correct":false},{"text":"En ögonblicklig elastisk töjning som sedan närmar sig ett gränsvärde","correct":false},{"text":"Ingen töjning alls","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fo20, s. 16; Canvas, MTT085 Polymeric materials L6, s. 5$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('9b19d47b-61e1-53e0-bdba-7f0039c09a5c', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-kryp-aterhamtning$kuggfri$, $kuggfri$Vad händer när krypspänningen tas bort från ett viskoelastiskt material (återhämtning)?$kuggfri$, $kuggfri$Den töjning som återgår (återhämtningstöjningen) visar hur mycket elastisk energi som lagrades i strukturen. Resten återgår inte, eftersom kedjor som har glidit förbi varandra stannar i sina nya lägen; det är den viskösa förlusten. Att all töjning återgår gäller bara ett rent elastiskt material.$kuggfri$, null, 337, false, $kuggfri$c75bf3446$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"En del av töjningen återgår snabbt, men en kvarstående töjning blir kvar","correct":true},{"text":"All töjning återgår direkt","correct":false},{"text":"Töjningen fortsätter att öka i samma takt som under belastningen","correct":false},{"text":"Töjningen blir negativ","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 Polymeric materials L6, s. 5; Canvas, 2025 MTT085 Fo20, s. 17$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('0592f1cd-14a4-5862-b005-39f588f8dd2a', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-var-star-polymerer-ut$kuggfri$, $kuggfri$Inom vilka områden sticker polymera material ut?$kuggfri$, $kuggfri$Polymerer och polymerkompositer har goda mekaniska egenskaper i förhållande till densiteten och är därför nyckeln till lättviktskonstruktion. Eftersom de är viskoelastiska omvandlas en del av vibrationerna till viskösa förluster, vilket ger dämpning. De är också termiskt och elektriskt isolerande; elektrisk ledningsförmåga kräver ledande fyllmedel. Jämfört med metaller tål polymerer lägre temperaturer, och användningstemperaturen är ett av de viktigaste kriterierna vid val av polymer.$kuggfri$, null, 338, false, $kuggfri$c482780f0$kuggfri$, $kuggfri$alternativ$kuggfri$, $kuggfri$[{"text":"Lättviktskonstruktion (höga mekaniska egenskaper i förhållande till densiteten)","correct":true},{"text":"Vibrationsdämpning","correct":true},{"text":"Hög användningstemperatur","correct":false},{"text":"Hög elektrisk ledningsförmåga utan tillsatser","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 Polymeric materials L6, s. 1; Canvas, 2025 MTT085 Fo20, s. 4; Canvas, 2025 MTT085 Fo16, s. 20; Canvas, MTT085-Turorials-Part12, s. 4$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('ec7e3384-0c39-50d6-a088-147c77d5b244', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-krazer-langsam-deformation$kuggfri$, $kuggfri$Vid hög deformationshastighet blir krazerna stora och bildas tidigt under belastningen.$kuggfri$, $kuggfri$Det är tvärtom. Krackeleringen beror på deformationshastigheten: vid hög deformationshastighet blir krazerna små och bildas strax före brottet, eller inte alls. Vid långsam deformation blir de stora och uppträder tidigt under belastningen.$kuggfri$, null, 339, false, $kuggfri$c2f18c76f$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fo21, s. 9; Canvas, 05142_10 (Osswald kap. 10), s. 10; Canvas, MTT085 Polymeric materials L6, s. 8$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('8e08644d-ccd3-5487-9cfd-30640aa0ffd1', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-krazer-fibriller$kuggfri$, $kuggfri$Krazer är mindre farliga än riktiga sprickor, eftersom krazernas gränsytor hålls ihop av lastbärande fibriller.$kuggfri$, $kuggfri$Krazerna är sammankopplade av lastbärande fibriller och är därför mindre farliga än verkliga sprickor. De är ändå en synlig varning: i transparenta detaljer syns de eftersom de försämrar klarheten och reflekterar ljus.$kuggfri$, null, 340, false, $kuggfri$ca1553116$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fo21, s. 9; Canvas, 05142_10 (Osswald kap. 10), s. 10$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('6d0845be-44e8-54fb-bd6e-1dd179d9ce01', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-isometriska-kurvor$kuggfri$, $kuggfri$Isometriska kurvor fås genom snitt i krypkurvorna vid konstant tid, med spänningen plottad mot töjningen.$kuggfri$, $kuggfri$Det beskriver isokrona kurvor ("samma tid"). Isometriska kurvor ("samma töjning") fås genom snitt i krypkurvorna vid konstant töjning, med spänningen plottad mot tiden. De liknar resultatet av ett relaxationsprov.$kuggfri$, null, 341, false, $kuggfri$c24a68333$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":false},{"text":"Falskt","correct":true}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 05142_09 (Osswald kap. 9), s. 39; Canvas, 2025 MTT085 Fo20, s. 20$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('2761935f-c635-56ab-8132-f0d63d2a67bf', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-elastomer-reversibel$kuggfri$, $kuggfri$Deformationen hos en tvärbunden elastomer är reversibel så länge inga tvärbindningar bryts.$kuggfri$, $kuggfri$Tvärbindningarna gör att en elastomer klarar mycket stora deformationer (gummielasticitet). Eftersom elastomerer bara är glest tvärbundna kan stora delar av kedjorna sträckas ut, och deformationen går tillbaka så länge tvärbindningarna är intakta.$kuggfri$, null, 342, false, $kuggfri$ccc0ce475$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fo21, s. 15; Canvas, MTT085 PM 1, s. 10$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('86d41b2b-69c9-5ff6-abe2-77ab1a036969', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-sprott-over-tg-kryp-utmattning$kuggfri$, $kuggfri$Sprött brott hos polymerer kan uppträda även över Tg, vid krypbrott och utmattning.$kuggfri$, $kuggfri$Sprött brott i ett kortvarigt dragprov gäller termoplaster under Tg och högt tvärbundna polymerer. I krypbrotts- och utmattningsprov kan sprött brott uppträda även vid temperaturer över Tg.$kuggfri$, null, 343, false, $kuggfri$cf36d501c$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fo21, s. 7; Canvas, 05142_10 (Osswald kap. 10), s. 8$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('881008db-c1c6-5ba2-a824-d0f7fe032b79', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-slagprov-elastiskt-langtid-viskoelastiskt$kuggfri$, $kuggfri$I slagprov kan polymerer oftast betraktas som rent elastiska, medan de i långtidsprov som krypprov beter sig viskoelastiskt.$kuggfri$, $kuggfri$Polymerers beteende är tidsberoende. Vid korta tidsskalor (slagprov) beter de sig i regel som rent elastiska material, vid långa tidsskalor (kryp) är beteendet tydligt viskoelastiskt. Svårast att bedöma är tidsskalor i samma storleksordning som ett vanligt dragprov.$kuggfri$, null, 344, false, $kuggfri$c76b481e8$kuggfri$, $kuggfri$sant-falskt$kuggfri$, $kuggfri$[{"text":"Sant","correct":true},{"text":"Falskt","correct":false}]$kuggfri$::jsonb, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 Polymeric materials L6, s. 2$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('a42e6fe5-e420-5149-a836-d71f6ac183c9', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-begrepp-krypmodul$kuggfri$, $kuggfri$Krypmodul$kuggfri$, $kuggfri$Den pålagda konstanta spänningen delad med den tidsberoende töjningen i ett krypprov: $E_c = \dfrac{\sigma_0}{\varepsilon(t)}$. Krypmodulen minskar alltså med tiden. I skjuvning motsvaras den av skjuvkrypmodulen $G_c = \sigma_0/\gamma(t)$.$kuggfri$, null, 345, false, $kuggfri$c0d994e56$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fo20, s. 15; Canvas, 05142_09 (Osswald kap. 9), s. 37$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('3fe6e068-2291-5e5d-8ead-8d3dc0798d66', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-begrepp-deborahtal$kuggfri$, $kuggfri$Deborahtal (Deborah number)$kuggfri$, $kuggfri$Kvoten mellan materialets karakteristiska tidsskala och observationens tidsskala: $De = \dfrac{\text{materialets tidsskala}}{\text{observationstiden}}$. När De går mot 0 beter sig materialet som en rent viskös vätska, när De går mot oändligheten som ett rent elastiskt fast material. Däremellan är det viskoelastiskt ("everything flows", jämför beckdroppsförsöket).$kuggfri$, null, 346, false, $kuggfri$c24b5d8d6$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fo20, s. 13$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('58e13724-a3e0-53ae-9469-3e98913340ac', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-begrepp-halsbildning$kuggfri$, $kuggfri$Halsbildning (necking)$kuggfri$, $kuggfri$En lokal minskning av tvärsnittsarean som följer efter flytpunkten när en delkristallin polymer dras. Därefter följer en lång kalldragning där sfärulitstrukturen först deformeras och sedan bryts upp, så att starkt orienterade områden bildas.$kuggfri$, null, 347, false, $kuggfri$cd55afe62$kuggfri$, $kuggfri$begrepp$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fo21, s. 13; Canvas, 05142_10 (Osswald kap. 10), s. 14$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('e1a34429-b82c-5fbd-9932-0896ac415549', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-amorf-dragprovskurva$kuggfri$, $kuggfri$Beskriv den typiska spännings-töjningskurvan för en amorf termoplast vid rumstemperatur (under Tg) i ett kortvarigt dragprov.$kuggfri$, $kuggfri$Sprött brott vid mycket små töjningar, kring 1 % eller mindre (t.ex. polystyren).

1. Kurvan är först linjär och deformationen reversibel.
2. Strax före brottet bildas mikrosprickor, krazer (crazing), vinkelrätt mot den största huvudspänningen. Det är de som gör att kurvan slutar vara linjär, och därefter brister provet.$kuggfri$, null, 348, false, $kuggfri$c5d543bda$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, Tentamen Materialteknik mrd svar 2021-10-23 korrigerad, uppgift 9a; Canvas, 2025 MTT085 Fo21, s. 7–9; Canvas, 05142_10 (Osswald kap. 10), s. 8–10$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('be773bde-4bcc-5819-b78b-8d95772a2130', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-halsbildning-molekylmodell$kuggfri$, $kuggfri$Beskriv vad som händer i molekylstrukturen vid halsbildning i en delkristallin polymer.$kuggfri$, $kuggfri$Under halsbildningen och kalldragningen deformeras sfärulitstrukturen och bryts upp, så att starkt orienterade områden bildas. I molekylmodellen ingår:

- De amorfa banden mellan lamellerna sträcks ut helt, vilket gör att lamellerna glider och vrids i förhållande till varandra (slip-tilt).
- Vid fortsatt dragning ordnas lamellfragment i dragriktningen och bildar fibriller av omväxlande kristallina block och sträckta amorfa områden.$kuggfri$, null, 349, false, $kuggfri$c0adae309$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, 2025 MTT085 Fo21, s. 13–14; Canvas, MTT085 Polymeric materials L6, s. 9–10; Canvas, 05142_10 (Osswald kap. 10), s. 14–15$kuggfri$, false);
insert into public.cards (id, deck_id, category_id, key, front, back, hint, sort_order, is_active, source_hash, kind, options, review_status, source, original) values ('24ff24fb-975d-5da9-821d-f0cc7cc74d12', '1fd9bb0d-b779-540f-bbbd-604e02cdaf6b', '93859c85-44c9-5113-879e-3dab2f92f3df', $kuggfri$polymer-isokront-diagram-dimensionering$kuggfri$, $kuggfri$Hur används ett isokront spännings-töjningsdiagram vid dimensionering av en plastdetalj?$kuggfri$, $kuggfri$Varje isokron kurva gäller en viss belastningstid, och diagrammet gäller den temperatur som krypproven gjordes vid. Välj kurvan för produktens livslängd, t.ex. 1 år. Gå in med spänningen på y-axeln och läs av vilken töjning detaljen har fått efter krypning under den tiden; jämför med den tillåtna töjningen. Omvänt ger en största tillåten töjning den största tillåtna spänningen.$kuggfri$, null, 350, false, $kuggfri$cf72b6d82$kuggfri$, $kuggfri$sjalvskattning$kuggfri$, null, $kuggfri$utkast$kuggfri$, $kuggfri$Canvas, MTT085 Polymeric materials L6, s. 6–7; Canvas, 2025 MTT085 Fo20, s. 20$kuggfri$, false);

commit;
